window.__BOOK__ = {"meta": {"title_it": "Il Piccolo Principe", "title_zh": "小王子", "author_it": "Antoine de Saint-Exupéry", "author_zh": "安托万·德·圣埃克苏佩里", "voice": "it-IT-ElsaNeural (edge-tts)", "ipa_note": "音标为宽式音位转写，仅供参考；重音未标注。", "n_chapters": 28, "n_paras": 738, "n_sents": 1574, "audio_paras": 738}, "chapters": [{"id": "ch00", "title_it": "A LÉON WERTH", "title_zh": "献词", "paras": [{"id": "ch00p00", "audio": true, "sents": [{"it": "Chiedo scusa ai bambini per aver dedicato questo libro a un adulto.", "zh": "请孩子们原谅我把这本书献给一位大人。", "t": [100, 4112]}, {"it": "Ho un buon motivo: questo adulto è il migliore amico che ho al mondo.", "zh": "我有这样做的充分理由：这位大人是我最要好的朋友。", "t": [4112, 8012]}, {"it": "Ho un altro motivo: questo adulto può capire tutto, anche i libri per bambini.", "zh": "我还有另一个理由：这位大人什么都懂，他完全能理解写给孩子们阅读的书籍。", "t": [8012, 13125]}, {"it": "Ho un terzo motivo: questo adulto abita in Francia, dove ha fame e freddo.", "zh": "我还有第三个理由：这位大人住在法国，正在忍饥挨饿，他需要别人的安慰。", "t": [13125, 18500]}, {"it": "Ha un gran bisogno di essere consolato.", "zh": "我还有第三个理由：这位大人住在法国，正在忍饥挨饿，他需要别人的安慰。", "t": [18500, 20888]}, {"it": "Se tutti questi motivi non bastano, voglio dedicare il libro al bambino che questo adulto è stato molto tempo fa.", "zh": "要是你们认为这些理由还不充分，那我就把这本书献给小时候的他吧——所有的大人都经历过童年。", "t": [20888, 27488]}, {"it": "Tutti gli adulti sono stati prima di tutto dei bambini.", "zh": "（但很少有大人记得自己曾是孩子。", "t": [27488, 30925]}, {"it": "(Ma pochi di loro se lo ricordano.) Quindi correggo la mia dedica: QUANDO ERA BAMBINO", "zh": "）因此，我把我的献辞改为： 献给从前那个小男孩列翁·维尔特。", "t": [30925, 36350]}]}]}, {"id": "ch01", "title_it": "I", "title_zh": "第 1 章", "paras": [{"id": "ch01p00", "audio": true, "sents": [{"it": "Una volta, quando avevo sei anni, in un libro sulla foresta vergine intitolato Storie vissute ho visto un’illustrazione bellissima.", "zh": "六岁那一年，我在一本描写原始森林的书里看见一幅扣人心弦的图画。", "t": [100, 8050]}, {"it": "Raffigurava un serpente boa che divora una belva.", "zh": "图中画的是正在吞吃野兽的蟒蛇。", "t": [8050, 11162]}, {"it": "Questa è una riproduzione del disegno.", "zh": "下面是这幅画的复印件。", "t": [11162, 13263]}]}, {"id": "ch01p01", "audio": true, "sents": [{"it": "Il libro diceva: “I serpenti boa divorano la preda tut­t’in­tera senza masticarla.", "zh": "书中说：“蟒蛇囫囵吞下猎物，肚子撑得它不能动弹，要躺六个月才能把猎物消化掉。", "t": [100, 5362]}, {"it": "Dopo non riescono più a muoversi e passano i sei mesi della digestione dormendo”.", "zh": "书中说：“蟒蛇囫囵吞下猎物，肚子撑得它不能动弹，要躺六个月才能把猎物消化掉。", "t": [5362, 10225]}]}, {"id": "ch01p02", "audio": true, "sents": [{"it": "Allora ho pensato molto alle avventure della giungla e con una matita colorata sono riuscito anch’io a fare il mio primo disegno.", "zh": "我也用彩色铅笔绘下我的第一幅画。", "t": [100, 6750]}, {"it": "Il mio disegno numero 1.", "zh": "我称它为一号画。", "t": [6750, 8438]}, {"it": "Era così:", "zh": "一号画如下： 我把我的杰作拿给大人看，还问他们，我的画是否吓坏了他们。", "t": [8438, 9162]}]}, {"id": "ch01p03", "audio": true, "sents": [{"it": "Ho mostrato il mio capolavoro agli adulti e ho chiesto se era un disegno che faceva paura.", "zh": "一号画如下： 我把我的杰作拿给大人看，还问他们，我的画是否吓坏了他们。", "t": [100, 4937]}]}, {"id": "ch01p04", "audio": true, "sents": [{"it": "Tutti mi hanno risposto: “E perché mai un cappello dovrebbe fare paura?”.", "zh": "他们回答我说：“一顶帽子有什么可怕的？", "t": [100, 4025]}]}, {"id": "ch01p05", "audio": true, "sents": [{"it": "Il mio disegno non raffigurava un cappello.", "zh": "” 我画的不是一顶帽子，而是一条正在消化大象的蟒蛇啊。", "t": [100, 2688]}, {"it": "Raffigurava un serpente boa che digerisce un elefante.", "zh": "我又画了一张画，画的是蟒蛇和它肚子里的大象，好让大人看懂我的画。", "t": [2688, 6125]}, {"it": "Allora ho disegnato l’interno del serpente boa, in modo che gli adulti potessero capire.", "zh": "我又画了一张画，画的是蟒蛇和它肚子里的大象，好让大人看懂我的画。", "t": [6125, 11362]}, {"it": "Hanno sempre bisogno di spiegazioni.", "zh": "他们总是需要我们给他们解释的。", "t": [11362, 13750]}, {"it": "Il mio disegno numero 2 era così:", "zh": "他们总是需要我们给他们解释的。", "t": [13750, 15700]}]}, {"id": "ch01p06", "audio": true, "sents": [{"it": "Gli adulti mi hanno consigliato di lasciar perdere i disegni di serpenti boa aperti o chiusi e di interessarmi invece alla geografia, alla storia, all’aritmetica e alla grammatica.", "zh": "我的二号画如下： 大人们劝我，别画这些肚子没打开或打开了的蟒蛇了，把心思放到地理、历史、算术、语法上去吧。", "t": [100, 10712]}, {"it": "È stato così che, all’età di sei anni, ho rinunciato a una brillante carriera di pittore, scoraggiato dall’insuccesso dei miei disegni numero 1 e numero 2.", "zh": "一号画、二号画的失败令我垂头丧气。", "t": [10712, 19850]}, {"it": "Gli adulti da soli non capiscono niente, ed è stancante per i bambini dover sempre spiegare tutto...", "zh": "我只好选择另一门职业。", "t": [19850, 26150]}]}, {"id": "ch01p07", "audio": true, "sents": [{"it": "Perciò ho dovuto scegliermi un altro lavoro e ho imparato a pilotare gli aerei.", "zh": "地理确实帮了我的大忙。", "t": [100, 4550]}, {"it": "Ho volato un po’ in giro per il mondo.", "zh": "地理确实帮了我的大忙。", "t": [4550, 6612]}, {"it": "E in effetti la geografia mi è stata utile.", "zh": "在空中，我一眼就能认出中国和亚利桑那 [1] ，这样的本领很管用——如果夜航时迷了路。", "t": [6612, 9250]}, {"it": "Sapevo distinguere al primo colpo d’occhio la Cina dall’Arizona.", "zh": "在空中，我一眼就能认出中国和亚利桑那 [1] ，这样的本领很管用——如果夜航时迷了路。", "t": [9250, 12962]}, {"it": "Torna comodo, se ti sei perso in piena notte.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [12962, 15700]}]}, {"id": "ch01p08", "audio": true, "sents": [{"it": "Così nella vita ho conosciuto molte persone serie.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [100, 3162]}, {"it": "Ho frequentato parecchio gli adulti.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [3162, 5325]}, {"it": "Li ho visti proprio da vicino.", "zh": "我始终保留着我的一号画。", "t": [5325, 7238]}, {"it": "E la mia opinione non è cambiata.", "zh": "我始终保留着我的一号画。", "t": [7238, 9288]}, {"it": "Quando ne incontravo uno che mi sembrava abbastanza sveglio, facevo l’esperimento del mio disegno numero 1, che conservo ancora.", "zh": "遇到一个我认为略为懂事的大人，我就用这幅画做试验，看他是否真的懂事，但他们总是这样回答我：“这是一顶帽子。", "t": [9288, 16762]}, {"it": "Volevo capire se era davvero veloce di comprendonio.", "zh": "遇到一个我认为略为懂事的大人，我就用这幅画做试验，看他是否真的懂事，但他们总是这样回答我：“这是一顶帽子。", "t": [16762, 19962]}, {"it": "Ma tutti, invariabilmente, rispondevano: “È un cappello”.", "zh": "”听了这样的话，我就不再与他们谈蟒蛇、原始森林、星星了。", "t": [19962, 24562]}, {"it": "Allora lasciavo perdere i serpenti boa, le foreste vergini e le stelle.", "zh": "我谈他们能理解的事情，例如桥牌啦，高尔夫球啦，政治啦，领带啦。", "t": [24562, 28988]}, {"it": "Mi mettevo al suo livello.", "zh": "我谈他们能理解的事情，例如桥牌啦，高尔夫球啦，政治啦，领带啦。", "t": [28988, 30638]}, {"it": "Gli parlavo di bridge, di golf, di politica e di cravatte.", "zh": "我谈他们能理解的事情，例如桥牌啦，高尔夫球啦，政治啦，领带啦。", "t": [30638, 34575]}, {"it": "E l’adulto era felicissimo di conoscere un uomo tanto ragionevole...", "zh": "大人们便很满意，以为他们认识了一个通情达理、善解人意的人。", "t": [34575, 38224]}]}]}, {"id": "ch02", "title_it": "II", "title_zh": "第 2 章", "paras": [{"id": "ch02p00", "audio": true, "sents": [{"it": "Così ho vissuto solo, senza nessuno con cui poter veramente parlare, finché sei anni fa non ho avuto un incidente nel deserto del Sahara.", "zh": "这种状况一直延续至六年前。", "t": [100, 8125]}, {"it": "Si era rotto qualcosa nel motore.", "zh": "六年前，我的飞机出了故障，发动机里的某个部件被撞坏了，我被迫在撒哈拉沙漠降落。", "t": [8125, 10300]}, {"it": "E siccome non avevo con me né un meccanico né passeggeri, decisi di riparare da solo quel brutto guasto.", "zh": "身边没有机械师，没有一个乘客，我只好勉为其难，自己动手，试着修理部件。", "t": [10300, 16375]}, {"it": "Era una questione di vita o di morte.", "zh": "身边没有机械师，没有一个乘客，我只好勉为其难，自己动手，试着修理部件。", "t": [16375, 18725]}, {"it": "Avevo scorte di acqua solo per otto giorni.", "zh": "我带的水仅够喝一个星期，能否修好飞机，关系到我的生死存亡了。", "t": [18725, 21087]}]}, {"id": "ch02p01", "audio": true, "sents": [{"it": "Perciò la prima sera mi sono addormentato sulla sabbia, a mille miglia da qualsiasi luogo abitato.", "zh": "我带的水仅够喝一个星期，能否修好飞机，关系到我的生死存亡了。", "t": [100, 5875]}, {"it": "Ero più isolato di un naufrago su una zattera in mezzo all’oceano.", "zh": "比起那些乘着木排，在茫茫大洋中挣扎漂浮的遇险者，我更显得孤独无助。", "t": [5875, 10050]}, {"it": "Potete quindi immaginare la mia sorpresa quando, sul far del giorno, sono stato svegliato da una vocina che diceva:", "zh": "朝霞初露的时候，一个细细的奇妙的声音把我唤醒。", "t": [10050, 16775]}]}, {"id": "ch02p02", "audio": true, "sents": [{"it": "“Per favore...", "zh": "你不难想像我当时有多惊讶了。", "t": [100, 1112]}, {"it": "disegnami una pecora!”", "zh": "你不难想像我当时有多惊讶了。", "t": [1112, 2550]}]}, {"id": "ch02p03", "audio": true, "sents": [{"it": "“Eh?”", "zh": "你不难想像我当时有多惊讶了。", "t": [100, 450]}]}, {"id": "ch02p04", "audio": true, "sents": [{"it": "“Disegnami una pecora...”", "zh": "你不难想像我当时有多惊讶了。", "t": [100, 1562]}]}, {"id": "ch02p05", "audio": true, "sents": [{"it": "Sono balzato in piedi come se fossi stato colpito da un fulmine.", "zh": "这细细的奇妙的声音说： “劳驾……请你给我画一只绵羊吧！", "t": [100, 4138]}, {"it": "Mi sono sfregato gli occhi.", "zh": "” “你说什么？", "t": [4138, 5938]}, {"it": "Ho guardato bene.", "zh": "” “你说什么？", "t": [5938, 7175]}, {"it": "E ho visto uno stranissimo ometto che mi fissava con aria seria.", "zh": "” “给我画一只绵羊……” 我像遭了雷击，一跃而起。", "t": [7175, 10875]}, {"it": "Questo è il ritratto migliore che poi sono riuscito a farne.", "zh": "我使劲揉我的眼睛，仔细地看了看，只见一个很奇特的小小的人儿，他正在那儿注视我呢。", "t": [10875, 14238]}]}, {"id": "ch02p06", "audio": true, "sents": [{"it": "Ma ovviamente il mio disegno è molto meno bello dell’originale.", "zh": "我使劲揉我的眼睛，仔细地看了看，只见一个很奇特的小小的人儿，他正在那儿注视我呢。", "t": [100, 3900]}, {"it": "Non è colpa mia.", "zh": "下面就是以后我给他画的最为成功的一幅肖像画。", "t": [3900, 5225]}, {"it": "Quando avevo sei anni gli adulti mi avevano dissuaso dall’intraprendere la carriera di pittore, perciò non sapevo disegnare altro che i boa chiusi e i boa aperti.", "zh": "当然，它没有他本人可爱俊美，这可不能怪我，该怪大人，是他们在我六岁那年葬送了我的画家生涯。", "t": [5225, 13837]}]}, {"id": "ch02p07", "audio": true, "sents": [{"it": "Guardai quindi quell’apparizione con gli occhi sbarrati dallo stupore.", "zh": "除了画打开肚子和没打开肚子的蟒蛇之外，我没有画过一张画。", "t": [100, 4038]}, {"it": "Tenete presente che, come ho detto, mi trovavo a mille miglia da qualunque terra abitata.", "zh": "我大吃一惊，眼睛瞪得溜圆，看着这位突然出现的人儿。", "t": [4038, 9488]}, {"it": "E quell’ometto non sembrava essersi perso, né essere morto di stanchezza, né morto di fame, né morto di sete, né morto di paura.", "zh": "你们可别忘了，这儿是远离人烟、千里之遥的地方啊。", "t": [9488, 18012]}, {"it": "Non aveva proprio l’aria di un bambino perso nel deserto, a mille miglia da qualsiasi terra abitata.", "zh": "他一点不像迷失于沙漠中的孩子，不像远离人烟、千里之遥的孩子。", "t": [18012, 23850]}, {"it": "Quando finalmente riuscii a parlare, gli dissi:", "zh": "他一点不像迷失于沙漠中的孩子，不像远离人烟、千里之遥的孩子。", "t": [23850, 26850]}]}, {"id": "ch02p08", "audio": true, "sents": [{"it": "“Ma...", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [100, 750]}, {"it": "Che ci fai tu qui?”", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [750, 1688]}]}, {"id": "ch02p09", "audio": true, "sents": [{"it": "E allora mi ripeté piano, come fosse una cosa della massima importanza:", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [100, 4212]}]}, {"id": "ch02p10", "audio": true, "sents": [{"it": "“Per favore...", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [100, 1112]}, {"it": "disegnami una pecora...”", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [1112, 2537]}]}, {"id": "ch02p11", "audio": true, "sents": [{"it": "Dinanzi a un mistero assoluto, nessuno ha il coraggio di disobbedire.", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [100, 4450]}, {"it": "Benché lì, a mille miglia da qualsiasi luogo abitato e in pericolo di morte, mi sembrasse una cosa del tutto strampalata, tirai fuori dalla tasca un foglio di carta e una stilografica.", "zh": "虽然，身处远离人烟的荒漠，面临死亡的威胁，叫人画画的要求又未免荒堂，我还是从口袋里掏出一张纸和一枝钢笔。", "t": [4450, 15588]}, {"it": "Ma allora mi ricordai che avevo studiato soprattutto la geografia, la storia, l’aritmetica e la grammatica e (con un certo malumore) dissi all’ometto che non sapevo disegnare.", "zh": "我忽然记起，除了钻研地理、历史、算术、语法，我没有画过画，便没好气地冲小人儿说，我不会画画。", "t": [15588, 26475]}, {"it": "Lui mi rispose:", "zh": "他说：“不要紧，给我画一只绵羊吧。", "t": [26475, 27587]}]}, {"id": "ch02p12", "audio": true, "sents": [{"it": "“Non importa.", "zh": "他说：“不要紧，给我画一只绵羊吧。", "t": [100, 1250]}, {"it": "Disegnami una pecora.”", "zh": "” 我从没画过绵羊，只画过那两张画。", "t": [1250, 2650]}]}, {"id": "ch02p13", "audio": true, "sents": [{"it": "Siccome non avevo mai disegnato una pecora, rifeci per lui uno degli unici due disegni che sapevo fare.", "zh": "我就给他画了其中的一张，就是没有打开肚子的蟒蛇。", "t": [100, 6450]}, {"it": "Quello del boa chiuso.", "zh": "我吓了一跳，我听见小人儿说： “不！", "t": [6450, 7900]}, {"it": "E con mio grande stupore udii l’ometto rispondermi:", "zh": "不！", "t": [7900, 10787]}]}, {"id": "ch02p14", "audio": true, "sents": [{"it": "“No, no, non voglio un elefante dentro un boa.", "zh": "我不要象在蟒蛇的肚子里。", "t": [100, 3600]}, {"it": "Il boa è pericolosissimo e l’elefante è troppo grosso.", "zh": "我的家地方不大。", "t": [3600, 7262]}, {"it": "Il posto dove sto io è molto piccolo.", "zh": "我要绵羊，给我画一只绵羊吧。", "t": [7262, 9788]}, {"it": "Mi serve una pecora.", "zh": "” 我便画了一头羊。", "t": [9788, 11312]}, {"it": "Disegnami una pecora.”", "zh": "他仔细看看，然后说： “不好！", "t": [11312, 12713]}]}, {"id": "ch02p15", "audio": true, "sents": [{"it": "Allora disegnai.", "zh": "他仔细看看，然后说： “不好！", "t": [100, 1187]}]}, {"id": "ch02p16", "audio": true, "sents": [{"it": "Lui guardò attentamente e poi:", "zh": "这是一头患了重病的羊。", "t": [100, 2013]}]}, {"id": "ch02p17", "audio": true, "sents": [{"it": "“No!", "zh": "这是一头患了重病的羊。", "t": [100, 788]}, {"it": "Questa è troppo malconcia.", "zh": "给我画另一头吧。", "t": [788, 2525]}, {"it": "Fanne un’altra.”", "zh": "” 我又画了一只羊。", "t": [2525, 3488]}]}, {"id": "ch02p18", "audio": true, "sents": [{"it": "Disegnai.", "zh": "” 我又画了一只羊。", "t": [100, 975]}]}, {"id": "ch02p19", "audio": true, "sents": [{"it": "Il mio amico fece un sorriso bonario e disse, paziente:", "zh": "” 我又画了一只羊。", "t": [100, 3675]}]}, {"id": "ch02p20", "audio": true, "sents": [{"it": "“Ma no, lo vedi anche tu che non è una pecora, ma un ariete.", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [100, 4225]}, {"it": "Ha le corna...”", "zh": "” 我又画了一张。", "t": [4225, 4950]}]}, {"id": "ch02p21", "audio": true, "sents": [{"it": "Allora rifeci un’altra volta il disegno:", "zh": "” 我又画了一张。", "t": [100, 2375]}]}, {"id": "ch02p22", "audio": true, "sents": [{"it": "Ma, come i precedenti, fu rifiutato:", "zh": "” 我又画了一张。", "t": [100, 3112]}]}, {"id": "ch02p23", "audio": true, "sents": [{"it": "“Questa è troppo vecchia.", "zh": "这一张画和前面两张一样，遭到了他的拒绝： “这只太老了，我要一只能活很久的绵羊。", "t": [100, 1612]}, {"it": "Voglio una pecora che viva a lungo.”", "zh": "这一张画和前面两张一样，遭到了他的拒绝： “这只太老了，我要一只能活很久的绵羊。", "t": [1612, 3500]}]}, {"id": "ch02p24", "audio": true, "sents": [{"it": "Poiché cominciavo a perdere la pazienza, e avevo fretta di smontare il motore, scarabocchiai questo disegno:", "zh": "” 我急于着手拆卸我的发动机，失去了耐性。", "t": [100, 6325]}]}, {"id": "ch02p25", "audio": true, "sents": [{"it": "E dissi:", "zh": "我胡乱涂了下面这幅画。", "t": [100, 800]}]}, {"id": "ch02p26", "audio": true, "sents": [{"it": "“Questa è la cassa.", "zh": "我胡乱涂了下面这幅画。", "t": [100, 1412]}, {"it": "E dentro c’è la pecora che vuoi tu.”", "zh": "而且我冲他说： “这是一只箱子，你要的绵羊在里面。", "t": [1412, 3237]}]}, {"id": "ch02p27", "audio": true, "sents": [{"it": "Quale non fu il mio stupore nel vedere il viso del mio giovane giudice illuminarsi:", "zh": "” 然而我惊讶地看到，我的这位小法官竟眉开眼笑： “我要的正是这样的箱子！", "t": [100, 4400]}]}, {"id": "ch02p28", "audio": true, "sents": [{"it": "“Ah, è proprio come la volevo!", "zh": "” 然而我惊讶地看到，我的这位小法官竟眉开眼笑： “我要的正是这样的箱子！", "t": [100, 2112]}, {"it": "Pensi che a questa pecora occorra tanta erba?”", "zh": "这只绵羊要很多草吗？", "t": [2112, 4450]}]}, {"id": "ch02p29", "audio": true, "sents": [{"it": "“Perché?”", "zh": "” “为什么你提这个问题？", "t": [100, 588]}]}, {"id": "ch02p30", "audio": true, "sents": [{"it": "“Perché il posto dove sto io è molto piccolo...”", "zh": "” “为什么你提这个问题？", "t": [100, 2525]}]}, {"id": "ch02p31", "audio": true, "sents": [{"it": "“Sarà più che sufficiente.", "zh": "” “因为我的家太小啦……” “肯定够了。", "t": [100, 1812]}, {"it": "Ti ho dato una pecora piccola piccola.”", "zh": "我给你的是一只很小很小的绵羊。", "t": [1812, 3750]}]}, {"id": "ch02p32", "audio": true, "sents": [{"it": "Chinò il capo verso il disegno:", "zh": "” 他低头看画。", "t": [100, 1800]}]}, {"id": "ch02p33", "audio": true, "sents": [{"it": "“Mica tanto piccola...", "zh": "” 他低头看画。", "t": [100, 1662]}, {"it": "Guarda!", "zh": "“没有这个这么小吧……咦！", "t": [1662, 2500]}, {"it": "Si è addormentata...”", "zh": "“没有这个这么小吧……咦！", "t": [2500, 3775]}]}, {"id": "ch02p34", "audio": true, "sents": [{"it": "E fu così che feci la conoscenza del piccolo principe.", "zh": "它睡熟了……” 我就这样认识了小王子。", "t": [100, 3338]}]}]}, {"id": "ch03", "title_it": "III", "title_zh": "第 3 章", "paras": [{"id": "ch03p00", "audio": true, "sents": [{"it": "Mi ci volle un bel po’ di tempo per capire da dove veniva.", "zh": "过了好久好久，我才弄明白他是打哪儿来的。", "t": [100, 3438]}, {"it": "Il piccolo principe mi faceva moltissime domande, ma sembrava non ascoltare mai quelle che gli facevo io.", "zh": "小王子向我提了许多问题，却从不理会我对他提的问题。", "t": [3438, 9662]}, {"it": "Solo alcune parole dette per caso mi hanno pian piano rivelato tutto.", "zh": "我从他无意中吐出的片言只语里，逐渐知道了他的来历。", "t": [9662, 13638]}, {"it": "Così, quando vide per la prima volta il mio aereo (non lo disegno, è troppo difficile per me), mi domandò:", "zh": "例如，当他第一次看见我的飞机的时候（我不愿画飞机，太复杂了），就问我： “这是什么玩艺儿呀？", "t": [13638, 19913]}]}, {"id": "ch03p01", "audio": true, "sents": [{"it": "“Che roba è?”", "zh": "” “它不是玩艺儿，它会飞。", "t": [100, 688]}]}, {"id": "ch03p02", "audio": true, "sents": [{"it": "“Non è una roba.", "zh": "这是飞机，是我的飞机。", "t": [100, 1388]}, {"it": "Vola, è un aereo.", "zh": "这是飞机，是我的飞机。", "t": [1388, 3350]}, {"it": "Il mio aereo.”", "zh": "” 我挺自豪地告诉他我会飞。", "t": [3350, 4200]}]}, {"id": "ch03p03", "audio": true, "sents": [{"it": "Ed ero orgoglioso di fargli sapere che volavo.", "zh": "” 我挺自豪地告诉他我会飞。", "t": [100, 2750]}, {"it": "Allora esclamò:", "zh": "他嚷起来： “怎么？", "t": [2750, 3750]}]}, {"id": "ch03p04", "audio": true, "sents": [{"it": "“Ma come!", "zh": "你是从天上掉下来的吗？", "t": [100, 1075]}, {"it": "Sei caduto dal cielo?”", "zh": "你是从天上掉下来的吗？", "t": [1075, 2250]}]}, {"id": "ch03p05", "audio": true, "sents": [{"it": "“Sì,” feci io con modestia.", "zh": "”我并没有吹嘘的意思。", "t": [100, 1813]}]}, {"id": "ch03p06", "audio": true, "sents": [{"it": "“Ah, questa sì che è bella!...”", "zh": "“啊！", "t": [100, 1813]}]}, {"id": "ch03p07", "audio": true, "sents": [{"it": "E il piccolo principe scoppiò in una gran risata che mi irritò molto.", "zh": "这就奇了……” 小王子发出清脆悦耳的笑声，他这一笑可惹恼了我。", "t": [100, 4275]}, {"it": "Voglio che si prendano sul serio le mie disgrazie.", "zh": "我不喜欢别人对我的不幸打哈哈。", "t": [4275, 7188]}, {"it": "Poi aggiunse:", "zh": "然后他又说： “这么说，你也是从天上下来的！", "t": [7188, 8113]}]}, {"id": "ch03p08", "audio": true, "sents": [{"it": "“Allora vieni anche tu dal cielo?", "zh": "然后他又说： “这么说，你也是从天上下来的！", "t": [100, 1950]}, {"it": "Di che pianeta sei?”", "zh": "你住在哪一个星球上？", "t": [1950, 3200]}]}, {"id": "ch03p09", "audio": true, "sents": [{"it": "Di colpo scorsi una luce nel mistero della sua presenza, e subito gli domandai:", "zh": "” 这句话犹如一道亮光，让我马上瞥见了他突然出现的秘密。", "t": [100, 4800]}]}, {"id": "ch03p10", "audio": true, "sents": [{"it": "“Quindi vieni da un altro pianeta?”", "zh": "我以突袭的方式问他： “你是从另一个星球来的？", "t": [100, 1900]}]}, {"id": "ch03p11", "audio": true, "sents": [{"it": "Ma non mi rispose.", "zh": "我以突袭的方式问他： “你是从另一个星球来的？", "t": [100, 1450]}, {"it": "Guardava l’aereo scuotendo piano la testa:", "zh": "” 他不答。", "t": [1450, 3825]}]}, {"id": "ch03p12", "audio": true, "sents": [{"it": "“In effetti con quest’affare non puoi venire da molto lontano...”", "zh": "他看着我的飞机，轻轻地点头： “从你乘的这玩艺来看，你确实不可能来自很远的地方……” 他陷入沉思。", "t": [100, 3350]}]}, {"id": "ch03p13", "audio": true, "sents": [{"it": "E restò a lungo come trasognato.", "zh": "他看着我的飞机，轻轻地点头： “从你乘的这玩艺来看，你确实不可能来自很远的地方……” 他陷入沉思。", "t": [100, 2375]}, {"it": "Poi tirò fuori dalla tasca la mia pecora e si immerse nella contemplazione del suo tesoro.", "zh": "过了很久，他从口袋里掏出我画的绵羊，低头凝视他的宝贝。", "t": [2375, 7650]}]}, {"id": "ch03p14", "audio": true, "sents": [{"it": "Potete ben immaginare quanto mi incuriosisse quella mezza confidenza sugli “altri pianeti”.", "zh": "你们不难想像，听了他那句无意透露的“其他星球”的话后，我会怎样惊讶吧。", "t": [100, 5188]}, {"it": "Cercai quindi di saperne di più:", "zh": "你们不难想像，听了他那句无意透露的“其他星球”的话后，我会怎样惊讶吧。", "t": [5188, 7087]}]}, {"id": "ch03p15", "audio": true, "sents": [{"it": "“Da dove vieni, ometto?", "zh": "我竭力从中探听他的来历： “我的小人儿，你从哪儿来？", "t": [100, 2050]}, {"it": "Qual è il posto dove stai?", "zh": "我竭力从中探听他的来历： “我的小人儿，你从哪儿来？", "t": [2050, 3762]}, {"it": "Dove la vuoi portare la mia pecora?”", "zh": "你的家在哪儿？", "t": [3762, 5576]}]}, {"id": "ch03p16", "audio": true, "sents": [{"it": "Dopo un silenzio pensoso mi rispose:", "zh": "你要把你的绵羊牵到哪儿去？", "t": [100, 2437]}]}, {"id": "ch03p17", "audio": true, "sents": [{"it": "“C’è di buono che la cassa che mi hai dato di notte potrà farle da casa.”", "zh": "然后才说： “你给了我一个箱子，太好了。", "t": [100, 3825]}]}, {"id": "ch03p18", "audio": true, "sents": [{"it": "“Certo.", "zh": "夜里可以给绵羊做屋子了。", "t": [100, 1025]}, {"it": "E se fai il bravo ti darò anche una corda per legarla durante il giorno.", "zh": "夜里可以给绵羊做屋子了。", "t": [1025, 5162]}, {"it": "E un paletto.”", "zh": "” “是呀，如果你乖，我还要给你一根绳子，白天给你拴羊用。", "t": [5162, 6088]}]}, {"id": "ch03p19", "audio": true, "sents": [{"it": "Il piccolo principe sembrò scioccato dalla proposta:", "zh": "我还要给你一根拴羊的桩。", "t": [100, 3163]}]}, {"id": "ch03p20", "audio": true, "sents": [{"it": "“Legarla?", "zh": "我还要给你一根拴羊的桩。", "t": [100, 1100]}, {"it": "Che idea assurda!”", "zh": "” 我的建议显然惹恼了小王子： “拴住它？", "t": [1100, 2250]}]}, {"id": "ch03p21", "audio": true, "sents": [{"it": "“Ma se non la leghi se ne andrà in giro chissà dove e si perderà.”", "zh": "亏你想得出这样的主意！", "t": [100, 3700]}]}, {"id": "ch03p22", "audio": true, "sents": [{"it": "E di nuovo il mio amico scoppiò a ridere:", "zh": "” “你不拴住它，它会乱跑的呀，会走失的呀。", "t": [100, 2213]}]}, {"id": "ch03p23", "audio": true, "sents": [{"it": "“Ma dove vuoi che vada?!”", "zh": "” “你不拴住它，它会乱跑的呀，会走失的呀。", "t": [100, 1312]}]}, {"id": "ch03p24", "audio": true, "sents": [{"it": "“Dove capita, prenderà la prima direzione che trova.”", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [100, 3226]}]}, {"id": "ch03p25", "audio": true, "sents": [{"it": "Allora il piccolo principe osservò, con aria seria:", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [100, 3326]}]}, {"id": "ch03p26", "audio": true, "sents": [{"it": "“Non importa, dove sto io è talmente piccolo!”", "zh": "” “到处乱跑呗，朝前跑呗……” 小王子告诉我： “这倒不成问题，我的家小得很呢！", "t": [100, 3000]}]}, {"id": "ch03p27", "audio": true, "sents": [{"it": "E aggiunse, forse con un’ombra di malinconia:", "zh": "” “到处乱跑呗，朝前跑呗……” 小王子告诉我： “这倒不成问题，我的家小得很呢！", "t": [100, 2900]}]}, {"id": "ch03p28", "audio": true, "sents": [{"it": "“Qualunque direzione si prende, non si può andare molto lontano...”", "zh": "” 他的神色略带忧伤，说： “朝前跑，也跑不了多远……”", "t": [100, 3826]}]}]}, {"id": "ch04", "title_it": "IV", "title_zh": "第 4 章", "paras": [{"id": "ch04p00", "audio": true, "sents": [{"it": "Così avevo scoperto un’altra cosa molto importante: il pianeta da cui proveniva era poco più grande di una casa!", "zh": "就这样，我知道了第二件很重要的事情：他打那儿来的星球比一幢房子大不了多少！", "t": [100, 6413]}]}, {"id": "ch04p01", "audio": true, "sents": [{"it": "Non mi stupiva.", "zh": "我并不因此大惊小怪。", "t": [100, 1338]}, {"it": "Sapevo che oltre ai pianeti maggiori come la Terra, Giove, Marte, Venere, a cui abbiamo dato dei nomi, ne esistono centinaia di altri che a volte sono così piccoli che quasi non si riesce neppure a vederli con il telescopio.", "zh": "有些星球小到连望远镜都难以观测。", "t": [1338, 15575]}, {"it": "Quando un astronomo ne scopre uno, lo designa con un numero.", "zh": "我有充分的证据认为小王子打那儿来的星球就是B612号小行星。", "t": [15575, 19288]}, {"it": "Per esempio: “asteroide 325”.", "zh": "我有充分的证据认为小王子打那儿来的星球就是B612号小行星。", "t": [19288, 22450]}]}, {"id": "ch04p02", "audio": true, "sents": [{"it": "Ho buoni motivi per credere che il pianeta da cui veniva il piccolo principe fosse l’asteroide B 612.", "zh": "这颗小行星仅仅在一九〇九年被一位土耳其天文学家用望远镜看见过一回。", "t": [100, 5175]}, {"it": "Questo asteroide è stato intravisto solo una volta, con il telescopio, nel 1909, da un astronomo turco.", "zh": "在国际天文会议上，他为他的发现做了雄辩的论证，但没有人相信他的报告。", "t": [5175, 14563]}]}, {"id": "ch04p03", "audio": true, "sents": [{"it": "Lo scienziato aveva presentato la sua scoperta a un congresso internazionale di astronomia.", "zh": "因为他穿的是土耳其人的服装。", "t": [100, 5512]}, {"it": "Ma nessuno gli aveva creduto, per via del modo in cui era vestito.", "zh": "幸好，为了维护B612小行星的声誉，土耳其独裁者颁布了一条法令，命令百姓改穿欧式服装，否则处以死刑。", "t": [5512, 9675]}, {"it": "Gli adulti sono fatti così.", "zh": "幸好，为了维护B612小行星的声誉，土耳其独裁者颁布了一条法令，命令百姓改穿欧式服装，否则处以死刑。", "t": [9675, 11350]}]}, {"id": "ch04p04", "audio": true, "sents": [{"it": "Fu una vera fortuna, per la reputazione dell’asteroide B 612, quando un dittatore turco impose al proprio popolo, pena la morte, di vestirsi all’europea.", "zh": "一九二〇年，这位土耳其天文学家身穿一套极考究的西服，再一次在国际会议上做了论证。", "t": [100, 11700]}, {"it": "L’astronomo rifece la presentazione nel 1920, vestito con un completo elegante.", "zh": "这一回，他得到了大家的认可。", "t": [11700, 16950]}, {"it": "E stavolta tutti gli diedero retta.", "zh": "我对你们详细报告发现小行星B612的这些细节，把它的号码告诉你们，都是由于那些大人们的缘故。", "t": [16950, 18924]}]}, {"id": "ch04p05", "audio": true, "sents": [{"it": "Vi ho raccontato questi particolari sull’asteroide B 612 e vi ho rivelato il suo numero a causa degli adulti.", "zh": "因为大人们对数字情有独钟。", "t": [100, 6962]}, {"it": "Agli adulti piacciono i numeri.", "zh": "因为大人们对数字情有独钟。", "t": [6962, 8875]}, {"it": "Quando raccontate loro di un nuovo amico, non vi chiedono mai le cose importanti.", "zh": "如果你对他们介绍一个新朋友，他们从不打听他的基本情况，他们从不会问你：“他的嗓子怎么样？", "t": [8875, 13538]}, {"it": "Non vi dicono: “Com’è il suono della sua voce?", "zh": "他喜欢玩什么游戏？", "t": [13538, 16612]}, {"it": "Quali sono i suoi giochi preferiti?", "zh": "他是否采集蝴蝶标本？", "t": [16612, 18812]}, {"it": "Fa collezione di farfalle?”.", "zh": "”而是问：“他几岁了？", "t": [18812, 20575]}, {"it": "Le loro domande sono: “Quanti anni ha?", "zh": "体重多少？", "t": [20575, 23188]}, {"it": "Quanti fratelli?", "zh": "他的父亲挣多少钱？", "t": [23188, 24362]}, {"it": "Quanto pesa?", "zh": "”他们认为了解了这些情况，就了解了一个人。", "t": [24362, 25438]}, {"it": "Quanto guadagna suo padre?”.", "zh": "”他们认为了解了这些情况，就了解了一个人。", "t": [25438, 27138]}, {"it": "Solo allora pensano di conoscerlo.", "zh": "”他们认为了解了这些情况，就了解了一个人。", "t": [27138, 29375]}, {"it": "Se dite agli adulti: “Ho visto una bella casa di mattoni rosa, con gerani alle finestre e colombi sul tetto...”, loro non riescono a immaginarsi la casa.", "zh": "如果你告诉大人：“我看见一幢漂亮的红砖房子，窗前摆着天竺葵，鸽子在屋顶栖息……”他们便无法想像这是一幢怎样的房子。", "t": [29375, 38538]}, {"it": "Dovete dire: “Ho visto una casa da centomila franchi”.", "zh": "你必须对他们说：“我看见一幢值十万法郎的房子！", "t": [38538, 42238]}, {"it": "Allora esclamano subito: “Oh, che bella!”.", "zh": "”他们就会惊叹：“多漂亮的房子啊！", "t": [42238, 45000]}]}, {"id": "ch04p06", "audio": true, "sents": [{"it": "Quindi se dite: “Il piccolo principe è esistito perché era bellissimo, rideva e voleva una pecora.", "zh": "” 所以，如果你对他们说：“这世上确实存在一位王子，证据就是他可爱俊美，脸带笑容，他要一只绵羊。", "t": [100, 6550]}, {"it": "Se qualcuno vuole una pecora significa che esiste”, loro alzeranno le spalle e diranno che siete un bambino!", "zh": "一个人要一只绵羊，就是他存在的证明。", "t": [6550, 13162]}, {"it": "Ma se proclamate: “Il pianeta da cui veniva è l’asteroide B 612”, allora si convinceranno e vi lasceranno in pace, senza farvi domande.", "zh": "但如果你对他们说：“他打那儿来的星球是小行星B612。", "t": [13162, 22250]}, {"it": "Sono fatti così.", "zh": "”他们就深信不疑了，就不会用没完没了的问题烦你了。", "t": [22250, 23562]}, {"it": "Non bisogna prendersela.", "zh": "”他们就深信不疑了，就不会用没完没了的问题烦你了。", "t": [23562, 25238]}, {"it": "I bambini devono avere molta pazienza con gli adulti.", "zh": "他们就这副德性。", "t": [25238, 28237]}]}, {"id": "ch04p07", "audio": true, "sents": [{"it": "Noi però che capiamo la vita ce ne infischiamo dei numeri!", "zh": "我们不要责怪埋怨他们，孩子对大人应当尽量地宽容。", "t": [100, 3612]}, {"it": "Sarebbe stato bello cominciare questa storia come una favola.", "zh": "当然，我们是理解生活的人，我们才不会把数字放在眼里呢！", "t": [3612, 7038]}, {"it": "Mi sarebbe piaciuto dire:", "zh": "当然，我们是理解生活的人，我们才不会把数字放在眼里呢！", "t": [7038, 8413]}]}, {"id": "ch04p08", "audio": true, "sents": [{"it": "“C’era una volta un piccolo principe che abitava su un pianeta poco più grande di lui e aveva bisogno di un amico...”.", "zh": "我喜欢这样讲： “从前有个小王子，他住在小行星里。", "t": [100, 6425]}, {"it": "Per quelli che capiscono la vita, sarebbe sembrato molto più vero.", "zh": "这颗行星比他自己大不了多少。", "t": [6425, 10012]}]}, {"id": "ch04p09", "audio": true, "sents": [{"it": "Non mi piace, infatti, che il mio libro sia letto in maniera superficiale.", "zh": "”对于理解生活的人，这样讲似乎要真实得多。", "t": [100, 5025]}, {"it": "È molto doloroso rievocare questi ricordi.", "zh": "我不喜欢别人漫不经心地读我的书。", "t": [5025, 7650]}, {"it": "Sono passati ormai sei anni da quando il mio amico se n’è andato con la sua pecora.", "zh": "我的朋友牵着他的羊走了六年了。", "t": [7650, 12250]}, {"it": "Se tento di descriverlo qui, è per non dimenticarlo.", "zh": "我在这儿讲述他的故事，是为了不忘记他。", "t": [12250, 15812]}, {"it": "È triste dimenticare un amico.", "zh": "忘了朋友是可悲的。", "t": [15812, 17812]}, {"it": "Non tutti hanno avuto un amico.", "zh": "并不是每个人都有朋友的。", "t": [17812, 19675]}, {"it": "E rischio di diventare come gli adulti, a cui interessano soltanto i numeri.", "zh": "也许有一天我也像大人那样，除了数字，对别的东西都失去兴趣。", "t": [19675, 24275]}, {"it": "Per questo ho comprato una scatola di colori e delle matite.", "zh": "为了这个缘故，我买了一盒颜料和几枝铅笔。", "t": [24275, 27775]}, {"it": "Alla mia età è dura rimettersi a disegnare quando gli unici tentativi che hai fatto sono stati, a sei anni, un boa chiuso e un boa aperto!", "zh": "而且，除了在六岁那年画过一条打开肚子的蟒蛇和一条没打开肚子的蟒蛇之外，我没画过别的画。", "t": [27775, 35950]}, {"it": "Ovviamente cercherò di fare ritratti più fedeli possibile.", "zh": "当然，我可以画最逼真的人像画。", "t": [35950, 39488]}, {"it": "Ma non sono sicuro di riuscirci.", "zh": "但能否成功，我把握不大。", "t": [39488, 41812]}, {"it": "Un disegno viene bene, e poi un altro non è somigliante.", "zh": "这一幅画得可以，另一幅却画得不像。", "t": [41812, 45638]}, {"it": "A volte mi sbaglio anche con l’altezza.", "zh": "对他的个儿高矮，我也记得不太真切。", "t": [45638, 47975]}, {"it": "Qui il piccolo principe è troppo alto.", "zh": "这幅把他画得太高，另一幅把他画得太矮。", "t": [47975, 50438]}, {"it": "Lì è troppo basso.", "zh": "这幅把他画得太高，另一幅把他画得太矮。", "t": [50438, 51862]}, {"it": "E sono incerto sul colore dei vestiti.", "zh": "该给他的衣服抹什么颜色，我也犹豫不决。", "t": [51862, 54412]}, {"it": "Allora vado un po’ per tentativi, così e cosà, alla meno peggio.", "zh": "该给他的衣服抹什么颜色，我也犹豫不决。", "t": [54412, 58675]}, {"it": "Finirà che sbaglierò qualche dettaglio cruciale.", "zh": "我在画纸上抹来抹去，画了张约莫相似的肖像，但某些重要部位也许弄错了。", "t": [58675, 61588]}, {"it": "Ma dovrete perdonarmi.", "zh": "对这一点，你们一定要谅解。", "t": [61588, 63238]}, {"it": "Il mio amico non dava mai spiegazioni.", "zh": "对这一点，你们一定要谅解。", "t": [63238, 65625]}, {"it": "Forse mi credeva simile a lui.", "zh": "我的朋友从不向我解释，大概他以为我和他一样；可是我呢，很遗憾，我不能透过箱子看到里面的绵羊。", "t": [65625, 67638]}, {"it": "Purtroppo però io non sono capace di vedere le pecore attraverso le casse.", "zh": "我的朋友从不向我解释，大概他以为我和他一样；可是我呢，很遗憾，我不能透过箱子看到里面的绵羊。", "t": [67638, 72112]}, {"it": "Forse sono un po’ come gli adulti.", "zh": "也许我有点像大人了。", "t": [72112, 74262]}, {"it": "Devo essere invecchiato.", "zh": "我大概老了。", "t": [74262, 75625]}]}]}, {"id": "ch05", "title_it": "V", "title_zh": "第 5 章", "paras": [{"id": "ch05p00", "audio": true, "sents": [{"it": "Ogni giorno scoprivo qualcosa sul pianeta, sulla partenza e sul viaggio.", "zh": "每一天，我都从他那儿获得一些有关星球、启程、旅行的知识。", "t": [100, 4750]}, {"it": "Saltava fuori tra una riflessione e l’altra.", "zh": "这些知识是逐渐得到的，只要想到什么问题就提什么问题。", "t": [4750, 7450]}, {"it": "Fu così che il terzo giorno appresi il dramma dei baobab.", "zh": "这些知识是逐渐得到的，只要想到什么问题就提什么问题。", "t": [7450, 11050]}]}, {"id": "ch05p01", "audio": true, "sents": [{"it": "Anche stavolta fu grazie alla pecora, perché improvvisamente il piccolo principe mi domandò, come in preda a un grave dubbio:", "zh": "这一回还真亏了绵羊。", "t": [100, 7062]}]}, {"id": "ch05p02", "audio": true, "sents": [{"it": "“È vero, no, che le pecore mangiano gli arbusti?”", "zh": "因为小王子突然对一件事产生了极大的怀疑，突然问我： “羊吃灌木，这是真的吗？", "t": [100, 3250]}]}, {"id": "ch05p03", "audio": true, "sents": [{"it": "“Sì, è vero.”", "zh": "” “是呀，是真的呀。", "t": [100, 1338]}]}, {"id": "ch05p04", "audio": true, "sents": [{"it": "“Ah, benissimo!”", "zh": "” “是呀，是真的呀。", "t": [100, 1412]}]}, {"id": "ch05p05", "audio": true, "sents": [{"it": "Non capii perché fosse così importante che le pecore mangiassero gli arbusti.", "zh": "” “啊，那我很高兴。", "t": [100, 4675]}, {"it": "Ma il piccolo principe aggiunse:", "zh": "” 我不明白，羊吃灌木为什么这么重要。", "t": [4675, 6525]}]}, {"id": "ch05p06", "audio": true, "sents": [{"it": "“Quindi mangiano anche i baobab?”", "zh": "小王子又问： “这么说，它们也吃猴面包树啦？", "t": [100, 1888]}]}, {"id": "ch05p07", "audio": true, "sents": [{"it": "Feci notare al piccolo principe che i baobab non sono arbusti, ma alberi alti come chiese, e che se anche avesse portato un intero branco di elefanti, il branco non sarebbe riuscito ad avere la meglio su un solo bao­bab.", "zh": "” 我提醒小王子，猴面包树不是灌木丛，而是像教堂一样巍峨高大的树。", "t": [100, 13200]}]}, {"id": "ch05p08", "audio": true, "sents": [{"it": "L’idea del branco di elefanti fece ridere il piccolo principe:", "zh": "想到一群象啃猴面包树的情景，小王子忍不住笑了： “那它们非得叠罗汉了……” 他很机灵，指出： “猴面包树的树苗挺小的呢！", "t": [100, 3500]}]}, {"id": "ch05p09", "audio": true, "sents": [{"it": "“Bisognerebbe metterli uno sopra l’altro...”", "zh": "想到一群象啃猴面包树的情景，小王子忍不住笑了： “那它们非得叠罗汉了……” 他很机灵，指出： “猴面包树的树苗挺小的呢！", "t": [100, 2450]}]}, {"id": "ch05p10", "audio": true, "sents": [{"it": "Ma saggiamente osservò:", "zh": "” “你说得对！", "t": [100, 1412]}]}, {"id": "ch05p11", "audio": true, "sents": [{"it": "“All’inizio, prima di crescere, i baobab sono piccoli.”", "zh": "” “你说得对！", "t": [100, 3738]}]}, {"id": "ch05p12", "audio": true, "sents": [{"it": "“Esatto!", "zh": "可是你为什么希望你的绵羊吃猴面包树苗呢？", "t": [100, 1138]}, {"it": "Ma perché mai le pecore dovrebbero mangiare i piccoli baobab?”", "zh": "可是你为什么希望你的绵羊吃猴面包树苗呢？", "t": [1138, 4537]}]}, {"id": "ch05p13", "audio": true, "sents": [{"it": "Mi rispose: “Insomma, dai!”, come se fosse ovvio.", "zh": "那还用说吗！", "t": [100, 4500]}, {"it": "E dovetti fare un grande sforzo di intelligenza per venire da solo a capo del problema.", "zh": "而要我自己想明白这个问题，我确实要绞尽脑汁了。", "t": [4500, 9675]}]}, {"id": "ch05p14", "audio": true, "sents": [{"it": "In effetti, come su ogni pianeta, sul pianeta del piccolo principe c’erano erbe buone ed erbe cattive.", "zh": "是的，小王子的星球和其他星球一样，长着益草，也长着毒草，因此也就有了益草的种子和毒草的种子。", "t": [100, 7125]}, {"it": "Quindi semi buoni di erbe buone e semi cattivi di erbe cattive.", "zh": "是的，小王子的星球和其他星球一样，长着益草，也长着毒草，因此也就有了益草的种子和毒草的种子。", "t": [7125, 11525]}, {"it": "Ma i semi sono invisibili.", "zh": "但种子是看不见的，它们沉埋在土地深处，直至其中一颗突然苏醒……它伸伸懒腰，羞羞答答，向着太阳伸出一株青嫩可爱、娇小玲珑、不伤人的幼苗来。", "t": [11525, 13450]}, {"it": "Dormono tutti nel segreto della terra finché a uno di loro non piglia il ghiribizzo di svegliarsi.", "zh": "但种子是看不见的，它们沉埋在土地深处，直至其中一颗突然苏醒……它伸伸懒腰，羞羞答答，向着太阳伸出一株青嫩可爱、娇小玲珑、不伤人的幼苗来。", "t": [13450, 19062]}, {"it": "Allora si stiracchia e fa spuntare timidamente verso il sole uno splendido, innocuo germoglio.", "zh": "倘若它是萝卜或玫瑰的幼苗，我们可以任由它茁壮成长；倘若它是有毒的植物，一经认出，我们就必须马上拔除。", "t": [19062, 25438]}, {"it": "Se è un germoglio di rapanello o di rosa, puoi lasciarlo crescere come gli pare.", "zh": "倘若它是萝卜或玫瑰的幼苗，我们可以任由它茁壮成长；倘若它是有毒的植物，一经认出，我们就必须马上拔除。", "t": [25438, 30100]}, {"it": "Ma se ti rendi conto che è una pianta cattiva, devi strapparla immediatamente.", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [30100, 34788]}, {"it": "Sul pianeta del piccolo principe c’erano alcuni semi terribili...", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [34788, 38762]}, {"it": "ed erano i semi di baobab.", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [38762, 40638]}, {"it": "Tutto il suolo del pianeta ne era infestato.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [40638, 43312]}, {"it": "E se un baobab non lo strappi via subito, dopo non riesci più a liberartene.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [43312, 48250]}, {"it": "Occupa tutto il pianeta.", "zh": "后来小王子对我说：“人早上梳洗之后，一定要小心清理地球，要经常督促自己，要养成良好的习惯。", "t": [48250, 49925]}, {"it": "Lo perfora con le radici.", "zh": "后来小王子对我说：“人早上梳洗之后，一定要小心清理地球，要经常督促自己，要养成良好的习惯。", "t": [49925, 52175]}, {"it": "E se il pianeta è troppo piccolo e i baobab sono troppo numerosi, questi lo spaccano tutto.", "zh": "后来小王子对我说：“人早上梳洗之后，一定要小心清理地球，要经常督促自己，要养成良好的习惯。", "t": [52175, 57600]}]}, {"id": "ch05p15", "audio": true, "sents": [{"it": "“È una questione di disciplina,” mi disse più tardi il piccolo principe.", "zh": "猴面包树的苗儿与玫瑰花的苗儿长得极相似，把它们区别开来之后，就要经常督促自己拔除猴面包树苗。", "t": [100, 4075]}, {"it": "“Al mattino, finita la toilette, bisogna occuparsi della toilette del pianeta.", "zh": "这活儿单调乏味，但也挺容易干。", "t": [4075, 9188]}, {"it": "Appena distingui i baobab dalle piante di rose, cui somigliano molto quando sono giovani, li devi subito strappare.", "zh": "” 有一天，他建议我用心画一幅猴面包树的画，要让我们那儿的孩子牢牢记住它。", "t": [9188, 16388]}, {"it": "È un lavoro noiosissimo, ma molto semplice.”", "zh": "他对我说：“有朝一日他们外出旅行，这幅画就派上用场了。", "t": [16388, 19250]}]}, {"id": "ch05p16", "audio": true, "sents": [{"it": "E un giorno mi consigliò di provare a cimentarmi con un bel disegno per far entrare questo principio nella testa dei bambini di dove sto io.", "zh": "有些时候，耽搁了的工夫造不成多大的恶果，然而对猴面包树的危害却不能轻视。", "t": [100, 7825]}, {"it": "“Potrebbe essergli utile, se dovessero viaggiare.", "zh": "有些时候，耽搁了的工夫造不成多大的恶果，然而对猴面包树的危害却不能轻视。", "t": [7825, 10725]}, {"it": "In certi casi rimandare un lavoro non ha alcuna conseguenza.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [10725, 14400]}, {"it": "Ma con i baobab è sempre un disastro.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [14400, 16962]}, {"it": "Conoscevo un pianeta abitato da un pigro.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [16962, 19500]}, {"it": "Aveva trascurato tre arbusti...”", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [19500, 21275]}]}, {"id": "ch05p17", "audio": true, "sents": [{"it": "Così, con le indicazioni del piccolo principe, ho disegnato quel pianeta.", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [100, 5125]}, {"it": "Non mi piace affatto prendere il tono del moralista.", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [5125, 8262]}, {"it": "Ma i baobab rappresentano un pericolo talmente sottovalutato, e i rischi di chi dovesse perdersi in un asteroide sono tali, che una volta tanto metto da parte ogni scrupolo.", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [8262, 18712]}, {"it": "Dico: “Bambini!", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [18712, 20350]}, {"it": "Fate attenzione ai baobab!”.", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [20350, 22388]}, {"it": "Se ho messo tutto il mio impegno in quel disegno è stato proprio per mettere in guardia i miei amici da un pericolo cui, come me, erano esposti da tempo senza saperlo.", "zh": "提醒大家警惕危险，是我义不容辞的责任。", "t": [22388, 31825]}, {"it": "Il messaggio che davo valeva lo sforzo.", "zh": "也许你们看了这幅画后会纳闷：“为什么他在这本书里画的其他画没有这张猴面包树的画雄壮，有气势？", "t": [31825, 34288]}, {"it": "Vi domanderete: Perché in questo libro non ci sono altri disegni grandiosi come il disegno dei baobab?", "zh": "”我的回答很简单：我尽了力去画其他的画，但心有余而力不足。", "t": [34288, 40512]}, {"it": "La risposta è molto semplice: ci ho provato, ma non ci sono riuscito.", "zh": "而画猴面包树的时候，为急迫的需要所激励，我的画便超出了原有的水平。", "t": [40512, 45238]}, {"it": "Quando ho disegnato i baobab, ero spinto dall’urgenza.", "zh": "而画猴面包树的时候，为急迫的需要所激励，我的画便超出了原有的水平。", "t": [45238, 48624]}]}]}, {"id": "ch06", "title_it": "VI", "title_zh": "第 6 章", "paras": [{"id": "ch06p00", "audio": true, "sents": [{"it": "Ah!, piccolo principe, così ho pian piano capito come procedeva la tua vita malinconica.", "zh": "我就是这样逐渐了解到，你过着并不顺心愉快的生活。", "t": [100, 6125]}, {"it": "Per molto tempo il tuo unico svago era stata la dolcezza dei tramonti.", "zh": "长期以来，你惟一的消遣就是观赏夕阳西下的美景。", "t": [6125, 10438]}, {"it": "Ho scoperto questo ennesimo dettaglio il mattino del quarto giorno, quando mi hai detto:", "zh": "你对我说： “我喜欢夕阳。", "t": [10438, 15276]}]}, {"id": "ch06p01", "audio": true, "sents": [{"it": "“A me piacciono molto i tramonti.", "zh": "我们去看日落的壮观吧……” “可是要等啊……” “等什么？", "t": [100, 2075]}, {"it": "Andiamo a vedere un tramonto...”", "zh": "我们去看日落的壮观吧……” “可是要等啊……” “等什么？", "t": [2075, 3588]}]}, {"id": "ch06p02", "audio": true, "sents": [{"it": "“Ma bisogna aspettare...”", "zh": "” “等太阳下山的时刻呀。", "t": [100, 1513]}]}, {"id": "ch06p03", "audio": true, "sents": [{"it": "“Aspettare cosa?”", "zh": "” “等太阳下山的时刻呀。", "t": [100, 1075]}]}, {"id": "ch06p04", "audio": true, "sents": [{"it": "“Aspettare che il sole tramonti.”", "zh": "” 你露出惊讶的神气，然后又自觉可笑，说道： “我老以为我是在自己家里呢！", "t": [100, 1800]}]}, {"id": "ch06p05", "audio": true, "sents": [{"it": "Sulle prime sembravi molto stupito, poi hai riso di te stesso.", "zh": "” 你露出惊讶的神气，然后又自觉可笑，说道： “我老以为我是在自己家里呢！", "t": [100, 4388]}, {"it": "E mi hai detto:", "zh": "” 这话说得不错。", "t": [4388, 5300]}]}, {"id": "ch06p06", "audio": true, "sents": [{"it": "“Credo sempre di essere da me!”", "zh": "” 这话说得不错。", "t": [100, 1612]}]}, {"id": "ch06p07", "audio": true, "sents": [{"it": "Infatti.", "zh": "” 这话说得不错。", "t": [100, 1262]}, {"it": "Tutti sanno che quando negli Stati Uniti è mezzogiorno, in Francia è il tramonto.", "zh": "大家都知道，在美国，太阳正在天空的当中，而这时在法国，太阳已经西下。", "t": [1262, 6712]}, {"it": "Basterebbe poter andare in Francia in un minuto per veder tramontare il sole.", "zh": "若能在一分钟之内赶到法国，就可以观看落日的壮景，遗憾的是法国离得太远了。", "t": [6712, 11362]}, {"it": "Purtroppo la Francia è molto lontana.", "zh": "但是，在你那小小的星球上，你只要把椅子挪几步就能看到日落了。", "t": [11362, 13775]}, {"it": "Ma sul tuo piccolissimo pianeta ti bastava spostare la sedia di qualche passo.", "zh": "但是，在你那小小的星球上，你只要把椅子挪几步就能看到日落了。", "t": [13775, 18350]}, {"it": "E guardavi il crepuscolo ogni volta che volevi...", "zh": "什么时候要看夕晖都能看得到…… “有一天，我看了四十三次太阳下山！", "t": [18350, 20912]}]}, {"id": "ch06p08", "audio": true, "sents": [{"it": "“Un giorno ho visto il sole tramontare quarantaquattro volte!”", "zh": "什么时候要看夕晖都能看得到…… “有一天，我看了四十三次太阳下山！", "t": [100, 3512]}]}, {"id": "ch06p09", "audio": true, "sents": [{"it": "E più tardi aggiungevi:", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [100, 1438]}]}, {"id": "ch06p10", "audio": true, "sents": [{"it": "“Sai...", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [100, 950]}, {"it": "quando si è molto tristi si amano i tramonti...”", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [950, 3462]}]}, {"id": "ch06p11", "audio": true, "sents": [{"it": "“Allora il giorno delle quarantaquattro volte eri proprio tanto triste?”", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [100, 3638]}]}, {"id": "ch06p12", "audio": true, "sents": [{"it": "Ma il piccolo principe non rispose.", "zh": "” 小王子没有答话。", "t": [100, 2225]}]}]}, {"id": "ch07", "title_it": "VII", "title_zh": "第 7 章", "paras": [{"id": "ch07p00", "audio": true, "sents": [{"it": "Il quinto giorno, sempre grazie alla pecora, mi fu rivelato il segreto della vita del piccolo principe.", "zh": "第五天，仍然是多亏了那只绵羊，小王子生活中的秘密才被泄露了出来。", "t": [100, 6300]}, {"it": "Mi domandò bruscamente, di punto in bianco, come un interrogativo a lungo meditato in silenzio:", "zh": "他似乎对一个问题反复思考了许久，然后开门见山，直截了当地突然问我： “绵羊吃灌木，它也吃花吗？", "t": [6300, 12113]}]}, {"id": "ch07p01", "audio": true, "sents": [{"it": "“Una pecora, se mangia gli arbusti, mangia anche i fiori?”", "zh": "” “绵羊遇见什么吃什么。", "t": [100, 3663]}]}, {"id": "ch07p02", "audio": true, "sents": [{"it": "“Una pecora mangia tutto quello che trova.”", "zh": "” “绵羊遇见什么吃什么。", "t": [100, 2187]}]}, {"id": "ch07p03", "audio": true, "sents": [{"it": "“Anche i fiori con le spine?”", "zh": "” “吃的。", "t": [100, 1537]}]}, {"id": "ch07p04", "audio": true, "sents": [{"it": "“Sì.", "zh": "” “吃的。", "t": [100, 825]}, {"it": "Anche i fiori con le spine.”", "zh": "带刺的花也吃。", "t": [825, 2288]}]}, {"id": "ch07p05", "audio": true, "sents": [{"it": "“Allora le spine a cosa servono?”", "zh": "” “那刺还有什么作用呢？", "t": [100, 1900]}]}, {"id": "ch07p06", "audio": true, "sents": [{"it": "Non lo sapevo.", "zh": "” 我不知道刺还有什么作用。", "t": [100, 1275]}, {"it": "In quel momento ero tutto preso a svitare un bullone troppo stretto del motore.", "zh": "当时我正忙于把发动机上拧得过紧的螺栓弄下来。", "t": [1275, 6138]}, {"it": "Ero molto preoccupato perché il guasto cominciava a sembrarmi davvero serio e le scorte d’acqua che si riducevano mi facevano temere il peggio.", "zh": "最让我担心的，是饮用水已经所剩不多了。", "t": [6138, 13526]}]}, {"id": "ch07p07", "audio": true, "sents": [{"it": "“Le spine a cosa servono?”", "zh": "“那刺还有什么作用呢？", "t": [100, 1576]}]}, {"id": "ch07p08", "audio": true, "sents": [{"it": "Il piccolo principe non rinunciava mai a una domanda dopo che l’aveva fatta.", "zh": "” 小王子一旦提出疑问，就要寻根究底，追问个没完，绝不会中途而废。", "t": [100, 4588]}, {"it": "Ero contrariato dal bullone e risposi con la prima sciocchezza che mi passò per la mente:", "zh": "我正被螺栓闹得心烦意乱，便顺口答道：“刺不起作用，都是因为花儿心眼太坏！", "t": [4588, 9226]}]}, {"id": "ch07p09", "audio": true, "sents": [{"it": "“Le spine non servono a niente, sono pura cattiveria da parte dei fiori!”", "zh": "” “哦？", "t": [100, 4350]}]}, {"id": "ch07p10", "audio": true, "sents": [{"it": "“Oh!”", "zh": "” 沉默了一会儿，他悻悻地说： “我不信你说的话！", "t": [100, 562]}]}, {"id": "ch07p11", "audio": true, "sents": [{"it": "Ma dopo un attimo di silenzio sbottò, come risentito:", "zh": "” 沉默了一会儿，他悻悻地说： “我不信你说的话！", "t": [100, 3737]}]}, {"id": "ch07p12", "audio": true, "sents": [{"it": "“Non ti credo!", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [100, 1312]}, {"it": "I fiori sono deboli.", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [1312, 2888]}, {"it": "Sono ingenui.", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [2888, 4112]}, {"it": "Si fanno coraggio come possono.", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [4112, 6112]}, {"it": "E con le spine pensano di mettere paura...”", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [6112, 8412]}]}, {"id": "ch07p13", "audio": true, "sents": [{"it": "Non risposi nulla.", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [100, 1538]}, {"it": "In quel momento pensavo: “Se questo bullone non si allenta, lo faccio saltare con una martellata”.", "zh": "这时我的念头是：“如果这颗螺栓拧不下来，我就用锤子把它砸了。", "t": [1538, 7412]}, {"it": "Il piccolo principe interruppe di nuovo le mie riflessioni:", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [7412, 10700]}]}, {"id": "ch07p14", "audio": true, "sents": [{"it": "“E tu credi che i fiori...”", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [100, 1425]}]}, {"id": "ch07p15", "audio": true, "sents": [{"it": "“Ma no!", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [100, 875]}, {"it": "Ma no!", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [875, 1650]}, {"it": "Non credo un bel niente!", "zh": "别烦我了！", "t": [1650, 3500]}, {"it": "Ho detto la prima cosa che capitava.", "zh": "我什么也不信！", "t": [3500, 5712]}, {"it": "Ho faccende ben più serie a cui pensare, io!”", "zh": "我不过在信口开河啊。", "t": [5712, 8462]}]}, {"id": "ch07p16", "audio": true, "sents": [{"it": "Mi guardò stupefatto.", "zh": "我，我在忙正经事呢。", "t": [100, 1563]}]}, {"id": "ch07p17", "audio": true, "sents": [{"it": "“Faccende ben più serie!”", "zh": "” 他瞪着我，愣住了。", "t": [100, 1638]}]}, {"id": "ch07p18", "audio": true, "sents": [{"it": "Mi vedeva con il martello in mano, le dita nere di grasso, alle prese con un oggetto che a lui sembrava molto brutto.", "zh": "” 他看见我手攥锤子，两手油污，俯身对着一件他认为很丑的物件。", "t": [100, 6937]}]}, {"id": "ch07p19", "audio": true, "sents": [{"it": "“Parli come gli adulti!”", "zh": "“你说话的时候像个大人！", "t": [100, 1463]}]}, {"id": "ch07p20", "audio": true, "sents": [{"it": "Provai un po’ di vergogna.", "zh": "“你说话的时候像个大人！", "t": [100, 1788]}, {"it": "Ma lui, implacabile, aggiunse:", "zh": "” 听了这话，我有点难为情。", "t": [1788, 4450]}]}, {"id": "ch07p21", "audio": true, "sents": [{"it": "“Confondi tutto...", "zh": "” 听了这话，我有点难为情。", "t": [100, 1375]}, {"it": "mescoli tutto!”", "zh": "然而他又毫不留情地讲了一句： “你是非不分……你混淆黑白！", "t": [1375, 2338]}]}, {"id": "ch07p22", "audio": true, "sents": [{"it": "Era davvero molto irritato.", "zh": "然而他又毫不留情地讲了一句： “你是非不分……你混淆黑白！", "t": [100, 1850]}, {"it": "Scuoteva al vento i capelli dorati:", "zh": "” 他真的气坏了。", "t": [1850, 3862]}]}, {"id": "ch07p23", "audio": true, "sents": [{"it": "“Conosco un pianeta dove c’è un signore con la faccia paonazza.", "zh": "一头金发在风中乱摇。", "t": [100, 3825]}, {"it": "Non ha mai annusato un fiore.", "zh": "“我知道一颗行星，上面有一位红脸先生。", "t": [3825, 5625]}, {"it": "Non ha mai guardato una stella.", "zh": "他从未嗅过一朵花。", "t": [5625, 7488]}, {"it": "Non ha mai amato nessuno.", "zh": "他从未嗅过一朵花。", "t": [7488, 9188]}, {"it": "Non ha mai fatto altro che addizioni.", "zh": "他从未观赏过一颗星星。", "t": [9188, 11425]}, {"it": "E tutto il giorno ripete come te: ‘Sono un uomo serio!", "zh": "他什么事也没干过，只会做算术中的加法。", "t": [11425, 15025]}, {"it": "Sono un uomo serio!’ e questo lo riempie di orgoglio.", "zh": "他整天就像你一样，反复地唠叨：‘我是个正经人！", "t": [15025, 18550]}, {"it": "Ma non è un uomo, è un fungo!”", "zh": "他整天就像你一样，反复地唠叨：‘我是个正经人！", "t": [18550, 20687]}]}, {"id": "ch07p24", "audio": true, "sents": [{"it": "“Un cosa?”", "zh": "我是正经人！", "t": [100, 787]}]}, {"id": "ch07p25", "audio": true, "sents": [{"it": "“Un fungo.”", "zh": "我是正经人！", "t": [100, 888]}]}, {"id": "ch07p26", "audio": true, "sents": [{"it": "Adesso il piccolo principe era pallido di rabbia.", "zh": "’真是自命不凡，神气活现！", "t": [100, 2863]}]}, {"id": "ch07p27", "audio": true, "sents": [{"it": "“Da milioni di anni i fiori mettono le spine.", "zh": "可他不是人，是蘑菇！", "t": [100, 2775]}, {"it": "Da milioni di anni le pecore mangiano ugualmente i fiori.", "zh": "” “是蘑菇！", "t": [2775, 6138]}, {"it": "E non è forse una cosa seria cercare di capire perché i fiori si danno tanta pena per mettere spine che non servono a niente?", "zh": "“几百万年以来，花儿都长着刺；几百万年以来，羊也在吃花。", "t": [6138, 12912]}, {"it": "Non è forse importante la guerra delle pecore e dei fiori?", "zh": "难道我想知道，花儿为什么憋足了劲长没用的刺，这是不正经的事吗？", "t": [12912, 16312]}, {"it": "Non è forse più seria e importante delle addizioni di un signore grasso e rosso?", "zh": "这不比红脸胖子的加法更正经，更重要吗？", "t": [16312, 20962]}, {"it": "E se io conosco un fiore unico al mondo, che esiste soltanto sul mio pianeta, e che una piccola pecora improvvisamente può distruggere, così, una mattina, senza neppure rendersene conto, non è forse importante?”", "zh": "要是我认识的世界上的一朵独一无二的花，她哪儿也不去，就爱长在我的星球上，可是却在某天早晨，被小绵羊一不留神咬死了，难道这样的事也不重要吗？", "t": [20962, 34675]}]}, {"id": "ch07p28", "audio": true, "sents": [{"it": "Arrossì, poi continuò:", "zh": "要是我认识的世界上的一朵独一无二的花，她哪儿也不去，就爱长在我的星球上，可是却在某天早晨，被小绵羊一不留神咬死了，难道这样的事也不重要吗？", "t": [100, 1975]}]}, {"id": "ch07p29", "audio": true, "sents": [{"it": "“Chi ama un fiore di cui esiste un solo esemplare fra milioni e milioni di stelle, basta che guardi le stelle e si sente felice.", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [100, 7500]}, {"it": "Può pensare: ‘Il mio fiore è lì da qualche parte...’.", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [7500, 10638]}, {"it": "Ma se la pecora mangia il fiore, è come se di colpo tutte le stelle si spegnessero!", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [10638, 15638]}, {"it": "E ti sembra che questo non sia importante!”", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [15638, 17950]}]}, {"id": "ch07p30", "audio": true, "sents": [{"it": "Non poté dire altro.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [100, 1575]}, {"it": "All’improvviso scoppiò in singhiozzi.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [1575, 4150]}, {"it": "Era scesa la notte.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [4150, 5612]}, {"it": "Avevo posato i miei utensili.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [5612, 7512]}, {"it": "Non mi importava niente del martello, del bullone, della sete e della morte.", "zh": "夜幕降临，我扔下手里的工具，顾不得锤子、螺栓、干渴、死亡了。", "t": [7512, 12400]}, {"it": "Su una stella, su un pianeta, il mio, la Terra, c’era un piccolo principe da consolare!", "zh": "在一颗星球上，在我的行星地球上，有一个小王子需要安慰！", "t": [12400, 18938]}, {"it": "Lo presi tra le braccia.", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [18938, 20688]}, {"it": "Lo cullai.", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [20688, 21738]}, {"it": "Gli dicevo: “Il fiore che ami non è in pericolo...", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [21738, 24838]}, {"it": "Disegnerò una museruola per la tua pecora...", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [24838, 27800]}, {"it": "E per il tuo fiore disegnerò un’armatura...", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [27800, 30462]}, {"it": "Io...”.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [30462, 31188]}, {"it": "Non sapevo cosa dire.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [31188, 32712]}, {"it": "Mi sentivo impacciato.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [32712, 34350]}, {"it": "Non sapevo come avvicinarmi a lui, dove trovare un accesso al suo cuore...", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [34350, 38738]}, {"it": "È talmente misterioso, il paese delle lacrime!", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [38738, 41825]}]}]}, {"id": "ch08", "title_it": "VIII", "title_zh": "第 8 章", "paras": [{"id": "ch08p00", "audio": true, "sents": [{"it": "Presto imparai a conoscere meglio quel fiore.", "zh": "我很快就对这朵花有了更深的了解。", "t": [100, 2675]}, {"it": "Sul pianeta del piccolo principe c’erano sempre stati alcuni fiori molto semplici, con una sola raggiera di petali, che occupavano poco spazio e non disturbavano nessuno.", "zh": "小王子生活的星球上长着很朴素的单瓣花，她们一点儿也不占地方，也不扰人，在草地上朝开暮落。", "t": [2675, 13100]}, {"it": "Apparivano un mattino nell’erba e la sera morivano.", "zh": "而这朵花的种子不知道是从哪儿来的。", "t": [13100, 16362]}, {"it": "Poi un giorno era spuntato quello, da un seme giunto da chissà dove, e il piccolo principe aveva tenuto d’occhio quel germoglio diverso da tutti gli altri.", "zh": "她很可能是新品种的猴面包树苗呢。", "t": [16362, 25450]}, {"it": "Poteva essere un nuovo genere di baobab.", "zh": "小王子看着硕大的花苞，预感到她会绽放出奇异的花朵。", "t": [25450, 28012]}, {"it": "Ben presto però l’arbusto smise di crescere e cominciò a preparare un fiore.", "zh": "小王子看着硕大的花苞，预感到她会绽放出奇异的花朵。", "t": [28012, 32662]}, {"it": "Il piccolo principe assisteva allo schiudersi di un enorme bocciolo e sentiva che ne sarebbe venuta un’apparizione miracolosa, ma la corolla indugiava, e si faceva bella, chiusa nella sua camera verde.", "zh": "颜色，慢条斯理地穿衣，一片片地搭配她的花瓣。", "t": [32662, 44412]}, {"it": "Con cura sceglieva i colori.", "zh": "她要容光焕发地见人。", "t": [44412, 46288]}, {"it": "Si vestiva piano, accomodando i petali a uno a uno.", "zh": "不错，她就是朵极爱俏的花儿。", "t": [46288, 49950]}, {"it": "Non voleva uscire tutta stropicciata, come fanno i papaveri.", "zh": "她神秘兮兮地梳妆打扮了好几天，终于在一天早晨，在太阳出来的那一刻，她露脸亮相了。", "t": [49950, 53750]}, {"it": "Voleva mostrarsi solo nel pieno fulgore della propria bellezza.", "zh": "她神秘兮兮地梳妆打扮了好几天，终于在一天早晨，在太阳出来的那一刻，她露脸亮相了。", "t": [53750, 57688]}, {"it": "Eh sì!", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [57688, 58538]}, {"it": "Era molto vanitosa.", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [58538, 60012]}, {"it": "La sua segreta toilette era durata giorni e giorni.", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [60012, 63250]}, {"it": "Ed ecco che una mattina, con il sorgere del sole, era apparsa una rosa.", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [63250, 67938]}]}, {"id": "ch08p01", "audio": true, "sents": [{"it": "Si era preparata con grande cura, e tuttavia disse sbadigliando:", "zh": "我刚刚睡醒呢……请你原谅……我的妆还零乱呢……” 小王子忍不住赞叹： “您真美啊！", "t": [100, 3738]}]}, {"id": "ch08p02", "audio": true, "sents": [{"it": "“Ah!", "zh": "我刚刚睡醒呢……请你原谅……我的妆还零乱呢……” 小王子忍不住赞叹： “您真美啊！", "t": [100, 750]}, {"it": "Mi sono svegliata proprio ora...", "zh": "我刚刚睡醒呢……请你原谅……我的妆还零乱呢……” 小王子忍不住赞叹： “您真美啊！", "t": [750, 2562]}, {"it": "Scusatemi...", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [2562, 3650]}, {"it": "Sono ancora tutta in disordine...”", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [3650, 5463]}]}, {"id": "ch08p03", "audio": true, "sents": [{"it": "Il piccolo principe non poté trattenere la propria ammirazione:", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [100, 3500]}]}, {"id": "ch08p04", "audio": true, "sents": [{"it": "“Come sei bella!”", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [100, 1063]}]}, {"id": "ch08p05", "audio": true, "sents": [{"it": "“Eh sì,” rispose piano la rosa.", "zh": "“是吃早点的时候了吧。", "t": [100, 2075]}, {"it": "“E sono nata insieme con il sole...”", "zh": "“是吃早点的时候了吧。", "t": [2075, 3913]}]}, {"id": "ch08p06", "audio": true, "sents": [{"it": "Il piccolo principe capì subito che non era granché modesta, ma era così toccante!", "zh": "”很快她又说。", "t": [100, 5088]}]}, {"id": "ch08p07", "audio": true, "sents": [{"it": "“Credo sia ora di colazione,” aveva poi aggiunto, “saresti così gentile da pensare a me...”", "zh": "“劳驾您给我……” 小王子为自己的疏忽而感到羞惭，赶紧找了一壶清水，侍候花儿用餐。", "t": [100, 4926]}]}, {"id": "ch08p08", "audio": true, "sents": [{"it": "E il piccolo principe, confuso, era andato a prendere un innaffiatoio pieno di acqua fresca e aveva servito la rosa.", "zh": "例如，有一天，她对小王子说到她身上长的四根刺的用途。", "t": [100, 7312]}]}, {"id": "ch08p09", "audio": true, "sents": [{"it": "Ben presto lei aveva cominciato a tormentarlo con la sua vanità un po’ ombrosa.", "zh": "她说： “这儿也许有老虎吧，老虎的爪子锋利得很呢！", "t": [100, 4862]}, {"it": "Un giorno, per esempio, parlando delle sue quattro spine aveva detto al principe:", "zh": "” “我的星球上没有老虎。", "t": [4862, 9825]}]}, {"id": "ch08p10", "audio": true, "sents": [{"it": "“Che vengano pure, le tigri, con i loro artigli!”", "zh": "”小王子表示异议。", "t": [100, 3276]}]}, {"id": "ch08p11", "audio": true, "sents": [{"it": "“Sul mio pianeta non ci sono tigri,” aveva obiettato il principe, “e comunque le tigri non mangiano l’erba.”", "zh": "“对不起……” “我一点也不畏惧老虎，但我讨厌风。", "t": [100, 5862]}]}, {"id": "ch08p12", "audio": true, "sents": [{"it": "“Ma io non sono erba,” aveva risposto dolcemente la rosa.", "zh": "您没有屏风吗？", "t": [100, 3238]}]}, {"id": "ch08p13", "audio": true, "sents": [{"it": "“Scusami...!”", "zh": "” “你居然讨厌风啊……这可不好。", "t": [100, 800]}]}, {"id": "ch08p14", "audio": true, "sents": [{"it": "“Non ho nessunissima paura delle tigri, ma ho il terrore delle correnti d’aria.", "zh": "”小王子对她有了看法。", "t": [100, 4612]}, {"it": "Non avresti un paravento?”", "zh": "“这朵花倒很复杂……” “晚上您用罩子把我罩起来吧。", "t": [4612, 6050]}]}, {"id": "ch08p15", "audio": true, "sents": [{"it": "“Il terrore delle correnti d’aria...", "zh": "“这朵花倒很复杂……” “晚上您用罩子把我罩起来吧。", "t": [100, 2250]}, {"it": "È una bella sfortuna, per una pianta,” aveva osservato il piccolo principe.", "zh": "您这儿太冷，位置不好。", "t": [2250, 6925]}, {"it": "“Questo fiore è proprio complicato...”", "zh": "我来的那个地方……” 她住了口。", "t": [6925, 8787]}]}, {"id": "ch08p16", "audio": true, "sents": [{"it": "“La sera devi mettermi sotto una campana di vetro.", "zh": "来这儿的时候她还是一颗种子呢，怎么可能了解别的地方呢。", "t": [100, 3262]}, {"it": "Qui da te fa molto freddo.", "zh": "她撒的谎幼稚可笑，让人一下子就能识破。", "t": [3262, 5038]}, {"it": "È un posto proprio disagevole.", "zh": "她撒的谎幼稚可笑，让人一下子就能识破。", "t": [5038, 7062]}, {"it": "Da dove vengo io...”", "zh": "她撒的谎幼稚可笑，让人一下子就能识破。", "t": [7062, 8124]}]}, {"id": "ch08p17", "audio": true, "sents": [{"it": "Ma la rosa si era interrotta.", "zh": "她撒的谎幼稚可笑，让人一下子就能识破。", "t": [100, 2175]}, {"it": "Era giunta lì sotto forma di seme.", "zh": "她觉得丢脸，便咳嗽了两三声，想把过错推到小王子身上去： “我要的屏风呢？", "t": [2175, 4425]}, {"it": "Non poteva sapere nulla degli altri mondi.", "zh": "她觉得丢脸，便咳嗽了两三声，想把过错推到小王子身上去： “我要的屏风呢？", "t": [4425, 6850]}, {"it": "Umiliata per essere stata sorpresa a inventare quella grossolana bugia, aveva tossito due o tre volte, per mettere il principe dalla parte del torto:", "zh": "……” “我正要去找屏风，是您和我说话的呀！", "t": [6850, 15363]}]}, {"id": "ch08p18", "audio": true, "sents": [{"it": "“Allora, questo paravento?”", "zh": "小王子很怜爱她，但她的做作令他生疑。", "t": [100, 1900]}]}, {"id": "ch08p19", "audio": true, "sents": [{"it": "“Stavo andando a prenderlo, ma tu mi parlavi!”", "zh": "小王子很怜爱她，但她的做作令他生疑。", "t": [100, 2762]}]}, {"id": "ch08p20", "audio": true, "sents": [{"it": "E la rosa aveva accentuato la tosse per farlo sentire in colpa.", "zh": "他是个做事一丝不苟的人，常把无关紧要的闲话当真，难免招来不少麻烦。", "t": [100, 3650]}]}, {"id": "ch08p21", "audio": true, "sents": [{"it": "Così, nonostante la buona volontà del proprio amore, ben presto il piccolo principe aveva dubitato di lei.", "zh": "有一天，他向我倾诉他的心事：“我本不该听信她的话的。", "t": [100, 6612]}, {"it": "Aveva preso sul serio parole senza importanza, ed era diventato molto infelice.", "zh": "永远也别信花儿讲的话。", "t": [6612, 11588]}]}, {"id": "ch08p22", "audio": true, "sents": [{"it": "“Non avrei dovuto ascoltarla,” mi confidò un giorno, “non bisogna mai ascoltare i fiori.", "zh": "我的花熏香了我的星球，但我不懂得为此高兴。", "t": [100, 5200]}, {"it": "Bisogna guardarli e annusarli.", "zh": "她说的老虎爪子的话，本来应该打动我的心，我却生了她的气。", "t": [5200, 7362]}, {"it": "La mia rosa profumava tutto il pianeta, ma io non sapevo gioirne.", "zh": "她说的老虎爪子的话，本来应该打动我的心，我却生了她的气。", "t": [7362, 11462]}, {"it": "La storia degli artigli, che mi aveva così irritato, avrebbe dovuto intenerirmi...”", "zh": "” 他还说： “那时我真是不懂事。", "t": [11462, 16400]}]}, {"id": "ch08p23", "audio": true, "sents": [{"it": "E mi confidò ancora:", "zh": "要对一个人下定论，不应听其言，而应观其行。", "t": [100, 1387]}]}, {"id": "ch08p24", "audio": true, "sents": [{"it": "“Non ho capito niente!", "zh": "要对一个人下定论，不应听其言，而应观其行。", "t": [100, 1688]}, {"it": "Avrei dovuto giudicarla dalle sue azioni e non dalle sue parole.", "zh": "她芬芳馥郁，赏心悦目，我不应抛下她一走了之！", "t": [1688, 5338]}, {"it": "Mi profumava e mi illuminava.", "zh": "我不理解她那不聪明的谎言饱含的深情。", "t": [5338, 7312]}, {"it": "Non avrei mai dovuto andarmene!", "zh": "我不理解她那不聪明的谎言饱含的深情。", "t": [7312, 9275]}, {"it": "Avrei dovuto intuire l’affetto che stava dietro i suoi poveri trucchi.", "zh": "花儿是缺点不少、但优点也很多的矛盾的东西！", "t": [9275, 13100]}, {"it": "I fiori sono così contraddittori!", "zh": "那时我年纪太轻，不懂得珍惜她，爱她。", "t": [13100, 15450]}, {"it": "Ma ero troppo giovane per saperla amare.”", "zh": "那时我年纪太轻，不懂得珍惜她，爱她。", "t": [15450, 17650]}]}]}, {"id": "ch09", "title_it": "IX", "title_zh": "第 9 章", "paras": [{"id": "ch09p00", "audio": true, "sents": [{"it": "Credo che per la sua fuga approfittò di una migrazione di uccelli selvatici.", "zh": "我估计他是趁候鸟迁徙时出走的。", "t": [100, 4825]}, {"it": "Il mattino della partenza rassettò per bene il pianeta.", "zh": "出走的那天早晨，他认真收拾整理他的星球，仔细疏通火山口。", "t": [4825, 8400]}, {"it": "Pulì con cura i vulcani attivi.", "zh": "他有两座活火山，热早饭挺方便的。", "t": [8400, 10562]}, {"it": "Ne possedeva due.", "zh": "他还有一座死火山。", "t": [10562, 12038]}, {"it": "Ed erano molto comodi per scaldare la colazione.", "zh": "他还有一座死火山。", "t": [12038, 15000]}, {"it": "Possedeva anche un vulcano spento.", "zh": "可是正如他说的：“日后的事很难说！", "t": [15000, 17325]}, {"it": "Ma, come diceva lui: “Non si sa mai!”.", "zh": "”谁知道死火山会不会变活呢？", "t": [17325, 20212]}, {"it": "Quindi pulì anche il vulcano spento.", "zh": "所以他也疏通死火山。", "t": [20212, 22700]}, {"it": "Se sono tenuti puliti, i vulcani bruciano piano e in maniera uniforme, senza eruzioni.", "zh": "经过疏通，火山里的火焰缓缓燃烧，火山就不会喷发。", "t": [22700, 28538]}, {"it": "Le eruzioni vulcaniche sono come i fuochi nel caminetto.", "zh": "我们这些人太渺小，没有疏通火山的能力，所以火山才给我们造成很多麻烦。", "t": [28538, 32075]}, {"it": "Naturalmente sulla Terra siamo troppo piccoli per pulire i vulcani.", "zh": "我们这些人太渺小，没有疏通火山的能力，所以火山才给我们造成很多麻烦。", "t": [32075, 36100]}, {"it": "Per questo ci causano tanti problemi.", "zh": "小王子闷闷地拔除了最后几棵猴面包树苗。", "t": [36100, 38200]}]}, {"id": "ch09p01", "audio": true, "sents": [{"it": "Con un po’ di malinconia, il piccolo principe strappò anche gli ultimi germogli di baobab.", "zh": "他知道自己不会再回来了。", "t": [100, 5738]}, {"it": "Pensava che non sarebbe mai più tornato.", "zh": "最后一次给花儿浇水，准备给她盖上罩子，他竟觉得他想哭。", "t": [5738, 8162]}, {"it": "Ma quella mattina tutti i lavori consueti gli parvero molto piacevoli.", "zh": "最后一次给花儿浇水，准备给她盖上罩子，他竟觉得他想哭。", "t": [8162, 12588]}, {"it": "E quando innaffiò un’ultima volta la rosa, e si accinse a metterla sotto la campana, scoprì di aver voglia di piangere.", "zh": "”他又说。", "t": [12588, 19500]}]}, {"id": "ch09p02", "audio": true, "sents": [{"it": "“Addio,” le disse.", "zh": "她终于对他说：“我以前真傻，请你原谅。", "t": [100, 1287]}]}, {"id": "ch09p03", "audio": true, "sents": [{"it": "Ma lei non gli rispose.", "zh": "她终于对他说：“我以前真傻，请你原谅。", "t": [100, 1538]}]}, {"id": "ch09p04", "audio": true, "sents": [{"it": "“Addio,” ripeté.", "zh": "好好地享受生活吧，愿你幸福。", "t": [100, 1100]}]}, {"id": "ch09p05", "audio": true, "sents": [{"it": "La rosa tossì.", "zh": "好好地享受生活吧，愿你幸福。", "t": [100, 1425]}, {"it": "Ma non era a causa del raffreddore.", "zh": "” 她并没有责备他的意思。", "t": [1425, 3462]}]}, {"id": "ch09p06", "audio": true, "sents": [{"it": "“Sono stata sciocca,” gli disse infine.", "zh": "他觉得挺意外。", "t": [100, 2488]}, {"it": "“Ti chiedo scusa.", "zh": "他不知所措地站在那儿，高举着罩子。", "t": [2488, 3712]}, {"it": "Cerca di essere felice.”", "zh": "他不知所措地站在那儿，高举着罩子。", "t": [3712, 5087]}]}, {"id": "ch09p07", "audio": true, "sents": [{"it": "Lo stupì l’assenza di rimproveri.", "zh": "他不理解她的脉脉深情。", "t": [100, 2325]}, {"it": "Se ne stava lì, tutto sottosopra, con la campana di vetro in mano.", "zh": "“是的，我爱你，”花儿对他说，“你丝毫没察觉到我对你的爱，这是我的错。", "t": [2325, 6762]}, {"it": "Non capiva quella dolcezza tranquilla.", "zh": "“是的，我爱你，”花儿对他说，“你丝毫没察觉到我对你的爱，这是我的错。", "t": [6762, 8900]}]}, {"id": "ch09p08", "audio": true, "sents": [{"it": "“Insomma, io ti amo,” gli disse la rosa.", "zh": "如今说也没用了。", "t": [100, 2900]}, {"it": "“E per colpa mia non l’hai capito.", "zh": "你和我一样傻。", "t": [2900, 4775]}, {"it": "Non importa.", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [4775, 5925]}, {"it": "Ma sei stato stupido quanto me.", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [5925, 7950]}, {"it": "Cerca di essere felice...", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [7950, 9662]}, {"it": "Lascia stare quella campana, non la voglio più.”", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [9662, 12250]}]}, {"id": "ch09p09", "audio": true, "sents": [{"it": "“Ma il vento...”", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [100, 1062]}]}, {"id": "ch09p10", "audio": true, "sents": [{"it": "“Non sono poi così raffreddata...", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [100, 2112]}, {"it": "L’aria fresca della notte mi farà bene.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [2112, 4512]}, {"it": "In fondo, sono un fiore.”", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [4512, 6150]}]}, {"id": "ch09p11", "audio": true, "sents": [{"it": "“Ma gli animali...”", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [100, 1012]}]}, {"id": "ch09p12", "audio": true, "sents": [{"it": "“Devo pur sopportare due o tre bruchi se voglio conoscere le farfalle.", "zh": "这似乎是很美的事。", "t": [100, 4225]}, {"it": "Pare che siano bellissime.", "zh": "要不，谁会看望我呢？", "t": [4225, 5950]}, {"it": "Altrimenti chi mi verrà a trovare?", "zh": "你呢，又快离我而去了。", "t": [5950, 8062]}, {"it": "Tu sarai lontano.", "zh": "你呢，又快离我而去了。", "t": [8062, 9400]}, {"it": "Quanto alle bestie grandi, non ho paura.", "zh": "我一点不畏惧大的动物，我有爪子呀。", "t": [9400, 12125]}, {"it": "Ho i miei artigli.”", "zh": "” 她天真地伸出她的四根刺。", "t": [12125, 13262]}]}, {"id": "ch09p13", "audio": true, "sents": [{"it": "E mostrava ingenuamente le sue quattro spine.", "zh": "” 她天真地伸出她的四根刺。", "t": [100, 2888]}, {"it": "Poi aggiunse:", "zh": "然后又说： “别婆婆妈妈，磨磨蹭蹭的了，闹得人心乱。", "t": [2888, 3813]}]}, {"id": "ch09p14", "audio": true, "sents": [{"it": "“Non tirarla tanto per le lunghe, che è seccante.", "zh": "然后又说： “别婆婆妈妈，磨磨蹭蹭的了，闹得人心乱。", "t": [100, 3375]}, {"it": "Hai deciso di partire, e allora vai.”", "zh": "你既已下了决心，那就走吧。", "t": [3375, 5600]}]}, {"id": "ch09p15", "audio": true, "sents": [{"it": "Non voleva che lui la vedesse piangere.", "zh": "” 她不愿让小王子看见她哭。", "t": [100, 2438]}, {"it": "Era un fiore talmente orgoglioso...", "zh": "她是一朵多么骄傲的花儿哟……", "t": [2438, 4437]}]}]}, {"id": "ch10", "title_it": "X", "title_zh": "第 10 章", "paras": [{"id": "ch10p00", "audio": true, "sents": [{"it": "Lui si trovava nella regione degli asteroidi 325, 326, 327, 328, 329 e 330.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [100, 10038]}, {"it": "Decise quindi di visitarli per cercarvi un’occupazione e per istruirsi.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [10038, 16062]}]}, {"id": "ch10p01", "audio": true, "sents": [{"it": "Il primo era abitato da un re.", "zh": "于是他决定首先拜访它们，在那儿找事干，并增长见识。", "t": [100, 2088]}, {"it": "Il re sedeva vestito di porpora e di ermellino su un trono semplicissimo e tuttavia maestoso.", "zh": "325号行星上住着一位国王。", "t": [2088, 7424]}]}, {"id": "ch10p02", "audio": true, "sents": [{"it": "“Ah!", "zh": "325号行星上住着一位国王。", "t": [100, 750]}, {"it": "Ecco un suddito,” esclamò il re quando scorse il piccolo principe.", "zh": "他穿着镶有紫红色袖口和领口的白鼬皮衣服，坐在式样简单然而威严的宝座上。", "t": [750, 4625]}]}, {"id": "ch10p03", "audio": true, "sents": [{"it": "E il piccolo principe si domandò:", "zh": "看见小王子，国王大声嚷： “哈！", "t": [100, 1963]}]}, {"id": "ch10p04", "audio": true, "sents": [{"it": "“Come fa a riconoscermi se non mi ha mai visto?”", "zh": "看见小王子，国王大声嚷： “哈！", "t": [100, 2462]}]}, {"id": "ch10p05", "audio": true, "sents": [{"it": "Non sapeva che per i re il mondo è alquanto semplificato.", "zh": "来了一个老百姓。", "t": [100, 3875]}, {"it": "Tutti gli uomini sono sudditi.", "zh": "” 小王子心想： “他从未见过我，怎么认得出我呢？", "t": [3875, 5600]}]}, {"id": "ch10p06", "audio": true, "sents": [{"it": "“Avvicinati, che ti voglio vedere meglio,” gli disse il re, tutto fiero di essere finalmente il re di qualcuno.", "zh": "” 他不知道，国王们把世界看得很简单，他们以为普天下的人都是他的百姓。", "t": [100, 6387]}]}, {"id": "ch10p07", "audio": true, "sents": [{"it": "Il piccolo principe cercò con gli occhi dove sedersi, ma il pianeta era tutto occupato dallo splendido mantello di ermellino.", "zh": "他对小王子说：“过来，让我好好地瞧瞧你。", "t": [100, 7575]}, {"it": "Quindi rimase in piedi e, poiché era stanco, sbadigliò.", "zh": "” 小王子用眼睛搜寻可坐之处，可是行星被国王豪华的鼬皮塞满了，他只好站着，因为累了，他打了个哈欠。", "t": [7575, 11338]}]}, {"id": "ch10p08", "audio": true, "sents": [{"it": "“È contrario all’etichetta sbadigliare in presenza di un re,” gli disse il monarca.", "zh": "” 小王子用眼睛搜寻可坐之处，可是行星被国王豪华的鼬皮塞满了，他只好站着，因为累了，他打了个哈欠。", "t": [100, 4562]}, {"it": "“Te lo proibisco.”", "zh": "“在国王面前打哈欠，违反礼节，我不准你打哈欠。", "t": [4562, 5576]}]}, {"id": "ch10p09", "audio": true, "sents": [{"it": "“Non posso evitarlo,” rispose il piccolo principe, imbarazzato.", "zh": "“在国王面前打哈欠，违反礼节，我不准你打哈欠。", "t": [100, 4362]}, {"it": "“Ho fatto un lungo viaggio e non ho dormito...”", "zh": "”国王说道。", "t": [4362, 6474]}]}, {"id": "ch10p10", "audio": true, "sents": [{"it": "“Allora,” gli disse il re, “ti ordino di sbadigliare.", "zh": "小王子抱歉地说：“我不是有意的。", "t": [100, 3512]}, {"it": "Sono anni che non vedo nessuno sbadigliare.", "zh": "我长途跋涉，没有睡眠……” “既然如此，”国王对他说，“我命令你打哈欠。", "t": [3512, 6100]}, {"it": "E per me gli sbadigli sono vere e proprie curiosità.", "zh": "我已经多年没看见别人打哈欠了。", "t": [6100, 9412]}, {"it": "Forza!", "zh": "我已经多年没看见别人打哈欠了。", "t": [9412, 10300]}, {"it": "Sbadiglia di nuovo.", "zh": "我已经多年没看见别人打哈欠了。", "t": [10300, 11712]}, {"it": "È un ordine.”", "zh": "依我看，打哈欠挺好玩的。", "t": [11712, 12487]}]}, {"id": "ch10p11", "audio": true, "sents": [{"it": "“Mi mette soggezione...", "zh": "依我看，打哈欠挺好玩的。", "t": [100, 1688]}, {"it": "non riesco...” fece il piccolo principe arrossendo.", "zh": "这是命令。", "t": [1688, 4788]}]}, {"id": "ch10p12", "audio": true, "sents": [{"it": "“Hum!", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [100, 838]}, {"it": "Hum!” rispose il re.", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [838, 2925]}, {"it": "“Allora...", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [2925, 3788]}, {"it": "allora ti ordino di sbadigliare e poi di non...”", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [3788, 6600]}]}, {"id": "ch10p13", "audio": true, "sents": [{"it": "Farfugliava e sembrava indispettito.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [100, 2362]}]}, {"id": "ch10p14", "audio": true, "sents": [{"it": "Al re infatti stava molto a cuore che la sua autorità fosse rispettata.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [100, 4312]}, {"it": "Non tollerava la disobbedienza.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [4312, 6388]}, {"it": "Era un monarca assoluto.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [6388, 8050]}, {"it": "Ma poiché era buono, dava ordini ragionevoli.", "zh": "国王最关心的是别人尊重他的权威，他不允许别人违抗他的命令，他是一个典型的专制君王，但他毕竟是个善良之辈，下达的命令都合乎情理。", "t": [8050, 10863]}]}, {"id": "ch10p15", "audio": true, "sents": [{"it": "“Se ordinassi,” diceva abitualmente, “se ordinassi a un generale di trasformarsi in un uccello marino, e se il generale non obbedisse, non sarebbe colpa del generale.", "zh": "国王最关心的是别人尊重他的权威，他不允许别人违抗他的命令，他是一个典型的专制君王，但他毕竟是个善良之辈，下达的命令都合乎情理。", "t": [100, 10075]}, {"it": "Sarebbe colpa mia.”", "zh": "“要是我向一个将军下令，要他变成海鸟，将军是不愿服从的。", "t": [10075, 11176]}]}, {"id": "ch10p16", "audio": true, "sents": [{"it": "“Posso sedermi?” domandò timidamente il piccolo principe.", "zh": "“要是我向一个将军下令，要他变成海鸟，将军是不愿服从的。", "t": [100, 3737]}]}, {"id": "ch10p17", "audio": true, "sents": [{"it": "“Ti ordino di sederti,” gli rispose il re, tirando cerimoniosamente a sé un lembo del mantello di ermellino.", "zh": "”他说，口齿很伶俐。", "t": [100, 6237]}]}, {"id": "ch10p18", "audio": true, "sents": [{"it": "Ma il piccolo principe era perplesso.", "zh": "”小王子怯怯地问。", "t": [100, 2538]}, {"it": "Il pianeta era minuscolo.", "zh": "“我命令你坐下。", "t": [2538, 4300]}, {"it": "Su cosa poteva mai regnare il re?", "zh": "”国王说，他威风凛凛地一挥白鼬皮皇袍的下摆。", "t": [4300, 6187]}]}, {"id": "ch10p19", "audio": true, "sents": [{"it": "“Maestà...” gli disse, “mi scusi se ho l’ardire di farle una domanda...”", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [100, 4500]}]}, {"id": "ch10p20", "audio": true, "sents": [{"it": "“Ti ordino di farmi una domanda,” si affrettò a dire il re.", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [100, 3087]}]}, {"id": "ch10p21", "audio": true, "sents": [{"it": "“Maestà...", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [100, 1000]}, {"it": "lei su che cosa regna?”", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [1000, 2276]}]}, {"id": "ch10p22", "audio": true, "sents": [{"it": "“Su tutto,” rispose il re, con assoluto candore.", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [100, 3162]}]}, {"id": "ch10p23", "audio": true, "sents": [{"it": "Con un gesto discreto il re indicò il proprio pianeta, gli altri pianeti e le stelle.", "zh": "“陛下……您统治什么？", "t": [100, 5150]}]}, {"id": "ch10p24", "audio": true, "sents": [{"it": "“Su tutto questo?” disse il piccolo principe.", "zh": "” 国王指指他的星球，其他星球，所有的星球。", "t": [100, 2963]}]}, {"id": "ch10p25", "audio": true, "sents": [{"it": "“Su tutto questo...” rispose il re.", "zh": "“所有这一切？", "t": [100, 2300]}]}, {"id": "ch10p26", "audio": true, "sents": [{"it": "Infatti non era soltanto un monarca assoluto, era anche un monarca universale.", "zh": "“所有这一切……”国王答道。", "t": [100, 4924]}]}, {"id": "ch10p27", "audio": true, "sents": [{"it": "“E le stelle le obbediscono?”", "zh": "因为他不但是个专制君主，还是宇宙之王。", "t": [100, 1612]}]}, {"id": "ch10p28", "audio": true, "sents": [{"it": "“Certamente,” disse il re.", "zh": "“所有的星星都听命于您吗？", "t": [100, 1925]}, {"it": "“Io non tollero la disobbedienza.”", "zh": "“所有的星星都听命于您吗？", "t": [1925, 3788]}]}, {"id": "ch10p29", "audio": true, "sents": [{"it": "Il piccolo principe rimase incantato da tanto potere.", "zh": "” “当然啦，”国王说，“它们令出即行。", "t": [100, 3638]}, {"it": "Se l’avesse avuto, avrebbe potuto assistere non a quarantaquattro ma a settantadue, o anche a cento, o anche a duecento tramonti nello stesso giorno, senza dover mai spostare la sedia!", "zh": "” 小王子既赞叹又羡慕国王的权威。", "t": [3638, 15188]}, {"it": "E, poiché si sentiva un po’ triste al ricordo del piccolo pianeta abbandonato, si azzardò a chiedere un favore al re:", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [15188, 22176]}]}, {"id": "ch10p30", "audio": true, "sents": [{"it": "“Vorrei tanto vedere un tramonto...", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [100, 2088]}, {"it": "Per piacere...", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [2088, 3188]}, {"it": "Ordini al sole di tramontare...”", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [3188, 4926]}]}, {"id": "ch10p31", "audio": true, "sents": [{"it": "“Se ordinassi a un generale di volare di fiore in fiore come una farfalla, o di scrivere una tragedia o di trasformarsi in un uccello marino, e se il generale non eseguisse l’ordine ricevuto, chi avrebbe torto fra lui e me?”", "zh": "他壮壮胆，请求国王开恩： “我想观看夕阳西下……求您开恩……命令太阳下去吧……” “如果我命令将军像蝴蝶那样，在花间飞来飞去，或命令他写一部悲剧，或变成海鸟，如果将军接到命令后不愿执行，你说是他的错还是我的错？", "t": [100, 12962]}]}, {"id": "ch10p32", "audio": true, "sents": [{"it": "“Lei,” disse convinto il piccolo principe.", "zh": "” “那是您的错。", "t": [100, 2712]}]}, {"id": "ch10p33", "audio": true, "sents": [{"it": "“Esatto.", "zh": "” “那是您的错。", "t": [100, 1150]}, {"it": "Bisogna pretendere da ciascuno quel che ciascuno può dare,” proseguì il re.", "zh": "”小王子不假思索便脱口而出。", "t": [1150, 5500]}, {"it": "“L’autorità si fonda in primo luogo sulla ragione.", "zh": "”国王说。", "t": [5500, 8525]}, {"it": "Se ordini al tuo popolo di andare a gettarsi in mare, quello farà la rivoluzione.", "zh": "“权威首先必须建筑在理性上。", "t": [8525, 13475]}, {"it": "Ho il diritto di pretendere l’obbedienza perché i miei ordini sono ragionevoli.”", "zh": "我有命令百姓服从的权利，那是因为我的命令合符情理。", "t": [13475, 17562]}]}, {"id": "ch10p34", "audio": true, "sents": [{"it": "“Allora, il mio tramonto?” tornò alla carica il piccolo principe, che non rinunciava mai a una domanda dopo che l’aveva fatta.", "zh": "”小王子问道。", "t": [100, 7400]}]}, {"id": "ch10p35", "audio": true, "sents": [{"it": "“Lo avrai, il tuo tramonto.", "zh": "“你会看到你要求的日落的，我会发布命令。", "t": [100, 2162]}, {"it": "Lo esigerò.", "zh": "“你会看到你要求的日落的，我会发布命令。", "t": [2162, 3325]}, {"it": "Ma, forte della mia esperienza di governo, aspetterò che si presentino le condizioni favorevoli.”", "zh": "要科学管理一个国家，下命令应等时机成熟。", "t": [3325, 9150]}]}, {"id": "ch10p36", "audio": true, "sents": [{"it": "“E quando sarà?” volle sapere il piccolo principe.", "zh": "” “什么时候时机才成熟呢？", "t": [100, 3224]}]}, {"id": "ch10p37", "audio": true, "sents": [{"it": "“Ehm!", "zh": "”小王子问。", "t": [100, 838]}, {"it": "Ehm!” rispose il re, che subito consultò un grosso calendario.", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [838, 5325]}, {"it": "“Ehm, ehm, sarà verso...", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [5325, 7688]}, {"it": "verso...", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [7688, 8575]}, {"it": "sarà stasera, verso le sette e quaranta!", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [8575, 11600]}, {"it": "E vedrai come mi obbedirà!”", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [11600, 13037]}]}, {"id": "ch10p38", "audio": true, "sents": [{"it": "Il piccolo principe sbadigliò.", "zh": "” 小王子打了个哈欠。", "t": [100, 2188]}, {"it": "Si rammaricava per il mancato tramonto.", "zh": "他感到惋惜，因为他的要求泡汤了。", "t": [2188, 4650]}, {"it": "E cominciava ad annoiarsi un po’:", "zh": "他感到惋惜，因为他的要求泡汤了。", "t": [4650, 6450]}]}, {"id": "ch10p39", "audio": true, "sents": [{"it": "“Non ho più niente da fare qui,” disse al re.", "zh": "再说，他已经有点儿腻烦了。", "t": [100, 2700]}, {"it": "“Me ne vado!”", "zh": "“我在这儿没事可干了，”他对国王说，“我要告辞了！", "t": [2700, 3488]}]}, {"id": "ch10p40", "audio": true, "sents": [{"it": "“Non te ne andare,” rispose il re, talmente fiero di avere un suddito.", "zh": "“我在这儿没事可干了，”他对国王说，“我要告辞了！", "t": [100, 4188]}, {"it": "“Non te ne andare, ti faccio ministro!”", "zh": "”国王说，拥有一个百姓，对他来说是一件值得自豪的事。", "t": [4188, 6362]}]}, {"id": "ch10p41", "audio": true, "sents": [{"it": "“Ministro di cosa?”", "zh": "”国王说，拥有一个百姓，对他来说是一件值得自豪的事。", "t": [100, 1187]}]}, {"id": "ch10p42", "audio": true, "sents": [{"it": "“Di...", "zh": "”国王说，拥有一个百姓，对他来说是一件值得自豪的事。", "t": [100, 850]}, {"it": "della Giustizia!”", "zh": "“别走，我任命你为部长！", "t": [850, 1850]}]}, {"id": "ch10p43", "audio": true, "sents": [{"it": "“Ma non c’è nessuno da giudicare!”", "zh": "“别走，我任命你为部长！", "t": [100, 1850]}]}, {"id": "ch10p44", "audio": true, "sents": [{"it": "“Non lo sappiamo,” gli disse il re.", "zh": "” “哪个部的部长？", "t": [100, 2175]}, {"it": "“Non ho ancora visitato tutto il mio regno.", "zh": "” “……司法部。", "t": [2175, 4538]}, {"it": "Sono molto vecchio, non ho spazio per una carrozza e camminare mi stanca.”", "zh": "” “这可就难说了，”国王说，“我还没视察过我的王国呢。", "t": [4538, 8650]}]}, {"id": "ch10p45", "audio": true, "sents": [{"it": "“Oh!", "zh": "” “这可就难说了，”国王说，“我还没视察过我的王国呢。", "t": [100, 812]}, {"it": "Ma io ho già visto,” disse il piccolo principe che si sporse a gettare ancora un’occhiata verso l’altro lato del pianeta.", "zh": "我上了年纪，这儿又没有停马车的地方，走路又太累了。", "t": [812, 7450]}, {"it": "“Non c’è nessuno neanche di là...”", "zh": "” “啊，我已经看过了。", "t": [7450, 9113]}]}, {"id": "ch10p46", "audio": true, "sents": [{"it": "“Allora giudicherai te stesso,” gli rispose il re.", "zh": "”小王子俯身朝星球的另一端又瞟了一眼。", "t": [100, 3000]}, {"it": "“È la cosa più difficile.", "zh": "“那儿也没一个人……” “你就审你自己吧，”国王说，“这是最难办的事。", "t": [3000, 4600]}, {"it": "È molto più difficile giudicare se stessi che giudicare gli altri.", "zh": "“那儿也没一个人……” “你就审你自己吧，”国王说，“这是最难办的事。", "t": [4600, 8300]}, {"it": "Se riesci a giudicarti bene, significa che sei un vero saggio.”", "zh": "审自己比审别人难得多。", "t": [8300, 12050]}]}, {"id": "ch10p47", "audio": true, "sents": [{"it": "“Io,” disse il piccolo principe, “posso giudicare me stesso ovunque.", "zh": "你若能审自己，你就是真正的聪明人。", "t": [100, 4338]}, {"it": "Non occorre che viva qui.”", "zh": "” “我嘛，”小王子说，“无论在什么地方我都能审自己，无需住在这儿。", "t": [4338, 5913]}]}, {"id": "ch10p48", "audio": true, "sents": [{"it": "“Ehm, ehm,” fece il re, “credo proprio che da qualche parte qui sul mio pianeta ci sia un vecchio topo.", "zh": "” “嗯，嗯，我知道。", "t": [100, 6138]}, {"it": "Lo sento la notte.", "zh": "“在我的星球的某一处，有一只老耗子。", "t": [6138, 7612]}, {"it": "Potrai giudicare quel vecchio topo.", "zh": "我在夜里听到的。", "t": [7612, 9762]}, {"it": "Ogni tanto lo condannerai a morte.", "zh": "你可以审这只老耗子。", "t": [9762, 12088]}, {"it": "Così la sua vita dipenderà dalla tua giustizia.", "zh": "隔一段时间判它一次死刑。", "t": [12088, 14925]}, {"it": "E poi lo grazierai, così potremo tenercelo.", "zh": "这样，它的死活就由你的裁判决定了。", "t": [14925, 18000]}, {"it": "Visto che ce n’è uno solo.”", "zh": "这样，它的死活就由你的裁判决定了。", "t": [18000, 19450]}]}, {"id": "ch10p49", "audio": true, "sents": [{"it": "“A me non piace condannare a morte,” rispose il piccolo principe, “e credo proprio che me ne andrò.”", "zh": "但你每一次都要免除它的死罪，你要悠着点，因为就只有这一个犯人了。", "t": [100, 5276]}]}, {"id": "ch10p50", "audio": true, "sents": [{"it": "“No,” disse il re.", "zh": "” “我可不喜欢判人死刑。", "t": [100, 1250]}]}, {"id": "ch10p51", "audio": true, "sents": [{"it": "Ma, finiti i preparativi, il piccolo principe non volle dare un dispiacere al vecchio monarca:", "zh": "” “别走。", "t": [100, 5862]}]}, {"id": "ch10p52", "audio": true, "sents": [{"it": "“Se Sua Maestà volesse essere prontamente obbedita, potrebbe darmi un ordine ragionevole.", "zh": "小王子已经做好走的准备，但他不愿伤老国王的心，他对老国王说：“如果陛下您希望令出即行，您可以向我下达合理的命令。", "t": [100, 5262]}, {"it": "Per esempio, potrebbe ordinarmi di partire fra un minuto.", "zh": "小王子已经做好走的准备，但他不愿伤老国王的心，他对老国王说：“如果陛下您希望令出即行，您可以向我下达合理的命令。", "t": [5262, 8775]}, {"it": "Mi sembra che ci siano le condizioni favorevoli...”", "zh": "例如说，可以命令我在一分钟之内离开。", "t": [8775, 11525]}]}, {"id": "ch10p53", "audio": true, "sents": [{"it": "Poiché il re non rispose nulla, il piccolo principe dapprima esitò, poi con un sospiro se ne andò.", "zh": "我认为时机已经成熟……” 国王一言不发。", "t": [100, 6162]}]}, {"id": "ch10p54", "audio": true, "sents": [{"it": "“Ti nomino mio ambasciatore,” si affrettò allora a gridare il re.", "zh": "国王急忙大叫：“我封你为大使。", "t": [100, 3375]}]}, {"id": "ch10p55", "audio": true, "sents": [{"it": "Aveva un atteggiamento di grande autorità.", "zh": "” 他摆出威风凛凛的神气。", "t": [100, 2362]}]}, {"id": "ch10p56", "audio": true, "sents": [{"it": "“Gli adulti sono proprio curiosi,” disse tra sé il piccolo principe durante il viaggio.", "zh": "小王子一面赶路，一面自言自语： “大人们真怪。", "t": [100, 4738]}]}]}, {"id": "ch11", "title_it": "XI", "title_zh": "第 11 章", "paras": [{"id": "ch11p00", "audio": true, "sents": [{"it": "Il secondo pianeta era abitato da un vanitoso: “Ah!", "zh": "第二颗星球住着一个爱慕虚荣的人。", "t": [100, 3862]}, {"it": "Ecco la visita di un ammiratore!” esclamò da lontano il vanitoso appena scorse il piccolo principe.", "zh": "崇拜我的人访问我啦！", "t": [3862, 9862]}]}, {"id": "ch11p01", "audio": true, "sents": [{"it": "Per i vanitosi, infatti, gli altri uomini sono degli ammiratori.", "zh": "爱慕虚荣的人以为别人都崇拜他。", "t": [100, 4450]}]}, {"id": "ch11p02", "audio": true, "sents": [{"it": "“Buongiorno,” disse il piccolo principe, “ha proprio uno strano cappello!”", "zh": "“您的帽子真怪。", "t": [100, 4375]}]}, {"id": "ch11p03", "audio": true, "sents": [{"it": "“È per salutare,” gli rispose il vanitoso.", "zh": "” “这顶帽子是用来敬礼的，”爱慕虚荣的人说，“有人向我欢呼的时候，我就用它敬礼。", "t": [100, 2662]}, {"it": "“È per salutare quando mi acclamano.", "zh": "” “这顶帽子是用来敬礼的，”爱慕虚荣的人说，“有人向我欢呼的时候，我就用它敬礼。", "t": [2662, 4738]}, {"it": "Disgraziatamente, da qui non passa mai nessuno.”", "zh": "可惜这儿没一个人来。", "t": [4738, 7750]}]}, {"id": "ch11p04", "audio": true, "sents": [{"it": "“Ah sì?” disse il piccolo principe, che non capiva.", "zh": "” “您说什么？", "t": [100, 3563]}]}, {"id": "ch11p05", "audio": true, "sents": [{"it": "“Batti le mani una contro l’altra,” consigliò quindi il vanitoso.", "zh": "“请你鼓掌吧。", "t": [100, 3500]}]}, {"id": "ch11p06", "audio": true, "sents": [{"it": "Il piccolo principe batté le mani una contro l’altra.", "zh": "小王子依言鼓掌。", "t": [100, 3488]}, {"it": "Il vanitoso fece un gran saluto sollevando il cappello.", "zh": "“这比拜访国王有趣多了。", "t": [3488, 6800]}]}, {"id": "ch11p07", "audio": true, "sents": [{"it": "“È più divertente della visita al re,” si disse il piccolo principe.", "zh": "”小王子暗自想。", "t": [100, 3825]}, {"it": "E ricominciò a battere le mani.", "zh": "爱慕虚荣的人又举帽子行礼。", "t": [3825, 5850]}, {"it": "Il vanitoso ricominciò a salutare sollevando il cappello.", "zh": "反复操练了五分钟之后，小王子厌倦了这个单调的游戏。", "t": [5850, 9137]}]}, {"id": "ch11p08", "audio": true, "sents": [{"it": "Dopo cinque minuti il piccolo principe si stancò di quel giochetto sempre uguale:", "zh": "“该怎样做才能让您放下帽子？", "t": [100, 4637]}]}, {"id": "ch11p09", "audio": true, "sents": [{"it": "“E per fare cadere il cappello cosa bisogna fare?” domandò.", "zh": "爱慕虚荣的人听不见这句话。", "t": [100, 3413]}]}, {"id": "ch11p10", "audio": true, "sents": [{"it": "Ma il vanitoso non lo sentì.", "zh": "爱慕虚荣的人只听得见赞扬声。", "t": [100, 2012]}, {"it": "I vanitosi sentono solo le lodi.", "zh": "“你对我真的崇拜到了五体投地？", "t": [2012, 4113]}]}, {"id": "ch11p11", "audio": true, "sents": [{"it": "“Tu mi ammiri davvero molto?” domandò al piccolo principe.", "zh": "”他问小王子。", "t": [100, 3350]}]}, {"id": "ch11p12", "audio": true, "sents": [{"it": "“Che cosa significa ‘ammirare’?”", "zh": "“什么叫做‘崇拜’？", "t": [100, 1700]}]}, {"id": "ch11p13", "audio": true, "sents": [{"it": "“‘Ammirare’ significa riconoscere che sono l’uomo più bello, meglio vestito, più ricco e più intelligente del pianeta.”", "zh": "” “‘崇拜’就是承认我是星球上最帅、衣着最讲究、最富有、最聪明的人。", "t": [100, 6974]}]}, {"id": "ch11p14", "audio": true, "sents": [{"it": "“Ma sei solo, sul tuo pianeta!”", "zh": "” “你就让我享受被人崇拜的快乐吧，仍然崇拜我吧！", "t": [100, 2124]}]}, {"id": "ch11p15", "audio": true, "sents": [{"it": "“Fammi questo favore.", "zh": "” “你就让我享受被人崇拜的快乐吧，仍然崇拜我吧！", "t": [100, 1538]}, {"it": "Ammirami lo stesso!”", "zh": "” “你就让我享受被人崇拜的快乐吧，仍然崇拜我吧！", "t": [1538, 2775]}]}, {"id": "ch11p16", "audio": true, "sents": [{"it": "“Ti ammiro,” disse il piccolo principe alzando un po’ le spalle, “ma che cosa te ne viene?”", "zh": "” “我崇拜你，”小王子耸耸肩，“这有什么值得你快乐的呢？", "t": [100, 4888]}]}, {"id": "ch11p17", "audio": true, "sents": [{"it": "E il piccolo principe se ne andò.", "zh": "” 小王子走了。", "t": [100, 1900]}]}, {"id": "ch11p18", "audio": true, "sents": [{"it": "“Gli adulti sono proprio strani,” disse semplicemente tra sé durante il viaggio.", "zh": "”小王子一边赶路一边对自己说。", "t": [100, 4400]}]}]}, {"id": "ch12", "title_it": "XII", "title_zh": "第 12 章", "paras": [{"id": "ch12p00", "audio": true, "sents": [{"it": "Il pianeta seguente era abitato da un bevitore.", "zh": "下一颗星球住着一个酒鬼。", "t": [100, 2887]}]}, {"id": "ch12p01", "audio": true, "sents": [{"it": "La visita fu molto breve, ma destò nel piccolo principe una gran malinconia:", "zh": "这次访问时间不长，但小王子极为不快。", "t": [100, 4788]}]}, {"id": "ch12p02", "audio": true, "sents": [{"it": "“Che fai qui?” disse al bevitore, che trovò seduto davanti a una sfilza di bottiglie, metà delle quali vuote e metà piene.", "zh": "”小王子看见酒鬼在喝闷酒，面前摆着一大堆空瓶子和装满了酒的瓶子，就这样问他。", "t": [100, 7438]}]}, {"id": "ch12p03", "audio": true, "sents": [{"it": "“Bevo,” rispose il bevitore con aria cupa.", "zh": "“我在喝酒呀。", "t": [100, 2375]}]}, {"id": "ch12p04", "audio": true, "sents": [{"it": "“Perché bevi?” gli domandò il piccolo principe.", "zh": "“你为什么喝酒呢？", "t": [100, 3050]}]}, {"id": "ch12p05", "audio": true, "sents": [{"it": "“Per dimenticare,” rispose il bevitore.", "zh": "“为了忘记呗。", "t": [100, 2237]}]}, {"id": "ch12p06", "audio": true, "sents": [{"it": "“Per dimenticare cosa?” volle sapere il piccolo principe, che già lo compativa.", "zh": "“为了忘记什么？", "t": [100, 4975]}]}, {"id": "ch12p07", "audio": true, "sents": [{"it": "“Per dimenticare che mi vergogno,” ammise il bevitore abbassando la testa.", "zh": "“为了忘记羞愧呗。", "t": [100, 4100]}]}, {"id": "ch12p08", "audio": true, "sents": [{"it": "“Ti vergogni di cosa?” lo interrogò il piccolo principe che desiderava aiutarlo.", "zh": "“为了什么事羞愧呢？", "t": [100, 4938]}]}, {"id": "ch12p09", "audio": true, "sents": [{"it": "“Mi vergogno di bere!” concluse il bevitore che si chiuse definitivamente nel silenzio.", "zh": "”酒鬼讲完后，闭了嘴巴不再讲话。", "t": [100, 5112]}]}, {"id": "ch12p10", "audio": true, "sents": [{"it": "E il piccolo principe se ne andò, perplesso.", "zh": "小王子走了。", "t": [100, 2750]}]}, {"id": "ch12p11", "audio": true, "sents": [{"it": "“Gli adulti sono proprio molto strani,” diceva tra sé durante il viaggio.", "zh": "”小王子一边赶路一边想。", "t": [100, 3913]}]}]}, {"id": "ch13", "title_it": "XIII", "title_zh": "第 13 章", "paras": [{"id": "ch13p00", "audio": true, "sents": [{"it": "Il quarto pianeta era quello dell’uomo d’affari.", "zh": "第四颗星球是商人的星球。", "t": [100, 2912]}, {"it": "Era un uomo talmente occupato che non alzò neppure la testa all’arrivo del piccolo principe.", "zh": "“您好！", "t": [2912, 8074]}]}, {"id": "ch13p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse quest’ultimo.", "zh": "“您的香烟已经熄灭了。", "t": [100, 2200]}, {"it": "“Ha la sigaretta spenta.”", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [2200, 3537]}]}, {"id": "ch13p02", "audio": true, "sents": [{"it": "“Tre più due cinque.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [100, 1488]}, {"it": "Cinque più sette dodici.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [1488, 3750]}, {"it": "Dodici più tre quindici.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [3750, 5975]}, {"it": "Buongiorno.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [5975, 7025]}, {"it": "Quindici più sette ventidue.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [7025, 8988]}, {"it": "Ventidue più sei ventotto.", "zh": "二十六加五等于三十一。", "t": [8988, 10888]}, {"it": "Non ho tempo di riaccenderla.", "zh": "嗬！", "t": [10888, 12838]}, {"it": "Ventisei più cinque trentuno.", "zh": "一共是五亿零一百六十二万二千七百三十一。", "t": [12838, 14950]}, {"it": "Uff!", "zh": "一共是五亿零一百六十二万二千七百三十一。", "t": [14950, 15712]}, {"it": "Quindi fanno cinquecentouno milioni seicento ventiduemila settecentotrentuno.”", "zh": "” “什么？", "t": [15712, 20626]}]}, {"id": "ch13p03", "audio": true, "sents": [{"it": "“Cinquecento milioni di cosa?”", "zh": "五亿零一百……我也闹糊涂了……我的活太忙了！", "t": [100, 1737]}]}, {"id": "ch13p04", "audio": true, "sents": [{"it": "“Eh?", "zh": "五亿零一百……我也闹糊涂了……我的活太忙了！", "t": [100, 712]}, {"it": "Sei ancora qui?", "zh": "我是个正经人，不爱讲废话！", "t": [712, 1988]}, {"it": "Cinquecentouno milioni di...", "zh": "我是个正经人，不爱讲废话！", "t": [1988, 3950]}, {"it": "non mi ricordo più...", "zh": "二加五等于七……” “五亿零一百万个什么？", "t": [3950, 5350]}, {"it": "ho tanto di quel lavoro!", "zh": "二加五等于七……” “五亿零一百万个什么？", "t": [5350, 6925]}, {"it": "Sono una persona seria, io, mica perdo tempo con le stupidaggini!", "zh": "”小王子还在追问，他一旦提出问题，绝不中途而废。", "t": [6925, 11300]}, {"it": "Due più cinque sette...”", "zh": "”小王子还在追问，他一旦提出问题，绝不中途而废。", "t": [11300, 12825]}]}, {"id": "ch13p05", "audio": true, "sents": [{"it": "“Cinquecentouno milioni di cosa?” ripeté il piccolo principe che in vita sua non aveva mai rinunciato a una domanda dopo che l’aveva fatta.", "zh": "商人抬起头： “我住在这个星球已经五十四年了，只受过三次干扰。", "t": [100, 7813]}]}, {"id": "ch13p06", "audio": true, "sents": [{"it": "L’uomo d’affari alzò la testa:", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [100, 1987]}]}, {"id": "ch13p07", "audio": true, "sents": [{"it": "“Abito in questo pianeta da cinquantaquattro anni e sono stato disturbato solo tre volte.", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [100, 5500]}, {"it": "La prima volta è stata ventidue anni fa, da un maggiolino caduto chissà da dove.", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [5500, 10412]}, {"it": "Faceva un rumore spaventoso e mi sono scappati quattro errori in un’addizione.", "zh": "我刚好算到五亿零一百万个……” “五亿零一百万个什么？", "t": [10412, 15225]}, {"it": "La seconda volta è stata undici anni fa, da un attacco di reumatismi.", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [15225, 19650]}, {"it": "Non faccio abbastanza moto.", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [19650, 21438]}, {"it": "Non ho tempo di andare a spasso.", "zh": "” “苍蝇吗？", "t": [21438, 23388]}, {"it": "Sono una persona seria, io.", "zh": "” “不是，是闪闪发亮的小东西。", "t": [23388, 25550]}, {"it": "La terza volta, eccola!", "zh": "” “不是，是闪闪发亮的小东西。", "t": [25550, 27688]}, {"it": "Dicevo quindi cinquecentouno milioni...”", "zh": "” “蜜蜂吗？", "t": [27688, 30176]}]}, {"id": "ch13p08", "audio": true, "sents": [{"it": "“Milioni di cosa?”", "zh": "” “不是，是金色的小东西，能教闲得发慌的人发痴做梦的小东西，可我是正经人，我没时间遐想做梦。", "t": [100, 1125]}]}, {"id": "ch13p09", "audio": true, "sents": [{"it": "L’uomo d’affari capì che non aveva speranza di essere lasciato in pace:", "zh": "” “不是，是金色的小东西，能教闲得发慌的人发痴做梦的小东西，可我是正经人，我没时间遐想做梦。", "t": [100, 3724]}]}, {"id": "ch13p10", "audio": true, "sents": [{"it": "“Milioni di quelle cosettine che ogni tanto si vedono in cielo.”", "zh": "是满天的繁星吗？", "t": [100, 3400]}]}, {"id": "ch13p11", "audio": true, "sents": [{"it": "“Mosche?”", "zh": "满天的星星。", "t": [100, 738]}]}, {"id": "ch13p12", "audio": true, "sents": [{"it": "“Ma no, quelle cosettine gialle.”", "zh": "满天的星星。", "t": [100, 2237]}]}, {"id": "ch13p13", "audio": true, "sents": [{"it": "“Api?”", "zh": "” “你要五亿多颗星星做什么？", "t": [100, 600]}]}, {"id": "ch13p14", "audio": true, "sents": [{"it": "“Ma no, quelle cosettine dorate che fanno sognare i perdigiorno.", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [100, 4138]}, {"it": "Io però sono una persona seria!", "zh": "我是个一丝不苟的人，我务求精确。", "t": [4138, 6338]}, {"it": "Mica ho tempo di perdermi nei sogni.”", "zh": "” “你要星星干什么？", "t": [6338, 8513]}]}, {"id": "ch13p15", "audio": true, "sents": [{"it": "“Ah, le stelle?”", "zh": "” “你要星星干什么？", "t": [100, 1174]}]}, {"id": "ch13p16", "audio": true, "sents": [{"it": "“Esatto.", "zh": "” “我要它们干什么？", "t": [100, 1150]}, {"it": "Le stelle.”", "zh": "” “我要它们干什么？", "t": [1150, 1976]}]}, {"id": "ch13p17", "audio": true, "sents": [{"it": "“E cosa te ne fai di cinquecento milioni di stelle?”", "zh": "” “没什么用。", "t": [100, 2825]}]}, {"id": "ch13p18", "audio": true, "sents": [{"it": "“Cinquecentouno milioni seicentoventiduemila settecentotrentuno.", "zh": "” “你拥有星星？", "t": [100, 4662]}, {"it": "Sono una persona seria, io, una persona precisa!”", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [4662, 8300]}]}, {"id": "ch13p19", "audio": true, "sents": [{"it": "“E cosa te ne fai di tutte quelle stelle?”", "zh": "大不相同。", "t": [100, 2200]}]}, {"id": "ch13p20", "audio": true, "sents": [{"it": "“Cosa me ne faccio?”", "zh": "” “你拥有星星又怎么样呢？", "t": [100, 1037]}]}, {"id": "ch13p21", "audio": true, "sents": [{"it": "“Sì.”", "zh": "” “你拥有星星又怎么样呢？", "t": [100, 562]}]}, {"id": "ch13p22", "audio": true, "sents": [{"it": "“Niente.", "zh": "” “你拥有星星又怎么样呢？", "t": [100, 1025]}, {"it": "Le possiedo.”", "zh": "” “拥有了星星，我就成了大富翁呗。", "t": [1025, 1912]}]}, {"id": "ch13p23", "audio": true, "sents": [{"it": "“Possiedi le stelle?”", "zh": "” “拥有了星星，我就成了大富翁呗。", "t": [100, 1224]}]}, {"id": "ch13p24", "audio": true, "sents": [{"it": "“Sì.”", "zh": "” “拥有了星星，我就成了大富翁呗。", "t": [100, 562]}]}, {"id": "ch13p25", "audio": true, "sents": [{"it": "“Ma io ho già visto un re che...”", "zh": "” “成了富翁有什么好处？", "t": [100, 1676]}]}, {"id": "ch13p26", "audio": true, "sents": [{"it": "“I re non possiedono niente.", "zh": "” “成了富翁有什么好处？", "t": [100, 2012]}, {"it": "Loro ‘regnano’.", "zh": "” “如果又有人发现了新的星星，我就把它们买下来呀。", "t": [2012, 3138]}, {"it": "È ben diverso.”", "zh": "” “如果又有人发现了新的星星，我就把它们买下来呀。", "t": [3138, 4062]}]}, {"id": "ch13p27", "audio": true, "sents": [{"it": "“E a cosa ti serve possedere le stelle?”", "zh": "” “如果又有人发现了新的星星，我就把它们买下来呀。", "t": [100, 2200]}]}, {"id": "ch13p28", "audio": true, "sents": [{"it": "“Mi serve a essere ricco.”", "zh": "” 小王子心想：“这个人的推理方法有点像我见过的那个酒鬼。", "t": [100, 1387]}]}, {"id": "ch13p29", "audio": true, "sents": [{"it": "“E a cosa ti serve essere ricco?”", "zh": "” 小王子心想：“这个人的推理方法有点像我见过的那个酒鬼。", "t": [100, 1763]}]}, {"id": "ch13p30", "audio": true, "sents": [{"it": "“A comprare altre stelle, se qualcuno le trova.”", "zh": "” 他仍然提出问题： “怎样才能拥有星星？", "t": [100, 2763]}]}, {"id": "ch13p31", "audio": true, "sents": [{"it": "“Questo qui,” disse tra sé il piccolo principe, “ragiona un po’ come il mio ubriacone.”", "zh": "” 商人烦了，没好气地反问： “你说，这满天的星星属于谁？", "t": [100, 4787]}]}, {"id": "ch13p32", "audio": true, "sents": [{"it": "Tuttavia fece ancora qualche domanda:", "zh": "” “我不知道。", "t": [100, 2138]}]}, {"id": "ch13p33", "audio": true, "sents": [{"it": "“Come si fa a possedere le stelle?”", "zh": "” “那么它们属于我。", "t": [100, 1875]}]}, {"id": "ch13p34", "audio": true, "sents": [{"it": "“Di chi sono?” ribatté, stizzito, l’uomo d’affari.", "zh": "因为我是第一个想到要拥有它们的人。", "t": [100, 4000]}]}, {"id": "ch13p35", "audio": true, "sents": [{"it": "“Non lo so.", "zh": "” “光是想就行了吗？", "t": [100, 1012]}, {"it": "Di nessuno.”", "zh": "” “光是想就行了吗？", "t": [1012, 1925]}]}, {"id": "ch13p36", "audio": true, "sents": [{"it": "“Allora sono mie, perché ho avuto per primo l’idea.”", "zh": "” “那还用说吗？", "t": [100, 2950]}]}, {"id": "ch13p37", "audio": true, "sents": [{"it": "“È sufficiente?”", "zh": "你发现一颗没有主人的钻石，这颗钻石就归你了。", "t": [100, 1125]}]}, {"id": "ch13p38", "audio": true, "sents": [{"it": "“Certo.", "zh": "你发现一颗没有主人的钻石，这颗钻石就归你了。", "t": [100, 1025]}, {"it": "Quando trovi un diamante che non è di nessuno, allora è tuo.", "zh": "你发现一个不属于任何人的岛，这岛就是你的了。", "t": [1025, 4962]}, {"it": "Quando sei il primo ad avere un’idea, la fai brevettare ed è tua.", "zh": "你头一个想出一个主意，你就可以申请专利，这个主意就是你的了。", "t": [4962, 9075]}, {"it": "E io possiedo le stelle, perché a nessuno prima di me è venuto in mente di possederle.”", "zh": "而我呢，我拥有星星，因为在我之前没有一个人想过要拥有星星。", "t": [9075, 13774]}]}, {"id": "ch13p39", "audio": true, "sents": [{"it": "“È vero,” disse il piccolo principe.", "zh": "” “这倒是真的。", "t": [100, 2275]}, {"it": "“E che cosa te ne fai?”", "zh": "” “这倒是真的。", "t": [2275, 3476]}]}, {"id": "ch13p40", "audio": true, "sents": [{"it": "“Le gestisco.", "zh": "”小王子想。", "t": [100, 1350]}, {"it": "Le conto e le riconto,” disse l’uomo d’affari.", "zh": "” “我管理它们。", "t": [1350, 4188]}, {"it": "“È difficile.", "zh": "我数它们，一次又一次地数它们。", "t": [4188, 5275]}, {"it": "Ma io sono un uomo serio!”", "zh": "我数它们，一次又一次地数它们。", "t": [5275, 6862]}]}, {"id": "ch13p41", "audio": true, "sents": [{"it": "Il piccolo principe non era ancora soddisfatto.", "zh": "“这是件困难的事，但我是个正经人！", "t": [100, 2887]}]}, {"id": "ch13p42", "audio": true, "sents": [{"it": "“Se possiedo un fazzoletto posso mettermelo al collo e portarlo con me.", "zh": "“这是件困难的事，但我是个正经人！", "t": [100, 4250]}, {"it": "Se possiedo un fiore posso coglier­lo e portarlo con me.", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [4250, 7612]}, {"it": "Ma tu non puoi cogliere le stelle!”", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [7612, 9526]}]}, {"id": "ch13p43", "audio": true, "sents": [{"it": "“No, ma posso metterle in banca.”", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [100, 2237]}]}, {"id": "ch13p44", "audio": true, "sents": [{"it": "“Che cosa vuol dire?”", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [100, 1162]}]}, {"id": "ch13p45", "audio": true, "sents": [{"it": "“Vuol dire che scrivo su un foglio il numero delle mie stelle.", "zh": "” “这是怎么回事？", "t": [100, 3562]}, {"it": "E poi chiudo a chiave il foglio in un cassetto.”", "zh": "” “我在一张小纸条上写上我的星星的数目，然后把它锁进抽屉里。", "t": [3562, 6050]}]}, {"id": "ch13p46", "audio": true, "sents": [{"it": "“Ed è sufficiente?”", "zh": "” “我在一张小纸条上写上我的星星的数目，然后把它锁进抽屉里。", "t": [100, 1163]}]}, {"id": "ch13p47", "audio": true, "sents": [{"it": "“Certo!”", "zh": "” “就这样？", "t": [100, 762]}]}, {"id": "ch13p48", "audio": true, "sents": [{"it": "“È divertente,” pensò il piccolo principe.", "zh": "” “就这样？", "t": [100, 2650]}, {"it": "“È molto poetico.", "zh": "” “这就行啦！", "t": [2650, 4038]}, {"it": "Ma non è granché serio.”", "zh": "” 小王子想：“这倒是挺好玩的，还挺有诗意的呢，但算不上是严肃正经的事儿。", "t": [4038, 5425]}]}, {"id": "ch13p49", "audio": true, "sents": [{"it": "Il piccolo principe aveva idee molto diverse dagli adulti riguardo alle cose serie.", "zh": "” 小王子想：“这倒是挺好玩的，还挺有诗意的呢，但算不上是严肃正经的事儿。", "t": [100, 4713]}]}, {"id": "ch13p50", "audio": true, "sents": [{"it": "“Io,” disse ancora, “possiedo una rosa che innaffio tutti i giorni.", "zh": "” 对“严肃正经的事儿”，小王子的看法与大人的看法极不相同。", "t": [100, 4338]}, {"it": "Possiedo tre vulcani che pulisco tutte le settimane.", "zh": "小王子说：“我呢，我拥有一朵花，我就天天给它浇水；我拥有三座火山，我就每个星期给它们疏通清理。", "t": [4338, 7762]}, {"it": "Perché pulisco anche quello spento.", "zh": "小王子说：“我呢，我拥有一朵花，我就天天给它浇水；我拥有三座火山，我就每个星期给它们疏通清理。", "t": [7762, 10012]}, {"it": "Non si sa mai.", "zh": "小王子说：“我呢，我拥有一朵花，我就天天给它浇水；我拥有三座火山，我就每个星期给它们疏通清理。", "t": [10012, 11175]}, {"it": "Il fatto che io li possieda è utile ai miei vulcani ed è utile alla mia rosa.", "zh": "我也疏通死火山，因为日后的事难说。", "t": [11175, 15950]}, {"it": "Invece tu non sei utile alle stelle...”", "zh": "我能做对火山、对花有益的事，才叫做拥有它们。", "t": [15950, 18037]}]}, {"id": "ch13p51", "audio": true, "sents": [{"it": "L’uomo d’affari aprì la bocca ma non trovò nulla da rispondere, e il piccolo principe se ne andò.", "zh": "” 商人张口结舌，找不到话回答。", "t": [100, 5387]}]}, {"id": "ch13p52", "audio": true, "sents": [{"it": "“Gli adulti sono veramente stravaganti,” diceva semplicemente tra sé durante il viaggio.", "zh": "“大人们真是怪得没法说。", "t": [100, 4750]}]}]}, {"id": "ch14", "title_it": "XIV", "title_zh": "第 14 章", "paras": [{"id": "ch14p00", "audio": true, "sents": [{"it": "Il quinto pianeta era davvero curioso.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [100, 2525]}, {"it": "Era il più piccolo di tutti.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [2525, 4412]}, {"it": "C’era spazio solo per un lampione e un lampionaio.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [4412, 7625]}, {"it": "Il piccolo principe non riusciva a spiegarsi a cosa potessero servire, in un punto del cielo, su un pia­neta senza case né popolazione, un lampione e un lampionaio.", "zh": "小王子怎么想都想不明白，这颗位于太空中不起眼的星球，既没有房屋，又没有居民，这路灯和点灯人有何用途。", "t": [7625, 17800]}, {"it": "Tuttavia disse tra sé:", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [17800, 19088]}]}, {"id": "ch14p01", "audio": true, "sents": [{"it": "“Forse quest’uomo è assurdo.", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [100, 2188]}, {"it": "Però è meno assurdo del re, del vanitoso, dell’uomo d’affari e del bevitore.", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [2188, 7412]}, {"it": "Almeno il suo lavoro ha un senso.", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [7412, 9538]}, {"it": "Quando accende il lampione, è come se facesse nascere una stella in più, o un fiore.", "zh": "他点亮路灯，如同给太空增添一颗星星，或一朵鲜花；他熄灭路灯，就是让花儿和星星休息睡眠。", "t": [9538, 14925]}, {"it": "Quando spegne il lampione, addormenta il fiore o la stella.", "zh": "他点亮路灯，如同给太空增添一颗星星，或一朵鲜花；他熄灭路灯，就是让花儿和星星休息睡眠。", "t": [14925, 18675]}, {"it": "È una bellissima occupazione.", "zh": "这活儿充满诗意，既然充满诗意，那就是有益的工作。", "t": [18675, 20712]}, {"it": "Ed è davvero utile perché è bella!”", "zh": "这活儿充满诗意，既然充满诗意，那就是有益的工作。", "t": [20712, 22513]}]}, {"id": "ch14p02", "audio": true, "sents": [{"it": "Quando giunse sul pianeta, salutò rispettosamente il lampionaio:", "zh": "” 他走近星球，毕恭毕敬地向点灯人行礼： “你好。", "t": [100, 4137]}]}, {"id": "ch14p03", "audio": true, "sents": [{"it": "“Buongiorno.", "zh": "你刚才为什么把灯灭了？", "t": [100, 1150]}, {"it": "Perché hai spento il tuo lampione?”", "zh": "你刚才为什么把灯灭了？", "t": [1150, 2850]}]}, {"id": "ch14p04", "audio": true, "sents": [{"it": "“Sono le direttive,” rispose il lampionaio.", "zh": "”点灯人答道。", "t": [100, 2738]}, {"it": "“Buongiorno.”", "zh": "“早上好。", "t": [2738, 3526]}]}, {"id": "ch14p05", "audio": true, "sents": [{"it": "“Quali direttive?”", "zh": "” “什么规定？", "t": [100, 1200]}]}, {"id": "ch14p06", "audio": true, "sents": [{"it": "“Di spegnere il lampione.", "zh": "” “熄灯的规定。", "t": [100, 1800]}, {"it": "Buonasera.”", "zh": "” “熄灯的规定。", "t": [1800, 2588]}]}, {"id": "ch14p07", "audio": true, "sents": [{"it": "E lo riaccese.", "zh": "晚上好。", "t": [100, 1038]}]}, {"id": "ch14p08", "audio": true, "sents": [{"it": "“Ma perché l’hai riacceso?”", "zh": "” 他点上灯。", "t": [100, 1474]}]}, {"id": "ch14p09", "audio": true, "sents": [{"it": "“Sono le direttive,” rispose il lampionaio.", "zh": "“你怎么又把灯点着了？", "t": [100, 2476]}]}, {"id": "ch14p10", "audio": true, "sents": [{"it": "“Non capisco,” disse il piccolo principe.", "zh": "”点灯人说。", "t": [100, 2375]}]}, {"id": "ch14p11", "audio": true, "sents": [{"it": "“Non c’è niente da capire,” disse il lampionaio.", "zh": "”小王子说。", "t": [100, 2912]}, {"it": "“Le direttive sono queste.", "zh": "“用不着明白，”点灯人说，“规定就是规定。", "t": [2912, 4738]}, {"it": "Buongiorno.”", "zh": "早上好。", "t": [4738, 5526]}]}, {"id": "ch14p12", "audio": true, "sents": [{"it": "E spense il lampione.", "zh": "早上好。", "t": [100, 1450]}]}, {"id": "ch14p13", "audio": true, "sents": [{"it": "Poi si asciugò la fronte con un fazzoletto a quadretti bianco e rosso.", "zh": "然后他用红方格手帕抹抹额头。", "t": [100, 4074]}]}, {"id": "ch14p14", "audio": true, "sents": [{"it": "“Il mio è proprio un mestiere orribile.", "zh": "“这活儿可把我累苦了。", "t": [100, 2412]}, {"it": "Una volta era ancora fattibile.", "zh": "从前的规定还合乎情理，早上熄灯，晚上点灯。", "t": [2412, 4500]}, {"it": "Spegnevo al mattino e accendevo alla sera.", "zh": "从前的规定还合乎情理，早上熄灯，晚上点灯。", "t": [4500, 7100]}, {"it": "Avevo il resto della giornata per riposarmi, e il resto della notte per dormire...”", "zh": "熄灯之后休息，点灯之后睡觉……” “现在的规定改了？", "t": [7100, 11750]}]}, {"id": "ch14p15", "audio": true, "sents": [{"it": "“E da allora sono cambiate le direttive?”", "zh": "” “规定倒没有改，”点灯人说，“倒霉就倒霉在这儿！", "t": [100, 2237]}]}, {"id": "ch14p16", "audio": true, "sents": [{"it": "“Le direttive non sono cambiate,” disse il lampionaio.", "zh": "行星一年转得比一年快，而规定却没有改变！", "t": [100, 3562]}, {"it": "“È proprio questo il dramma!", "zh": "” “这是怎么回事？", "t": [3562, 5275]}, {"it": "Con il passare degli anni il pianeta ha cominciato a ruotare sempre più in fretta, ma le direttive non sono cambiate!”", "zh": "” “现在它一分钟转一次，我连一秒钟的休息时间都没有。", "t": [5275, 11812]}]}, {"id": "ch14p17", "audio": true, "sents": [{"it": "“E allora?” disse il piccolo principe.", "zh": "每分钟要点亮、熄灭一次灯火！", "t": [100, 2550]}]}, {"id": "ch14p18", "audio": true, "sents": [{"it": "“Allora adesso che fa un giro al minuto non ho più un istante di riposo.", "zh": "你这儿一分钟就是一天？", "t": [100, 4612]}, {"it": "Accendo e spengo una volta al minuto!”", "zh": "” “怎么不可能，”点灯人说，“我们已经聊了一个月了。", "t": [4612, 6725]}]}, {"id": "ch14p19", "audio": true, "sents": [{"it": "“Questo sì che è buffo!", "zh": "” “怎么不可能，”点灯人说，“我们已经聊了一个月了。", "t": [100, 1612]}, {"it": "Da te i giorni durano un minuto!”", "zh": "” “一个月？", "t": [1612, 3513]}]}, {"id": "ch14p20", "audio": true, "sents": [{"it": "“Non è affatto buffo,” disse il lampionaio.", "zh": "” “是的，三十分钟，就是三十天！", "t": [100, 2712]}, {"it": "“Noi due stiamo parlando già da un mese.”", "zh": "晚上好。", "t": [2712, 4912]}]}, {"id": "ch14p21", "audio": true, "sents": [{"it": "“Da un mese?”", "zh": "” 点灯人又点亮了路灯。", "t": [100, 850]}]}, {"id": "ch14p22", "audio": true, "sents": [{"it": "“Sì.", "zh": "” 点灯人又点亮了路灯。", "t": [100, 825]}, {"it": "Trenta minuti.", "zh": "” 点灯人又点亮了路灯。", "t": [825, 1962]}, {"it": "Trenta giorni!", "zh": "小王子看着他，小王子喜欢这个一丝不苟，按章办事的点灯人。", "t": [1962, 3175]}, {"it": "Buonasera.”", "zh": "小王子看着他，小王子喜欢这个一丝不苟，按章办事的点灯人。", "t": [3175, 3963]}]}, {"id": "ch14p23", "audio": true, "sents": [{"it": "E riaccese il lampione.", "zh": "小王子看着他，小王子喜欢这个一丝不苟，按章办事的点灯人。", "t": [100, 1600]}]}, {"id": "ch14p24", "audio": true, "sents": [{"it": "Il piccolo principe lo guardò e provò simpatia per quel lampionaio così ligio alle direttive che aveva ricevuto.", "zh": "他记起自己以前必须挪动椅子才能看到日落的情景。", "t": [100, 6137]}]}, {"id": "ch14p25", "audio": true, "sents": [{"it": "“Sai...", "zh": "他很愿意帮助他的朋友。", "t": [100, 812]}, {"it": "posso insegnarti un trucco per riposarti quando vuoi...”", "zh": "他很愿意帮助他的朋友。", "t": [812, 3663]}]}, {"id": "ch14p26", "audio": true, "sents": [{"it": "“Io lo voglio sempre,” disse il lampionaio.", "zh": "“你知道吗……我有个办法，你什么时候想休息就可以休息……” “我一直想找个办法呢。", "t": [100, 2313]}]}, {"id": "ch14p27", "audio": true, "sents": [{"it": "Un uomo, infatti, può essere contemporaneamente coscienzioso e pigro.", "zh": "”点灯人说。", "t": [100, 5000]}]}, {"id": "ch14p28", "audio": true, "sents": [{"it": "Il piccolo principe proseguì:", "zh": "有个办法既能按章办事又能偷懒就好了。", "t": [100, 1913]}]}, {"id": "ch14p29", "audio": true, "sents": [{"it": "“Il tuo pianeta è talmente piccolo che in tre falcate ne fai il giro.", "zh": "小王子继续说道： “你的星球这么小，走三步就绕了一个圈。", "t": [100, 4212]}, {"it": "Per rimanere sempre al sole basta che cammini molto piano.", "zh": "你只要放慢脚步，太阳就老在你的头顶上。", "t": [4212, 7762]}, {"it": "Quando vorrai riposarti, dovrai solo camminare...", "zh": "你只要放慢脚步，太阳就老在你的头顶上。", "t": [7762, 10962]}, {"it": "e il giorno durerà tutto il tempo che vorrai.”", "zh": "你想休息的时候，你就往前走……你的白天要多长有多长。", "t": [10962, 13350]}]}, {"id": "ch14p30", "audio": true, "sents": [{"it": "“Sai che m’importa!” disse il lampionaio.", "zh": "你想休息的时候，你就往前走……你的白天要多长有多长。", "t": [100, 3375]}, {"it": "“A me nella vita piace dormire.”", "zh": "” “这个办法解决不了我多大的问题，”点灯人说，“我平生喜欢的就是睡觉。", "t": [3375, 4900]}]}, {"id": "ch14p31", "audio": true, "sents": [{"it": "“Proprio una bella scalogna,” disse il piccolo principe.", "zh": "” “这个办法解决不了我多大的问题，”点灯人说，“我平生喜欢的就是睡觉。", "t": [100, 3075]}]}, {"id": "ch14p32", "audio": true, "sents": [{"it": "“Sì, una bella scalogna davvero,” disse il lampionaio.", "zh": "” “那你就太不走运了。", "t": [100, 3875]}, {"it": "“Buongiorno.”", "zh": "“我真的不走运。", "t": [3875, 4663]}]}, {"id": "ch14p33", "audio": true, "sents": [{"it": "E spense il lampione.", "zh": "”点灯人说。", "t": [100, 1450]}]}, {"id": "ch14p34", "audio": true, "sents": [{"it": "“Quell’uomo sarebbe disprezzato da tutti gli altri,” disse tra sé il piccolo principe, proseguendo il suo viaggio, “dal re, dal vanitoso, dal bevitore, dall’uomo d’affari.", "zh": "小王子一面赶路一面想：“这个人会被其他人瞧不起的。", "t": [100, 10700]}, {"it": "Tuttavia è l’unico che non mi sembra ridicolo.", "zh": "会被国王、爱慕虚荣的人、酒鬼、商人瞧不起。", "t": [10700, 13325]}, {"it": "Forse perché si occupa di qualcos’altro che non sia se stesso.”", "zh": "可是他是惟一的我不觉得可笑的人，也许因为他没有光顾自己吧！", "t": [13325, 16238]}]}, {"id": "ch14p35", "audio": true, "sents": [{"it": "Ebbe un sospiro di rammarico e si disse ancora:", "zh": "可是他是惟一的我不觉得可笑的人，也许因为他没有光顾自己吧！", "t": [100, 2825]}]}, {"id": "ch14p36", "audio": true, "sents": [{"it": "“Quell’uomo è l’unico che avrei potuto farmi amico.", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [100, 3000]}, {"it": "Ma il suo pianeta è davvero troppo piccolo.", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [3000, 5512]}, {"it": "Non c’è posto per due...”", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [5512, 6912]}]}, {"id": "ch14p37", "audio": true, "sents": [{"it": "Il piccolo principe non osava ammettere che rimpiangeva quel pianeta benedetto soprattutto per i millequattrocento quaranta tramonti ogni ventiquattro ore!", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [100, 8725]}]}]}, {"id": "ch15", "title_it": "XV", "title_zh": "第 15 章", "paras": [{"id": "ch15p00", "audio": true, "sents": [{"it": "Il sesto pianeta era un pianeta dieci volte più grande.", "zh": "第六颗星球比刚才那颗大十倍。", "t": [100, 3800]}, {"it": "Era abitato da un anziano signore che scriveva certi enormi libri.", "zh": "星球上住着一位老先生，正在撰写大部头著作。", "t": [3800, 7575]}]}, {"id": "ch15p01", "audio": true, "sents": [{"it": "“Toh!", "zh": "看见小王子，他大声嚷： “嗬！", "t": [100, 625]}, {"it": "Ecco un esploratore!” esclamò quando vide il piccolo principe.", "zh": "来了一个勘探人员！", "t": [625, 4426]}]}, {"id": "ch15p02", "audio": true, "sents": [{"it": "Il piccolo principe si sedette sul tavolo e tirò il fiato.", "zh": "” 小王子有点气喘，坐在桌子上。", "t": [100, 4000]}, {"it": "Aveva già viaggiato così tanto!", "zh": "“你从哪儿来？", "t": [4000, 5737]}]}, {"id": "ch15p03", "audio": true, "sents": [{"it": "“Da dove vieni?” domandò l’anziano signore.", "zh": "”老先生问他。", "t": [100, 2788]}]}, {"id": "ch15p04", "audio": true, "sents": [{"it": "“Cos’è quel librone?” disse il piccolo principe.", "zh": "”小王子问。", "t": [100, 3338]}, {"it": "“Che cosa fa qui?”", "zh": "” “我是地理学家。", "t": [3338, 4187]}]}, {"id": "ch15p05", "audio": true, "sents": [{"it": "“Sono un geografo,” disse l’anziano signore.", "zh": "”老先生说。", "t": [100, 2600]}]}, {"id": "ch15p06", "audio": true, "sents": [{"it": "“Che cos’è un geografo?”", "zh": "“什么叫‘地理学家’？", "t": [100, 1388]}]}, {"id": "ch15p07", "audio": true, "sents": [{"it": "“È uno scienziato che sa dove si trovano i mari, i fiumi, le città, le montagne e i deserti.”", "zh": "” “地理学家是学者，知道哪儿有大海、江河、城市、山脉、沙漠。", "t": [100, 6225]}]}, {"id": "ch15p08", "audio": true, "sents": [{"it": "“Questo sì che è interessante,” disse il piccolo principe.", "zh": "”小王子说。", "t": [100, 3412]}, {"it": "“Finalmente un vero mestiere!” E diede un’occhiata intorno a sé al pianeta del geografo.", "zh": "”他环顾地理学家的行星。", "t": [3412, 8938]}, {"it": "Non aveva mai visto un pianeta così maestoso.", "zh": "“您的星球真美。", "t": [8938, 11475]}]}, {"id": "ch15p09", "audio": true, "sents": [{"it": "“È proprio bello il suo pianeta.", "zh": "” “我不可能知道这事。", "t": [100, 1975]}, {"it": "Ci sono degli oceani?”", "zh": "”地理学家说。", "t": [1975, 3187]}]}, {"id": "ch15p10", "audio": true, "sents": [{"it": "“Non posso saperlo,” disse il geografo.", "zh": "“啊（小王子有点失望）！", "t": [100, 2350]}]}, {"id": "ch15p11", "audio": true, "sents": [{"it": "“Ah!” (Il piccolo principe era deluso.) “E montagne?”", "zh": "” “我不可能知道。", "t": [100, 3763]}]}, {"id": "ch15p12", "audio": true, "sents": [{"it": "“Non posso saperlo,” disse il geografo.", "zh": "”地理学家说。", "t": [100, 2350]}]}, {"id": "ch15p13", "audio": true, "sents": [{"it": "“E città e fiumi e deserti?”", "zh": "“有城市、河流、沙漠吗？", "t": [100, 1775]}]}, {"id": "ch15p14", "audio": true, "sents": [{"it": "“Non posso sapere neanche questo,” disse il geografo.", "zh": "”地理学家说。", "t": [100, 3074]}]}, {"id": "ch15p15", "audio": true, "sents": [{"it": "“Ma lei è un geografo!”", "zh": "“可你是地理学家啊！", "t": [100, 1513]}]}, {"id": "ch15p16", "audio": true, "sents": [{"it": "“Certo,” disse il geografo, “ma non sono un esploratore.", "zh": "” “不错，”地理学家说，“但我不是勘探人员。", "t": [100, 3825]}, {"it": "Mi mancano gli esploratori.", "zh": "我这儿很缺勘探人员。", "t": [3825, 5638]}, {"it": "Non è il geografo che fa il conto delle città, dei fiumi, delle montagne, dei mari, degli oceani e dei deserti.", "zh": "计算城市、江河、山脉、大海、大洋、沙漠的数目，不是地理学家干的事。", "t": [5638, 13288]}, {"it": "Il geografo è troppo importante e non può andare a zonzo.", "zh": "地理学家太重要了，没有工夫四处闲逛。", "t": [13288, 16900]}, {"it": "Non esce mai dal suo studio.", "zh": "他必须寸步不离办公室。", "t": [16900, 18788]}, {"it": "Ma lì riceve gli esploratori.", "zh": "他必须寸步不离办公室。", "t": [18788, 20725]}, {"it": "Li ascolta e trascrive i loro ricordi.", "zh": "他在办公室接见勘探人员，询问他们，记下他们的回忆。", "t": [20725, 23350]}, {"it": "E se i ricordi di uno di loro gli sembrano interessanti, il geografo fa fare un’indagine sulla moralità dell’esploratore.”", "zh": "勘探人员引起了地理学家的兴趣，地理学家就要调查这位勘探人员的品质。", "t": [23350, 30276]}]}, {"id": "ch15p17", "audio": true, "sents": [{"it": "“Per quale motivo?”", "zh": "” “为什么？", "t": [100, 1125]}]}, {"id": "ch15p18", "audio": true, "sents": [{"it": "“Perché se un esploratore dovesse mentire, provocherebbe dei pasticci nei libri di geografia.", "zh": "” “一个撒谎的勘探人员会给地理学家的书带来灾难，酒喝得太多的也不行。", "t": [100, 5638]}, {"it": "E lo stesso vale per un esploratore che bevesse troppo.”", "zh": "” “为什么？", "t": [5638, 8600]}]}, {"id": "ch15p19", "audio": true, "sents": [{"it": "“Per quale motivo?”", "zh": "” “酒鬼看的东西是重叠的，地理学家就会在有一座山的地方记下两座山。", "t": [100, 1125]}]}, {"id": "ch15p20", "audio": true, "sents": [{"it": "“Perché gli ubriaconi vedono doppio.", "zh": "” “酒鬼看的东西是重叠的，地理学家就会在有一座山的地方记下两座山。", "t": [100, 2388]}, {"it": "Perciò l’esploratore segnerebbe due montagne dove invece ce n’è una sola.”", "zh": "” 小王子说：“我认识一个人，他会成为糟糕的勘探员。", "t": [2388, 6663]}]}, {"id": "ch15p21", "audio": true, "sents": [{"it": "“Conosco un tale,” disse il piccolo principe, “che sarebbe un pessimo esploratore.”", "zh": "” “很可能。", "t": [100, 4863]}]}, {"id": "ch15p22", "audio": true, "sents": [{"it": "“È possibile.", "zh": "勘探人员的品质不错，我就调查他的发现。", "t": [100, 1238]}, {"it": "Poi, dopo aver verificato la moralità dell’esploratore, si fa un’indagine sulla sua scoperta.”", "zh": "” “不，那太复杂了。", "t": [1238, 6863]}]}, {"id": "ch15p23", "audio": true, "sents": [{"it": "“Andate a vedere?”", "zh": "我要求勘探人员提供证据。", "t": [100, 975]}]}, {"id": "ch15p24", "audio": true, "sents": [{"it": "“No.", "zh": "我要求勘探人员提供证据。", "t": [100, 400]}, {"it": "È troppo complicato.", "zh": "比如说，他发现了一座大山，我就要求他带大石来。", "t": [400, 1888]}, {"it": "Ma si chiede all’esploratore di fornire delle prove.", "zh": "比如说，他发现了一座大山，我就要求他带大石来。", "t": [1888, 4912]}, {"it": "Nel caso per esempio della scoperta di una grande montagna, si chiede che porti qualche grossa pietra.”", "zh": "” 地理学家突然兴奋起来： “你呢，你是从远方来的！", "t": [4912, 10912]}]}, {"id": "ch15p25", "audio": true, "sents": [{"it": "Il geografo all’improvviso trasalì.", "zh": "你给我描写你的星球吧！", "t": [100, 2162]}]}, {"id": "ch15p26", "audio": true, "sents": [{"it": "“Ma tu vieni da lontano!", "zh": "” 地理学家打开他的登记册，削尖铅笔。", "t": [100, 1825]}, {"it": "Sei un esploratore!", "zh": "” 地理学家打开他的登记册，削尖铅笔。", "t": [1825, 3475]}, {"it": "Devi assolutamente descrivermi il tuo pianeta!”", "zh": "他先用铅笔记下勘探人员的口述。", "t": [3475, 6150]}]}, {"id": "ch15p27", "audio": true, "sents": [{"it": "E dopo aver aperto il registro, il geografo temperò la matita.", "zh": "勘探人员提供证据后，再用钢笔誊写。", "t": [100, 4300]}, {"it": "I resoconti degli esploratori sono inizialmente scritti a matita.", "zh": "“啊！", "t": [4300, 8325]}, {"it": "Poi, quando l’esploratore ha fornito le prove, sono ripassati a penna.", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [8325, 12700]}]}, {"id": "ch15p28", "audio": true, "sents": [{"it": "“Allora?” interrogò il geografo.", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [100, 2300]}]}, {"id": "ch15p29", "audio": true, "sents": [{"it": "“Oh!", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [100, 812]}, {"it": "Il posto dove sto io non è molto interessante,” disse il piccolo principe.", "zh": "” “以后的事谁知道呢。", "t": [812, 5288]}, {"it": "“È piccolissimo.", "zh": "”地理学家说。", "t": [5288, 6625]}, {"it": "Ho tre vulcani.", "zh": "“我还有一朵花。", "t": [6625, 7900]}, {"it": "Due attivi e uno spento.", "zh": "“我还有一朵花。", "t": [7900, 9712]}, {"it": "Ma non si sa mai.”", "zh": "” “我们不记录花的。", "t": [9712, 10750]}]}, {"id": "ch15p30", "audio": true, "sents": [{"it": "“Non si sa mai,” disse il geografo.", "zh": "”地理学家说。", "t": [100, 2150]}]}, {"id": "ch15p31", "audio": true, "sents": [{"it": "“Ho anche una rosa.”", "zh": "“为什么不记录花呢？", "t": [100, 1163]}]}, {"id": "ch15p32", "audio": true, "sents": [{"it": "“Noi non registriamo i fiori,” disse il geografo.", "zh": "它是最美的东西！", "t": [100, 2850]}]}, {"id": "ch15p33", "audio": true, "sents": [{"it": "“Perché mai!", "zh": "” “因为它‘昙花一现’。", "t": [100, 1112]}, {"it": "Sono la cosa più bella!”", "zh": "” “什么叫做‘昙花一现’？", "t": [1112, 2463]}]}, {"id": "ch15p34", "audio": true, "sents": [{"it": "“Perché i fiori sono effimeri!”", "zh": "” “什么叫做‘昙花一现’？", "t": [100, 1762]}]}, {"id": "ch15p35", "audio": true, "sents": [{"it": "“Che cosa vuol dire ‘effimero’?”", "zh": "” “地理书是一切书籍中最珍贵的书籍，从不会过时。", "t": [100, 1600]}]}, {"id": "ch15p36", "audio": true, "sents": [{"it": "“I libri di geografia,” disse il geografo, “sono i libri più seri che ci siano.", "zh": "山移位，海洋干枯都是极少发生的事。", "t": [100, 5050]}, {"it": "Non passano mai di moda.", "zh": "我们写的是永恒不变的东西。", "t": [5050, 6688]}, {"it": "È rarissimo che una montagna cambi posto.", "zh": "我们写的是永恒不变的东西。", "t": [6688, 9188]}, {"it": "È rarissimo che un oceano si prosciughi.", "zh": "”小王子打断他的话。", "t": [9188, 11625]}, {"it": "Noi scriviamo cose eterne.”", "zh": "“什么叫做‘昙花一现’？", "t": [11625, 13326]}]}, {"id": "ch15p37", "audio": true, "sents": [{"it": "“Ma i vulcani spenti possono risvegliarsi,” interruppe il piccolo principe.", "zh": "” “火山死与不死，在我们看来都是一回事。", "t": [100, 4812]}, {"it": "“Che cosa significa ‘effimero’?”", "zh": "”地理学家说。", "t": [4812, 6438]}]}, {"id": "ch15p38", "audio": true, "sents": [{"it": "“Che i vulcani siano spenti o attivi, per noialtri è lo stesso,” disse il geografo.", "zh": "” “什么叫做‘昙花一现’？", "t": [100, 5400]}, {"it": "“Ciò che conta per noi è la montagna.", "zh": "”小王子继续追问。", "t": [5400, 7588]}, {"it": "E quella non cambia!”", "zh": "他素来如此，一旦提出一个问题，绝不肯放弃。", "t": [7588, 8787]}]}, {"id": "ch15p39", "audio": true, "sents": [{"it": "“Ma che cosa vuol dire ‘effimero’?” ripeté il piccolo principe che in vita sua non aveva mai rinunciato a una domanda dopo che l’aveva fatta.", "zh": "“‘昙花一现’的意思就是‘面临很快消失的危险’。", "t": [100, 7513]}]}, {"id": "ch15p40", "audio": true, "sents": [{"it": "“Vuol dire che è destinato a scomparire presto.”", "zh": "” “当然。", "t": [100, 2688]}]}, {"id": "ch15p41", "audio": true, "sents": [{"it": "“La mia rosa è destinata a scomparire presto?”", "zh": "” “我的花会‘昙花一现’，”小王子想，“而她只有四根刺保护自己，应付这个世界！", "t": [100, 2624]}]}, {"id": "ch15p42", "audio": true, "sents": [{"it": "“Certo.”", "zh": "” “我的花会‘昙花一现’，”小王子想，“而她只有四根刺保护自己，应付这个世界！", "t": [100, 762]}]}, {"id": "ch15p43", "audio": true, "sents": [{"it": "“La mia rosa è effimera,” disse tra sé il piccolo principe, “e ha solo quattro spine per difendersi dal mondo!", "zh": "我却抛弃了她，让她孤苦伶仃地待在我家！", "t": [100, 6750]}, {"it": "E l’ho lasciata sola là dove sto io!”", "zh": "” 他头一次体会到悔恨的感觉。", "t": [6750, 8650]}]}, {"id": "ch15p44", "audio": true, "sents": [{"it": "Fu il suo primo moto di rammarico.", "zh": "” 他头一次体会到悔恨的感觉。", "t": [100, 2288]}, {"it": "Ma si fece coraggio:", "zh": "然而他还是鼓起勇气问： “您能否指点我，我该去哪儿访问？", "t": [2288, 3600]}]}, {"id": "ch15p45", "audio": true, "sents": [{"it": "“Cosa mi consiglia di andare a visitare?” domandò.", "zh": "然而他还是鼓起勇气问： “您能否指点我，我该去哪儿访问？", "t": [100, 2950]}]}, {"id": "ch15p46", "audio": true, "sents": [{"it": "“Il pianeta Terra,” gli rispose il geografo.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [100, 2838]}, {"it": "“Ne parlano molto bene...”", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [2838, 4238]}]}, {"id": "ch15p47", "audio": true, "sents": [{"it": "E il piccolo principe se ne andò, pensando alla sua rosa.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [100, 3500]}]}]}, {"id": "ch16", "title_it": "XVI", "title_zh": "第 16 章", "paras": [{"id": "ch16p00", "audio": true, "sents": [{"it": "Il settimo pianeta fu quindi la Terra.", "zh": "第七颗星球就是地球。", "t": [100, 2400]}]}, {"id": "ch16p01", "audio": true, "sents": [{"it": "La Terra non è un pianeta qualsiasi!", "zh": "地球可不是等闲之辈！", "t": [100, 2612]}, {"it": "Conta centoundici re (fra cui ovviamente i re negri), settemila geografi, novecentomila uomini d’affari, sette milioni e mezzo di ubriaconi, trecentoundici milioni di vanitosi, che fanno in tutto circa due miliardi di adulti.", "zh": "地球上有一百一十一位国王（我当然没有忘记算上黑人国王）、七千位地理学家、九十万个商人、七百五十万个酒鬼、三亿一千一百万个爱慕虚荣的人，也就是说，约莫有二十亿个大人。", "t": [2612, 17750]}]}, {"id": "ch16p02", "audio": true, "sents": [{"it": "Per darvi un’idea delle dimensioni della Terra sappiate solo che, prima dell’invenzione dell’elettricità, nell’insieme dei sei continenti si doveva disporre di un vero e proprio esercito di quattrocento sessantaduemila cinquecento undici lampionai.", "zh": "为了让你们对地球的面积大小有个具体形象的概念，我给你们打个比方。", "t": [100, 14562]}]}, {"id": "ch16p03", "audio": true, "sents": [{"it": "Visto da una certa distanza, il tutto faceva un bellissimo effetto.", "zh": "从稍远处眺望这支大军，真是蔚为壮观。", "t": [100, 4525]}, {"it": "I movimenti di quell’esercito erano sincronizzati come quelli di un balletto.", "zh": "从稍远处眺望这支大军，真是蔚为壮观。", "t": [4525, 9138]}, {"it": "Prima toccava ai lampionai della Nuova Zelanda e dell’Australia.", "zh": "点灯人的动作犹如芭蕾舞演员的动作：整齐划一，井然有序。", "t": [9138, 13338]}, {"it": "Quando questi avevano acceso i loro lampioni, se ne andavano a dormire.", "zh": "首先上场的是新西兰、澳大利亚的点灯人，他们点亮路灯后就去睡觉。", "t": [13338, 17588]}, {"it": "Allora entravano in scena i lampionai della Cina e della Siberia.", "zh": "接着加入舞蹈行列的是中国和西伯利亚的点灯人，然后他们也隐没于后台。", "t": [17588, 21462]}, {"it": "Poi anche loro sparivano dietro le quinte.", "zh": "接着加入舞蹈行列的是中国和西伯利亚的点灯人，然后他们也隐没于后台。", "t": [21462, 24012]}, {"it": "Allora toccava ai lampionai della Russia e delle Indie.", "zh": "然后轮到俄罗斯和印度的点灯人，接着是非洲和欧洲的，然后是南美洲、北美洲。", "t": [24012, 27200]}, {"it": "Poi a quelli dell’Africa e dell’Europa.", "zh": "然后轮到俄罗斯和印度的点灯人，接着是非洲和欧洲的，然后是南美洲、北美洲。", "t": [27200, 29550]}, {"it": "Poi a quelli del Sudamerica.", "zh": "然后轮到俄罗斯和印度的点灯人，接着是非洲和欧洲的，然后是南美洲、北美洲。", "t": [29550, 31488]}, {"it": "Poi a quelli del Nordamerica.", "zh": "这支大军的进场顺序从不错乱，真是让人叹为观止。", "t": [31488, 33488]}, {"it": "E mai che sbagliassero un’entrata in scena.", "zh": "这支大军的进场顺序从不错乱，真是让人叹为观止。", "t": [33488, 35887]}]}, {"id": "ch16p04", "audio": true, "sents": [{"it": "Solo il lampionaio dell’unico lampione del Polo Nord e il suo collega dell’unico lampione del Polo Sud conducevano vite pigre e sfaccendate: lavoravano due volte l’anno.", "zh": "惟有北极点灯人和他的南极同行，过着悠闲懒散的生活。", "t": [100, 9700]}]}]}, {"id": "ch17", "title_it": "XVII", "title_zh": "第 17 章", "paras": [{"id": "ch17p00", "audio": true, "sents": [{"it": "Quando uno vuole fare dello spirito, è facile che racconti qualche frottola.", "zh": "好出风头，喜欢卖弄聪明的人，多少会讲几句大话，吹点牛皮。", "t": [100, 4600]}, {"it": "Parlandovi dei lampionai, non sono stato molto corretto.", "zh": "我给你们介绍点灯人的时候，也不太老实。", "t": [4600, 8200]}, {"it": "Rischio di dare a quelli che non lo conoscono un’idea sbagliata del nostro pianeta.", "zh": "我也许让不了解我们星球的人产生误解，造成错觉。", "t": [8200, 12912]}, {"it": "Sulla Terra gli uomini occupano pochissimo spazio.", "zh": "人在地球上占的位置微乎其微。", "t": [12912, 16238]}, {"it": "Se i due miliardi di abitanti che popolano la Terra stessero in piedi e un po’ pigiati, come a un comizio, potrebbero occupare una piazza pubblica di venti miglia per venti miglia.", "zh": "倘若让散居在地球上的二十亿人口集中在一起开大会，他们可以松快地站在二十英里长二十英里宽的广场上。", "t": [16238, 26275]}, {"it": "Si potrebbe ammassare l’umanità su un qualsiasi isolotto del Pacifico.", "zh": "当然，大人们不会相信这些话。", "t": [26275, 30350]}]}, {"id": "ch17p01", "audio": true, "sents": [{"it": "Gli adulti ovviamente non vi crederanno.", "zh": "他们以为自己占了很大的位置，自以为自己像猴面包树那么庞大。", "t": [100, 2675]}, {"it": "Pensano di occupare molto spazio.", "zh": "他们以为自己占了很大的位置，自以为自己像猴面包树那么庞大。", "t": [2675, 4988]}, {"it": "Si immaginano imponenti come baobab.", "zh": "那你就建议他们算一算。", "t": [4988, 7700]}, {"it": "Consigliategli di fare il calcolo.", "zh": "他们不是喜欢数字吗？", "t": [7700, 9812]}, {"it": "Si divertiranno, perché adorano i numeri.", "zh": "他们会高兴的。", "t": [9812, 12525]}, {"it": "Ma voi non perdete tempo con questo compitino.", "zh": "但我劝你们别多此一举了，挺麻烦的，毫无用处的。", "t": [12525, 15425]}, {"it": "È inutile.", "zh": "相信我的话吧。", "t": [15425, 16425]}, {"it": "Fidatevi di me.", "zh": "相信我的话吧。", "t": [16425, 17300]}]}, {"id": "ch17p02", "audio": true, "sents": [{"it": "Così, una volta giunto sulla Terra, il piccolo principe fu stupito di non vedere nessuno.", "zh": "小王子来到地球后，看不见一个人影，不由心里纳闷。", "t": [100, 6200]}, {"it": "Temeva già di aver sbagliato pianeta quando un anello color della luna si mosse sulla sabbia.", "zh": "这时，他看见沙地上有一个月白色的圆环在蠕动。", "t": [6200, 11276]}]}, {"id": "ch17p03", "audio": true, "sents": [{"it": "“Buona notte,” disse il piccolo principe a casaccio.", "zh": "”小王子随口说。", "t": [100, 3088]}]}, {"id": "ch17p04", "audio": true, "sents": [{"it": "“Buona notte,” fece il serpente.", "zh": "“这儿是什么星球？", "t": [100, 1913]}]}, {"id": "ch17p05", "audio": true, "sents": [{"it": "“Su quale pianeta sono finito?” domandò il piccolo principe.", "zh": "“是地球，非洲。", "t": [100, 3787]}]}, {"id": "ch17p06", "audio": true, "sents": [{"it": "“Sulla Terra, in Africa,” rispose il serpente.", "zh": "……地球上没人吗？", "t": [100, 2974]}]}, {"id": "ch17p07", "audio": true, "sents": [{"it": "“Ah!...", "zh": "……地球上没人吗？", "t": [100, 750]}, {"it": "Ma non c’è nessuno sulla Terra?”", "zh": "” “这儿是沙漠，沙漠里是没有人烟的，地球很大。", "t": [750, 2412]}]}, {"id": "ch17p08", "audio": true, "sents": [{"it": "“Qui siamo nel deserto.", "zh": "” “这儿是沙漠，沙漠里是没有人烟的，地球很大。", "t": [100, 1775]}, {"it": "E nei deserti non c’è nessuno.", "zh": "”蛇说。", "t": [1775, 3812]}, {"it": "La Terra è grande,” disse il serpente.", "zh": "”蛇说。", "t": [3812, 6126]}]}, {"id": "ch17p09", "audio": true, "sents": [{"it": "Il piccolo principe si sedette su un sasso e levò gli occhi verso il cielo.", "zh": "小王子坐在一块石头上，抬头看天空： “我在想，星星发亮是否为了让每个人有一天能找到自己的星星。", "t": [100, 4512]}]}, {"id": "ch17p10", "audio": true, "sents": [{"it": "“Mi domando,” disse, “se le stelle brillano perché un giorno ciascuno possa ritrovare la propria.", "zh": "你看我的星球，它正好在我的头顶上……可它多么的遥远！", "t": [100, 5462]}, {"it": "Guarda il mio pianeta.", "zh": "” “它真美。", "t": [5462, 6862]}, {"it": "È esattamente sopra di noi...", "zh": "”蛇说。", "t": [6862, 8675]}, {"it": "Ma com’è lontano!”", "zh": "“你来这儿干什么？", "t": [8675, 9850]}]}, {"id": "ch17p11", "audio": true, "sents": [{"it": "“È bello,” disse il serpente.", "zh": "” “我和一朵花赌气闹别扭呢。", "t": [100, 1950]}, {"it": "“Che cosa sei venuto a fare qui?”", "zh": "”小王子说。", "t": [1950, 3526]}]}, {"id": "ch17p12", "audio": true, "sents": [{"it": "“Ho dei problemi con una rosa,” disse il piccolo principe.", "zh": "他们都缄口不言了。", "t": [100, 3125]}]}, {"id": "ch17p13", "audio": true, "sents": [{"it": "“Ah!” fece il serpente.", "zh": "“人在哪儿呢？", "t": [100, 1588]}]}, {"id": "ch17p14", "audio": true, "sents": [{"it": "E tacquero.", "zh": "”小王子终于开口说话。", "t": [100, 862]}]}, {"id": "ch17p15", "audio": true, "sents": [{"it": "“Dove sono gli uomini?” riprese poi il piccolo principe.", "zh": "“待在沙漠有点孤独……” “跟人在一起也孤独。", "t": [100, 3925]}, {"it": "“Si è un po’ soli nel deserto...”", "zh": "”蛇说。", "t": [3925, 5650]}]}, {"id": "ch17p16", "audio": true, "sents": [{"it": "“Si è soli anche fra gli uomini,” disse il serpente.", "zh": "小王子久久凝视着它。", "t": [100, 2900]}]}, {"id": "ch17p17", "audio": true, "sents": [{"it": "Il piccolo principe lo guardò lungamente:", "zh": "“你是奇特的动物，”小王子终于说道，“你像一根指头般细……” “可我比国王的指头强大得多。", "t": [100, 2450]}]}, {"id": "ch17p18", "audio": true, "sents": [{"it": "“Sei uno strano animale,” gli disse alla fine, “sottile come un dito...”", "zh": "“你是奇特的动物，”小王子终于说道，“你像一根指头般细……” “可我比国王的指头强大得多。", "t": [100, 4113]}]}, {"id": "ch17p19", "audio": true, "sents": [{"it": "“Ma sono più potente del dito di un re,” disse il serpente.", "zh": "小王子微微一笑。", "t": [100, 3226]}]}, {"id": "ch17p20", "audio": true, "sents": [{"it": "Il piccolo principe sorrise:", "zh": "小王子微微一笑。", "t": [100, 1874]}]}, {"id": "ch17p21", "audio": true, "sents": [{"it": "“Non si direbbe...", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [100, 1325]}, {"it": "non hai neanche le zampe...", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [1325, 2975]}, {"it": "non puoi neanche viaggiare...”", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [2975, 4488]}]}, {"id": "ch17p22", "audio": true, "sents": [{"it": "“Ti posso portare più lontano di quanto possa fare una nave,” disse il serpente.", "zh": "” 它盘着小王子的脚踝，像一只金镯子。", "t": [100, 4350]}]}, {"id": "ch17p23", "audio": true, "sents": [{"it": "Si avvolse intorno alla caviglia del piccolo principe, come una catenina d’oro:", "zh": "” 它盘着小王子的脚踝，像一只金镯子。", "t": [100, 4537]}]}, {"id": "ch17p24", "audio": true, "sents": [{"it": "“Chiunque tocco, lo restituisco alla terra da cui proviene,” disse ancora.", "zh": "“我碰到谁，就能把他送回他来的地方，”蛇还说，“但你纯洁，你是从星球上来的……” 小王子默默无言。", "t": [100, 4525]}, {"it": "“Ma tu sei puro e vieni da una stella...”", "zh": "“我同情你，在这花岗岩构成的地球上，你这么弱小。", "t": [4525, 6837]}]}, {"id": "ch17p25", "audio": true, "sents": [{"it": "Il piccolo principe non disse nulla.", "zh": "“我同情你，在这花岗岩构成的地球上，你这么弱小。", "t": [100, 2212]}]}, {"id": "ch17p26", "audio": true, "sents": [{"it": "“Mi fai pena, così fragile su questa Terra di granito.", "zh": "如果你有朝一日思念你的星球，我可以帮助你。", "t": [100, 3700]}, {"it": "Se un giorno dovessi rimpiangere troppo il tuo pianeta, posso aiutarti.", "zh": "我可以……” “啊！", "t": [3700, 8062]}, {"it": "Posso...”", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [8062, 8624]}]}, {"id": "ch17p27", "audio": true, "sents": [{"it": "“Oh, ho capito benissimo,” fece il piccolo principe, “ma perché parli sempre per enigmi?”", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [100, 5075]}]}, {"id": "ch17p28", "audio": true, "sents": [{"it": "“Li risolvo tutti,” disse il serpente.", "zh": "”蛇说。", "t": [100, 2324]}]}, {"id": "ch17p29", "audio": true, "sents": [{"it": "E tacquero.", "zh": "他们都不讲话了。", "t": [100, 862]}]}]}, {"id": "ch18", "title_it": "XVIII", "title_zh": "第 18 章", "paras": [{"id": "ch18p00", "audio": true, "sents": [{"it": "Il piccolo principe attraversò il deserto e incontrò soltanto un fiore.", "zh": "小王子穿过沙漠，只遇见一朵花。", "t": [100, 4500]}, {"it": "Un fiore con tre petali, un fiore da niente...", "zh": "一朵三瓣的花，一朵极普通平凡的花…… “你好。", "t": [4500, 7337]}]}, {"id": "ch18p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse il piccolo principe.", "zh": "“你好。", "t": [100, 2226]}]}, {"id": "ch18p02", "audio": true, "sents": [{"it": "“Buongiorno,” disse il fiore.", "zh": "“人在哪儿呢？", "t": [100, 1626]}]}, {"id": "ch18p03", "audio": true, "sents": [{"it": "“Dove sono gli uomini?” domandò gentilmente il piccolo principe.", "zh": "”小王子彬彬有礼地问。", "t": [100, 4337]}]}, {"id": "ch18p04", "audio": true, "sents": [{"it": "Un giorno il fiore aveva visto passare una carovana:", "zh": "“人？", "t": [100, 3112]}]}, {"id": "ch18p05", "audio": true, "sents": [{"it": "“Gli uomini?", "zh": "依我看，人是有的，大概六七个吧。", "t": [100, 1238]}, {"it": "Credo ce ne siano sei o sette.", "zh": "好几年前我见过他们。", "t": [1238, 3250]}, {"it": "Li ho intravisti anni fa.", "zh": "但我不知道在哪儿能找到他们。", "t": [3250, 4900]}, {"it": "Ma non si sa mai dove trovarli.", "zh": "但我不知道在哪儿能找到他们。", "t": [4900, 6912]}, {"it": "Vanno in balìa del vento.", "zh": "风把他们吹散了。", "t": [6912, 8638]}, {"it": "Non hanno radici, e questo per loro è un bel problema.”", "zh": "他们没有根，这就使他们吃尽了苦头。", "t": [8638, 12187]}]}, {"id": "ch18p06", "audio": true, "sents": [{"it": "“Addio,” fece il piccolo principe.", "zh": "”小王子说。", "t": [100, 2112]}]}, {"id": "ch18p07", "audio": true, "sents": [{"it": "“Addio,” disse il fiore.", "zh": "”花儿说。", "t": [100, 1488]}]}]}, {"id": "ch19", "title_it": "XIX", "title_zh": "第 19 章", "paras": [{"id": "ch19p00", "audio": true, "sents": [{"it": "Il piccolo principe scalò un’alta montagna.", "zh": "小王子登上一座高山。", "t": [100, 2950]}, {"it": "Le uniche montagne che avesse mai conosciuto erano i tre vulcani che gli arrivavano al ginocchio.", "zh": "以前他只见过自己的那三座火山，火山很矮，才到他的膝盖。", "t": [2950, 8550]}, {"it": "Adoperava il vulcano spento come uno sgabello.", "zh": "“站在这座高山上，”他想道，“我一眼就能看见整个星球和所有的人了……” 但他只看见悬崖峭壁。", "t": [8550, 11688]}, {"it": "“Da una montagna così alta,” si disse quindi, “vedrò l’intero pianeta e tutti gli uomini...” Ma vide soltanto alcuni picchi aguzzi.", "zh": "“您好。", "t": [11688, 19412]}]}, {"id": "ch19p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse a casaccio.", "zh": "“您好……您好……您好……”回声应道。", "t": [100, 1812]}]}, {"id": "ch19p02", "audio": true, "sents": [{"it": "“Buongiorno...", "zh": "“您是谁？", "t": [100, 1075]}, {"it": "buongiorno...", "zh": "”小王子问。", "t": [1075, 2025]}, {"it": "buongiorno...” rispose l’eco.", "zh": "”小王子问。", "t": [2025, 3900]}]}, {"id": "ch19p03", "audio": true, "sents": [{"it": "“Chi siete?” disse il piccolo principe.", "zh": "“您是谁……您是谁……您是谁……”回声应道。", "t": [100, 2675]}]}, {"id": "ch19p04", "audio": true, "sents": [{"it": "“Chi siete...", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [100, 1062]}, {"it": "chi siete...", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [1062, 2025]}, {"it": "chi siete...” rispose l’eco.", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [2025, 3875]}]}, {"id": "ch19p05", "audio": true, "sents": [{"it": "“Siate miei amici, sono solo,” disse.", "zh": "“我很孤单……我很孤单……我很孤单……”回声又答应道。", "t": [100, 2350]}]}, {"id": "ch19p06", "audio": true, "sents": [{"it": "“Sono solo...", "zh": "“我很孤单……我很孤单……我很孤单……”回声又答应道。", "t": [100, 1125]}, {"it": "sono solo...", "zh": "“我很孤单……我很孤单……我很孤单……”回声又答应道。", "t": [1125, 2088]}, {"it": "sono solo...” rispose l’eco.", "zh": "“多么古怪的星球！", "t": [2088, 3950]}]}, {"id": "ch19p07", "audio": true, "sents": [{"it": "“Che strano pianeta!” pensò allora.", "zh": "”小王子想道。", "t": [100, 2725]}, {"it": "“È tutto secco, appuntito e salato.", "zh": "”小王子想道。", "t": [2725, 5450]}, {"it": "E gli uomini sono privi di immaginazione.", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [5450, 8075]}, {"it": "Ripetono tutto quello che gli dici...", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [8075, 10638]}, {"it": "Dove stavo io avevo una rosa: era sempre lei la prima a parlare...”", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [10638, 14500]}]}]}, {"id": "ch20", "title_it": "XX", "title_zh": "第 20 章", "paras": [{"id": "ch20p00", "audio": true, "sents": [{"it": "Ma un bel giorno, dopo aver camminato a lungo sulla sabbia, sulle rocce, sulla neve, il piccolo principe si imbatté finalmente in una strada.", "zh": "他终于看见了一条路，条条路都通向有人烟的地方。", "t": [100, 9075]}, {"it": "E le strade vanno tutte dove ci sono gli uomini.", "zh": "这是一座盛开着玫瑰花的花园。", "t": [9075, 11588]}]}, {"id": "ch20p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse.", "zh": "”玫瑰花们说。", "t": [100, 1225]}]}, {"id": "ch20p02", "audio": true, "sents": [{"it": "Era un giardino di rose.", "zh": "小王子看着她们。", "t": [100, 1463]}]}, {"id": "ch20p03", "audio": true, "sents": [{"it": "“Buongiorno,” dissero le rose.", "zh": "她们一个个全像他的那朵花儿。", "t": [100, 1800]}]}, {"id": "ch20p04", "audio": true, "sents": [{"it": "Il piccolo principe le guardò.", "zh": "“你们是谁？", "t": [100, 2062]}, {"it": "Assomigliavano tutte al suo fiore.", "zh": "”小王子大吃一惊，问她们说。", "t": [2062, 3900]}]}, {"id": "ch20p05", "audio": true, "sents": [{"it": "“Chi siete?” domandò stupefatto.", "zh": "”玫瑰花们说。", "t": [100, 2450]}]}, {"id": "ch20p06", "audio": true, "sents": [{"it": "“Siamo le rose,” dissero le rose.", "zh": "“啊！", "t": [100, 2000]}]}, {"id": "ch20p07", "audio": true, "sents": [{"it": "“Ah!” fece il piccolo principe...", "zh": "”小王子说…… 小王子伤心极了。", "t": [100, 2162]}]}, {"id": "ch20p08", "audio": true, "sents": [{"it": "E si sentì molto infelice.", "zh": "他的花儿告诉他，大千世界中，她是惟一的玫瑰花。", "t": [100, 1988]}, {"it": "La sua rosa gli aveva detto di essere l’unica in tutto l’universo.", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [1988, 6112]}, {"it": "E invece ce n’erano cinquemila, tutte uguali, in un solo giardino!", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [6112, 10526]}]}, {"id": "ch20p09", "audio": true, "sents": [{"it": "“Se le vedesse, ci rimarrebbe malissimo...” pensò, “tossirebbe a più non posso e farebbe finta di morire per levarsi dall’imbarazzo.", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [100, 7975]}, {"it": "E sarei costretto a far finta di curarla perché altrimenti, per umiliare anche me, si lascerebbe davvero morire...”", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [7975, 14326]}]}, {"id": "ch20p10", "audio": true, "sents": [{"it": "Poi si disse ancora: “Credevo di possedere un fiore unico, e invece ho solo una rosa uguale a tante altre.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [100, 6788]}, {"it": "Lei e i miei tre vulcani che mi arrivano al ginocchio, di cui uno forse spento per sempre, non fanno di me un gran principe...”.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [6788, 14050]}, {"it": "E steso sull’erba pianse.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [14050, 15700]}]}]}, {"id": "ch21", "title_it": "XXI", "title_zh": "第 21 章", "paras": [{"id": "ch21p00", "audio": true, "sents": [{"it": "Fu allora che comparve la volpe:", "zh": "就在这个时候，出现了一只狐狸。", "t": [100, 1900]}]}, {"id": "ch21p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse la volpe.", "zh": "“你好。", "t": [100, 1688]}]}, {"id": "ch21p02", "audio": true, "sents": [{"it": "“Buongiorno,” rispose gentilmente il piccolo principe, che si voltò ma non vide nulla.", "zh": "”小王子彬彬有礼地回答，他转过身，但看不见有什么东西。", "t": [100, 5074]}]}, {"id": "ch21p03", "audio": true, "sents": [{"it": "“Sono qui,” disse la voce, “sotto il melo...”", "zh": "“我在这里，”那声音说，“在苹果树下。", "t": [100, 2612]}]}, {"id": "ch21p04", "audio": true, "sents": [{"it": "“Chi sei?” disse il piccolo principe.", "zh": "” “你是谁？", "t": [100, 2838]}, {"it": "“Sei proprio graziosa...”", "zh": "” “你是谁？", "t": [2838, 4274]}]}, {"id": "ch21p05", "audio": true, "sents": [{"it": "“Sono una volpe,” disse la volpe.", "zh": "”小王子说，“你真漂亮……” “我是狐狸。", "t": [100, 2000]}]}, {"id": "ch21p06", "audio": true, "sents": [{"it": "“Vieni a giocare con me,” le propose il piccolo principe, “sono tanto triste.”", "zh": "“来跟我一起玩吧。", "t": [100, 4362]}]}, {"id": "ch21p07", "audio": true, "sents": [{"it": "“Non posso giocare con te,” disse la volpe.", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [100, 2625]}, {"it": "“Non sono addomesticata.”", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [2625, 4200]}]}, {"id": "ch21p08", "audio": true, "sents": [{"it": "“Ah!", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [100, 750]}, {"it": "Scusa,” fece il piccolo principe.", "zh": "” “哦，对不起。", "t": [750, 2750]}]}, {"id": "ch21p09", "audio": true, "sents": [{"it": "Ma, dopo averci pensato un po’, aggiunse:", "zh": "” “哦，对不起。", "t": [100, 2987]}]}, {"id": "ch21p10", "audio": true, "sents": [{"it": "“Che cosa significa ‘addomesticare’?”", "zh": "小王子想了想，又问： “什么叫做‘驯养’？", "t": [100, 2026]}]}, {"id": "ch21p11", "audio": true, "sents": [{"it": "“Tu non sei di qui,” disse la volpe, “che cosa stai cercando?”", "zh": "” “你不是本地人。", "t": [100, 3537]}]}, {"id": "ch21p12", "audio": true, "sents": [{"it": "“Cerco gli uomini,” disse il piccolo principe.", "zh": "“人有枪，人打猎，太可恶了！", "t": [100, 2862]}, {"it": "“Che cosa significa ‘addomesticare’?”", "zh": "可人也养鸡！", "t": [2862, 4788]}]}, {"id": "ch21p13", "audio": true, "sents": [{"it": "“Gli uomini,” disse la volpe, “hanno i fucili e cacciano.", "zh": "” “不！", "t": [100, 3900]}, {"it": "È una gran seccatura!", "zh": "”小王子说，“我找朋友。", "t": [3900, 5550]}, {"it": "Allevano anche le galline.", "zh": "什么叫做‘驯养’？", "t": [5550, 7225]}, {"it": "È l’unica cosa interessante.", "zh": "什么叫做‘驯养’？", "t": [7225, 9138]}, {"it": "Cerchi delle galline?”", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [9138, 10300]}]}, {"id": "ch21p14", "audio": true, "sents": [{"it": "“No,” disse il piccolo principe.", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [100, 2175]}, {"it": "“Cerco degli amici.", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [2175, 4088]}, {"it": "Che cosa significa ‘addomesticare’?”", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [4088, 6013]}]}, {"id": "ch21p15", "audio": true, "sents": [{"it": "“È una cosa troppo dimenticata,” disse la volpe.", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [100, 2900]}, {"it": "“Significa ‘creare dei legami’...”", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [2900, 4787]}]}, {"id": "ch21p16", "audio": true, "sents": [{"it": "“Creare dei legami?”", "zh": "而且我不需要你，你也不需要我。", "t": [100, 1263]}]}, {"id": "ch21p17", "audio": true, "sents": [{"it": "“Certo,” disse la volpe.", "zh": "而且我不需要你，你也不需要我。", "t": [100, 1838]}, {"it": "“Per me, ora tu sei solo un bambino uguale a centomila altri bambini.", "zh": "而且我不需要你，你也不需要我。", "t": [1838, 6112]}, {"it": "E non ho bisogno di te.", "zh": "对你而言，我只是一只狐狸，和千千万万只狐狸没有两样。", "t": [6112, 7575]}, {"it": "Né tu hai bisogno di me.", "zh": "但如果你驯养了我，我们就互相需要了。", "t": [7575, 9275]}, {"it": "Per te, sono soltanto una volpe uguale a centomila altre volpi.", "zh": "但如果你驯养了我，我们就互相需要了。", "t": [9275, 13450]}, {"it": "Ma se mi addomestichi, avremo bisogno l’uno dell’altra.", "zh": "你就是我世界上惟一的人了，我也是你世上惟一的狐狸了……” “我有点明白了。", "t": [13450, 16838]}, {"it": "Per me tu sarai unico al mondo.", "zh": "”小王子说。", "t": [16838, 18762]}, {"it": "Per te io sarò unica al mondo...”", "zh": "”小王子说。", "t": [18762, 20424]}]}, {"id": "ch21p18", "audio": true, "sents": [{"it": "“Comincio a capire,” disse il piccolo principe.", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [100, 2775]}, {"it": "“C’è una rosa...", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [2775, 3850]}, {"it": "credo che mi abbia addomesticato...”", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [3850, 5613]}]}, {"id": "ch21p19", "audio": true, "sents": [{"it": "“È possibile,” disse la volpe.", "zh": "她不在地球上。", "t": [100, 2100]}, {"it": "“Sulla Terra capita di tutto...”", "zh": "她不在地球上。", "t": [2100, 3700]}]}, {"id": "ch21p20", "audio": true, "sents": [{"it": "“Oh!", "zh": "”小王子说。", "t": [100, 812]}, {"it": "Non è sulla Terra,” disse il piccolo principe.", "zh": "狐狸露出大惊的神色。", "t": [812, 3312]}]}, {"id": "ch21p21", "audio": true, "sents": [{"it": "La volpe parve molto incuriosita:", "zh": "“在另一个星球上？", "t": [100, 2326]}]}, {"id": "ch21p22", "audio": true, "sents": [{"it": "“Su un altro pianeta?”", "zh": "” “是的。", "t": [100, 1300]}]}, {"id": "ch21p23", "audio": true, "sents": [{"it": "“Sì.”", "zh": "” “那颗星球上，有猎人吗？", "t": [100, 562]}]}, {"id": "ch21p24", "audio": true, "sents": [{"it": "“E ci sono cacciatori, su quel pianeta?”", "zh": "” “没有。", "t": [100, 2626]}]}, {"id": "ch21p25", "audio": true, "sents": [{"it": "“No.”", "zh": "” “没有。", "t": [100, 462]}]}, {"id": "ch21p26", "audio": true, "sents": [{"it": "“Ah, molto interessante!", "zh": "” “那可有意思了！", "t": [100, 2162]}, {"it": "E galline?”", "zh": "有鸡吗？", "t": [2162, 2887]}]}, {"id": "ch21p27", "audio": true, "sents": [{"it": "“No.”", "zh": "” “没有。", "t": [100, 462]}]}, {"id": "ch21p28", "audio": true, "sents": [{"it": "“Nulla è perfetto,” sospirò la volpe.", "zh": "” “没有。", "t": [100, 2387]}]}, {"id": "ch21p29", "audio": true, "sents": [{"it": "Ma la volpe tornò alla sua idea:", "zh": "” “世上就没有十全十美的东西。", "t": [100, 2000]}]}, {"id": "ch21p30", "audio": true, "sents": [{"it": "“Ho una vita monotona.", "zh": "”狐狸叹了一口气。", "t": [100, 1600]}, {"it": "Io do la caccia alle galline e gli uomini danno la caccia a me.", "zh": "狐狸又扯回原先的话题： “我的生活枯燥乏味，异常单调。", "t": [1600, 5175]}, {"it": "Tutte le galline si assomigliano, e tutti gli uomini si assomigliano.", "zh": "我逮鸡，人逮我。", "t": [5175, 9350]}, {"it": "Quindi mi annoio un po’.", "zh": "鸡全是一个模样，人也是一个模样，我都腻了。", "t": [9350, 10850]}, {"it": "Ma se tu mi addomestichi, la mia vita sarà come inondata di luce.", "zh": "但如果你驯养我，我的生活就会充满阳光。", "t": [10850, 14975]}, {"it": "Conoscerò un rumore di passi diverso da tutti gli altri.", "zh": "我能辨得出与众不同的脚步声。", "t": [14975, 18550]}, {"it": "Gli altri passi mi fanno fuggire sotto terra.", "zh": "别人的脚步声吓得我赶紧钻回地洞。", "t": [18550, 21238]}, {"it": "Il tuo mi chiamerà fuori dalla tana, come una musica.", "zh": "你的脚步声却像悦耳的音乐，召唤我走出洞穴。", "t": [21238, 24600]}, {"it": "E poi guarda!", "zh": "你看那儿，那不是一片麦田吗？", "t": [24600, 25788]}, {"it": "Li vedi laggiù, i campi di grano?", "zh": "你看那儿，那不是一片麦田吗？", "t": [25788, 28150]}, {"it": "Io non mangio pane.", "zh": "我不吃面包，我不需要小麦，麦田引不起我的想像力。", "t": [28150, 29500]}, {"it": "Quindi per me il grano è inutile.", "zh": "我不吃面包，我不需要小麦，麦田引不起我的想像力。", "t": [29500, 31812]}, {"it": "I campi di grano non mi dicono niente.", "zh": "说到这个，实在可悲！", "t": [31812, 34138]}, {"it": "E questo è molto triste!", "zh": "说到这个，实在可悲！", "t": [34138, 36000]}, {"it": "Ma tu hai capelli color dell’oro.", "zh": "说到这个，实在可悲！", "t": [36000, 38000]}, {"it": "E allora sarà bellissimo quando mi avrai addomesticato!", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [38000, 41375]}, {"it": "Il grano, che è dorato, mi farà pensare a te.", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [41375, 44600]}, {"it": "E mi piacerà il rumore del vento nel grano...”", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [44600, 47000]}]}, {"id": "ch21p31", "audio": true, "sents": [{"it": "La volpe tacque e guardò a lungo il piccolo principe.", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [100, 3188]}]}, {"id": "ch21p32", "audio": true, "sents": [{"it": "“Per favore...", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [100, 1075]}, {"it": "addomesticami!” disse.", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [1075, 2925]}]}, {"id": "ch21p33", "audio": true, "sents": [{"it": "“Lo farei volentieri,” rispose il piccolo principe, “ma non ho molto tempo.", "zh": "” “人只认识自己驯养的东西。", "t": [100, 4525]}, {"it": "Ho amici da scoprire e molte cose da conoscere.”", "zh": "“人再没时间认识什么事物。", "t": [4525, 7088]}]}, {"id": "ch21p34", "audio": true, "sents": [{"it": "“Conosciamo soltanto le cose che addomestichiamo,” disse la volpe.", "zh": "他们到商店买现成的东西，但没有一家商店是出售朋友的，人也就没有朋友了。", "t": [100, 3800]}, {"it": "“Gli uomini non hanno più tempo per conoscere nulla.", "zh": "如果你想要朋友，你就驯养我吧！", "t": [3800, 6750]}, {"it": "Comprano le cose già fatte nei negozi.", "zh": "如果你想要朋友，你就驯养我吧！", "t": [6750, 9300]}, {"it": "Ma siccome non esistono negozi che vendono amici, gli uomini non hanno più amici.", "zh": "”小王子说。", "t": [9300, 14950]}, {"it": "Se vuoi un amico, addomesticami!”", "zh": "”狐狸回答说。", "t": [14950, 17387]}]}, {"id": "ch21p35", "audio": true, "sents": [{"it": "“Come si fa?” disse il piccolo principe.", "zh": "“首先你要离我稍远点，坐着，像这样，坐在草地上。", "t": [100, 2637]}]}, {"id": "ch21p36", "audio": true, "sents": [{"it": "“Ci vuole molta pazienza,” rispose la volpe.", "zh": "我斜瞟着你，你什么也别对我说。", "t": [100, 2775]}, {"it": "“Prima dovrai sederti un po’ lontano da me, così, nell’erba.", "zh": "语言是误会的源泉。", "t": [2775, 6738]}, {"it": "Io ti guarderò con la coda dell’occhio e tu non dirai niente.", "zh": "可是每天你可以坐得稍近一点……” 翌日，小王子又来了。", "t": [6738, 10525]}, {"it": "Il linguaggio è fonte di malintesi.", "zh": "“最好在同一个时间来，”狐狸说，“例如，如果你是下午四点钟来的，从三点钟开始，我就开始感觉到幸福的滋味了。", "t": [10525, 12825]}, {"it": "Ma ogni giorno potrai sederti un po’ più vicino...”", "zh": "“最好在同一个时间来，”狐狸说，“例如，如果你是下午四点钟来的，从三点钟开始，我就开始感觉到幸福的滋味了。", "t": [12825, 15537]}]}, {"id": "ch21p37", "audio": true, "sents": [{"it": "L’indomani il piccolo principe tornò.", "zh": "“最好在同一个时间来，”狐狸说，“例如，如果你是下午四点钟来的，从三点钟开始，我就开始感觉到幸福的滋味了。", "t": [100, 2312]}]}, {"id": "ch21p38", "audio": true, "sents": [{"it": "“Sarebbe stato meglio se fossi venuto alla stessa ora,” disse la volpe.", "zh": "越接近四点钟，我越觉得幸福。", "t": [100, 3875]}, {"it": "“Se per esempio verrai alle quattro del pomeriggio, già dalle tre io comincerò a essere felice.", "zh": "到了四点钟，我就心神恍惚，坐立不安了。", "t": [3875, 9438]}, {"it": "Più il tempo passerà e più mi sentirò felice.", "zh": "我发现了幸福的价值，但是如果你不按时来，我就不知道几点钟该装扮我的心，仪式还是需要的。", "t": [9438, 12300]}, {"it": "Finché alle quattro sarò tutta agitata e in apprensione: scoprirò il valore della felicità!", "zh": "” “什么叫做‘仪式’？", "t": [12300, 17762]}, {"it": "Ma se vieni quando capita, non saprò mai a che ora vestirmi il cuore...", "zh": "”狐狸说。", "t": [17762, 21825]}, {"it": "I riti sono importanti.”", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [21825, 23400]}]}, {"id": "ch21p39", "audio": true, "sents": [{"it": "“Che cos’è un rito?” disse il piccolo principe.", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [100, 3188]}]}, {"id": "ch21p40", "audio": true, "sents": [{"it": "“Anche questa è una cosa troppo dimenticata,” disse la volpe.", "zh": "比如说，猎人们有个仪式，每逢星期四，他们就与村里的姑娘们跳舞，星期四就成了再美妙不过的日子了！", "t": [100, 3662]}, {"it": "“È ciò che rende un giorno diverso dagli altri giorni, un’ora diversa dalle altre ore.", "zh": "比如说，猎人们有个仪式，每逢星期四，他们就与村里的姑娘们跳舞，星期四就成了再美妙不过的日子了！", "t": [3662, 8762]}, {"it": "I miei cacciatori, per esempio, hanno un rito.", "zh": "我也就可以到葡萄园里去闲逛了。", "t": [8762, 12188]}, {"it": "Il giovedì ballano con le ragazze del villaggio.", "zh": "如果猎人跳舞不挑日子，每一天都一样，我就没有假期了。", "t": [12188, 14888]}, {"it": "Allora il giovedì è una giornata meravigliosa!", "zh": "” 于是小王子驯养狐狸了。", "t": [14888, 17662]}, {"it": "E io vado a fare una passeggiata fino alla vigna.", "zh": "小王子要走的时候到了。", "t": [17662, 20362]}, {"it": "Se i cacciatori ballassero quando capita, i giorni sarebbero tutti uguali, e non avrei mai vacanza.”", "zh": "”狐狸说，“……我想哭了。", "t": [20362, 26224]}]}, {"id": "ch21p41", "audio": true, "sents": [{"it": "Così il piccolo principe addomesticò la volpe.", "zh": "” “这就是你的不对了，”小王子说，“我一点也不想伤害你，但你却要我驯养你……” “不错。", "t": [100, 3238]}, {"it": "E quando si avvicinò il momento della partenza:", "zh": "”狐狸说。", "t": [3238, 5813]}]}, {"id": "ch21p42", "audio": true, "sents": [{"it": "“Ah!” disse la volpe...", "zh": "“但你却想哭！", "t": [100, 2012]}, {"it": "“Piangerò.”", "zh": "”小王子说。", "t": [2012, 2637]}]}, {"id": "ch21p43", "audio": true, "sents": [{"it": "“È colpa tua,” disse il piccolo principe, “io non volevo farti soffrire, ma tu mi hai chiesto di addomesticarti...”", "zh": "“那你是一无所获了！", "t": [100, 6512]}]}, {"id": "ch21p44", "audio": true, "sents": [{"it": "“Certo,” disse la volpe.", "zh": "” “我有收获的，”狐狸说，“我得到了小麦的颜色。", "t": [100, 1575]}]}, {"id": "ch21p45", "audio": true, "sents": [{"it": "“Però piangerai!” disse il piccolo principe.", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 3213]}]}, {"id": "ch21p46", "audio": true, "sents": [{"it": "“Certo,” disse la volpe.", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 1575]}]}, {"id": "ch21p47", "audio": true, "sents": [{"it": "“Allora non ci guadagni niente!”", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 1787]}]}, {"id": "ch21p48", "audio": true, "sents": [{"it": "“Ci guadagno,” disse la volpe, “a causa del colore del grano.”", "zh": "然后你回来与我告别，我会送你一桩秘密作为礼物。", "t": [100, 3588]}]}, {"id": "ch21p49", "audio": true, "sents": [{"it": "Poi aggiunse:", "zh": "然后你回来与我告别，我会送你一桩秘密作为礼物。", "t": [100, 1026]}]}, {"id": "ch21p50", "audio": true, "sents": [{"it": "“Vai a rivedere le rose.", "zh": "然后你回来与我告别，我会送你一桩秘密作为礼物。", "t": [100, 1650]}, {"it": "Capirai che la tua è unica al mondo.", "zh": "” 小王子探望玫瑰花们，并对她们说： “你们一点也不像我的玫瑰，你们还无足轻重，没有人驯养你们，你们也没有驯养任何人。", "t": [1650, 3850]}, {"it": "Quando tornerai a salutarmi, ti regalerò un segreto.”", "zh": "” 小王子探望玫瑰花们，并对她们说： “你们一点也不像我的玫瑰，你们还无足轻重，没有人驯养你们，你们也没有驯养任何人。", "t": [3850, 7062]}]}, {"id": "ch21p51", "audio": true, "sents": [{"it": "Il piccolo principe andò a rivedere le rose:", "zh": "” 小王子探望玫瑰花们，并对她们说： “你们一点也不像我的玫瑰，你们还无足轻重，没有人驯养你们，你们也没有驯养任何人。", "t": [100, 2463]}]}, {"id": "ch21p52", "audio": true, "sents": [{"it": "“Non assomigliate affatto alla mia rosa, non siete ancora niente,” disse loro.", "zh": "你们的今天如同我的狐狸的昨天。", "t": [100, 4712]}, {"it": "“Nessuno vi ha addomesticate e voi non avete addomesticato nessuno.", "zh": "昨天的他与千千万万的狐狸一样，但自从我让他做了我的朋友，他就是世上绝无仅有的狐狸了。", "t": [4712, 8725]}, {"it": "Siete com’era la mia volpe.", "zh": "昨天的他与千千万万的狐狸一样，但自从我让他做了我的朋友，他就是世上绝无仅有的狐狸了。", "t": [8725, 10462]}, {"it": "Era solo una volpe uguale a centomila altre.", "zh": "” 玫瑰花们听了心里怪不自在的。", "t": [10462, 13350]}, {"it": "Ma ho fatto di lei la mia amica e ora è unica al mondo.”", "zh": "“你们长得很美，但你们的感情世界一片空白。", "t": [13350, 16625]}]}, {"id": "ch21p53", "audio": true, "sents": [{"it": "Le rose erano molto imbarazzate.", "zh": "“你们长得很美，但你们的感情世界一片空白。", "t": [100, 2162]}]}, {"id": "ch21p54", "audio": true, "sents": [{"it": "“Siete belle, ma siete vuote,” disse ancora.", "zh": "“没有人为你们而死。", "t": [100, 3188]}, {"it": "“Non si può morire per voi.", "zh": "“没有人为你们而死。", "t": [3188, 4938]}, {"it": "Certo, un passante qualsiasi penserebbe che la mia rosa vi assomigli.", "zh": "不错，行人会认为我的玫瑰与你们没有两样，但只有她比你们重要，因为我给她浇了水，我给她盖上花罩，我给她竖起屏风，给她避风挡雨。", "t": [4938, 9438]}, {"it": "Ma lei da sola è più importante di tutte voi, perché è quella che ho innaffiato.", "zh": "不错，行人会认为我的玫瑰与你们没有两样，但只有她比你们重要，因为我给她浇了水，我给她盖上花罩，我给她竖起屏风，给她避风挡雨。", "t": [9438, 14450]}, {"it": "Perché l’ho messa sotto la campana di vetro.", "zh": "我为她杀死了几条毛虫（除了两三条我没杀，要让它们变成蝴蝶），我倾听她的抱怨，或她的吹嘘，有时也看着她默默无语的样子，因为她是我的玫瑰。", "t": [14450, 16962]}, {"it": "Perché l’ho protetta con il paravento.", "zh": "我为她杀死了几条毛虫（除了两三条我没杀，要让它们变成蝴蝶），我倾听她的抱怨，或她的吹嘘，有时也看着她默默无语的样子，因为她是我的玫瑰。", "t": [16962, 19225]}, {"it": "Perché ho ucciso i bruchi (tranne due o tre per le farfalle).", "zh": "我为她杀死了几条毛虫（除了两三条我没杀，要让它们变成蝴蝶），我倾听她的抱怨，或她的吹嘘，有时也看着她默默无语的样子，因为她是我的玫瑰。", "t": [19225, 23050]}, {"it": "Perché l’ho ascoltata lamentarsi, o vantarsi o a volte anche tacere.", "zh": "” 他回到狐狸身边。", "t": [23050, 27312]}, {"it": "Perché è la mia rosa.”", "zh": "” 他回到狐狸身边。", "t": [27312, 28512]}]}, {"id": "ch21p55", "audio": true, "sents": [{"it": "E tornò dalla volpe:", "zh": "“别了。", "t": [100, 1325]}]}, {"id": "ch21p56", "audio": true, "sents": [{"it": "“Addio...” disse.", "zh": "“别了。", "t": [100, 1550]}]}, {"id": "ch21p57", "audio": true, "sents": [{"it": "“Addio,” disse la volpe.", "zh": "“别了。", "t": [100, 1788]}, {"it": "“Ecco il mio segreto.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [1788, 3175]}, {"it": "È molto semplice: si vede solo con il cuore.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [3175, 6175]}, {"it": "L’essenziale è invisibile agli occhi.”", "zh": "” “用眼睛是看不见本质的东西的。", "t": [6175, 8250]}]}, {"id": "ch21p58", "audio": true, "sents": [{"it": "“L’essenziale è invisibile agli occhi,” ripeté il piccolo principe, per tenerlo a mente.", "zh": "” “用眼睛是看不见本质的东西的。", "t": [100, 4912]}]}, {"id": "ch21p59", "audio": true, "sents": [{"it": "“Il tempo che hai perso per la tua rosa è ciò che fa la tua rosa tanto importante.”", "zh": "“你为你的玫瑰失去的时间，使你的玫瑰变得重要了。", "t": [100, 4763]}]}, {"id": "ch21p60", "audio": true, "sents": [{"it": "“Il tempo che ho perso per la mia rosa...” ripeté il piccolo principe, per tenerlo a mente.", "zh": "” “我为我的玫瑰失去的时间，使我的玫瑰……”小王子说道，为了把它记住。", "t": [100, 5162]}]}, {"id": "ch21p61", "audio": true, "sents": [{"it": "“Gli uomini hanno dimenticato questa verità,” disse la volpe.", "zh": "“人忘记了这条真理，”狐狸说，“但你不该忘。", "t": [100, 3625]}, {"it": "“Ma tu non devi dimenticarla.", "zh": "“人忘记了这条真理，”狐狸说，“但你不该忘。", "t": [3625, 5538]}, {"it": "Diventi responsabile per sempre di ciò che hai addomesticato.", "zh": "“人忘记了这条真理，”狐狸说，“但你不该忘。", "t": [5538, 9112]}, {"it": "Tu sei responsabile della tua rosa...”", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [9112, 11275]}]}, {"id": "ch21p62", "audio": true, "sents": [{"it": "“Sono responsabile della mia rosa...” ripeté il piccolo principe, per tenerlo a mente.", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [100, 5100]}]}]}, {"id": "ch22", "title_it": "XXII", "title_zh": "第 22 章", "paras": [{"id": "ch22p00", "audio": true, "sents": [{"it": "“Buongiorno,” disse il piccolo principe.", "zh": "”小王子说。", "t": [100, 2226]}]}, {"id": "ch22p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse l’addetto agli scambi.", "zh": "“你在这儿干什么？", "t": [100, 2387]}]}, {"id": "ch22p02", "audio": true, "sents": [{"it": "“Che cosa fai qui?” disse il piccolo principe.", "zh": "” “我给旅客们分组。", "t": [100, 2800]}]}, {"id": "ch22p03", "audio": true, "sents": [{"it": "“Smisto i viaggiatori, a migliaia,” disse l’addetto agli scambi.", "zh": "”扳道工说。", "t": [100, 4288]}, {"it": "“Mando via i treni che li portano lontano, ora verso destra ora verso sinistra.”", "zh": "“载乘客的火车也由我调度，它们有时开往左方，有时开往右方。", "t": [4288, 9087]}]}, {"id": "ch22p04", "audio": true, "sents": [{"it": "E un rapido tutto illuminato passò rombante come un tuono e fece tremare la cabina dell’addetto agli scambi.", "zh": "“他们行色匆匆。", "t": [100, 6387]}]}, {"id": "ch22p05", "audio": true, "sents": [{"it": "“Vanno proprio di fretta,” disse il piccolo principe.", "zh": "“他们寻找什么？", "t": [100, 3075]}, {"it": "“Che cosa cercano?”", "zh": "” “坐在火车头上的人也不知道他们要寻找什么。", "t": [3075, 4124]}]}, {"id": "ch22p06", "audio": true, "sents": [{"it": "“Neanche l’uomo della locomotiva lo sa,” disse l’ad­detto agli scambi.", "zh": "”扳道工说。", "t": [100, 3762]}]}, {"id": "ch22p07", "audio": true, "sents": [{"it": "E in senso inverso arrivò rombando un secondo rapido illuminato.", "zh": "第二列灯火通明的火车轰隆隆地，从相反的方向奔驰而来。", "t": [100, 4025]}]}, {"id": "ch22p08", "audio": true, "sents": [{"it": "“Sono già di ritorno?” domandò il piccolo principe...", "zh": "”小王子问…… “这列车坐的不是刚才那些人。", "t": [100, 3238]}]}, {"id": "ch22p09", "audio": true, "sents": [{"it": "“Non sono gli stessi,” disse l’addetto agli scambi.", "zh": "”扳道工说。", "t": [100, 3125]}, {"it": "“Questo è uno scambio.”", "zh": "“这是对开的火车。", "t": [3125, 4400]}]}, {"id": "ch22p10", "audio": true, "sents": [{"it": "“Non erano contenti, dove stavano?”", "zh": "” “他们对他们的居住地不满意？", "t": [100, 2387]}]}, {"id": "ch22p11", "audio": true, "sents": [{"it": "“Nessuno è mai contento dove sta,” disse l’addetto allo scambio.", "zh": "” “人总是这山望着那山高的。", "t": [100, 3750]}]}, {"id": "ch22p12", "audio": true, "sents": [{"it": "E come un tuono rombò un terzo rapido illuminato.", "zh": "第三列灯火通明的火车也轰隆隆地响起来了。", "t": [100, 3337]}]}, {"id": "ch22p13", "audio": true, "sents": [{"it": "“Inseguono i primi viaggiatori?” domandò il piccolo principe.", "zh": "“他们在追赶第一批旅客吗？", "t": [100, 3774]}]}, {"id": "ch22p14", "audio": true, "sents": [{"it": "“Non inseguono un bel niente,” disse l’addetto allo scambio.", "zh": "”小王子问。", "t": [100, 3762]}, {"it": "“Là dentro dormono, oppure sbadigliano.", "zh": "“他们从不追赶人，”扳道工说，“他们在车厢里睡大觉或打哈欠，只有孩子们才把鼻子贴在玻璃窗上看外面的世界。", "t": [3762, 6475]}, {"it": "Solo i bambini se ne stanno con il naso incollato al finestrino.”", "zh": "“他们从不追赶人，”扳道工说，“他们在车厢里睡大觉或打哈欠，只有孩子们才把鼻子贴在玻璃窗上看外面的世界。", "t": [6475, 10200]}]}, {"id": "ch22p15", "audio": true, "sents": [{"it": "“Solo i bambini sanno quello che cercano,” fece il piccolo principe.", "zh": "” “只有孩子才知道他们要寻觅什么。", "t": [100, 3975]}, {"it": "“Perdono tempo per una bambola di pezza, che allora diventa importantissima, e se qualcuno gliela porta via piangono...”", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [3975, 10524]}]}, {"id": "ch22p16", "audio": true, "sents": [{"it": "“Sono fortunati,” disse l’addetto allo scambio.", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [100, 2725]}]}]}, {"id": "ch23", "title_it": "XXIII", "title_zh": "第 23 章", "paras": [{"id": "ch23p00", "audio": true, "sents": [{"it": "“Buongiorno,” disse il piccolo principe.", "zh": "”小王子说。", "t": [100, 2226]}]}, {"id": "ch23p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse il negoziante.", "zh": "”商人说。", "t": [100, 2063]}]}, {"id": "ch23p02", "audio": true, "sents": [{"it": "Vendeva pillole speciali che placano la sete.", "zh": "这位商人贩卖解渴的药丸。", "t": [100, 2888]}, {"it": "Ne prendi una alla settimana e non provi più il desiderio di bere.", "zh": "一个星期吃一颗这样的药丸，就不再需要喝水了。", "t": [2888, 6725]}]}, {"id": "ch23p03", "audio": true, "sents": [{"it": "“Perché vendi queste pillole?” disse il piccolo principe.", "zh": "”小王子问。", "t": [100, 3737]}]}, {"id": "ch23p04", "audio": true, "sents": [{"it": "“È un bel risparmio di tempo,” disse il negoziante.", "zh": "“为了节省更多的时间，”商人说，“专家们计算过，每个星期能节省五十三分钟。", "t": [100, 3200]}, {"it": "“Gli esperti hanno calcolato che si guadagnano cinquantatré minuti alla settimana.”", "zh": "” “节省的这五十三分钟，有什么用途？", "t": [3200, 7563]}]}, {"id": "ch23p05", "audio": true, "sents": [{"it": "“E cosa si fa di quei cinquantatré minuti?”", "zh": "” “节省的这五十三分钟，有什么用途？", "t": [100, 2437]}]}, {"id": "ch23p06", "audio": true, "sents": [{"it": "“Quello che si vuole...”", "zh": "” “人可以干自己愿意干的事……” 小王子想：“要是我节省下这五十三分钟，我就要悠闲自在地朝一泓泉水走去……”", "t": [100, 1100]}]}, {"id": "ch23p07", "audio": true, "sents": [{"it": "“Se avessi cinquantatré minuti da spendere,” si disse il piccolo principe, “me ne andrei lentamente verso una fontana...”", "zh": "” “人可以干自己愿意干的事……” 小王子想：“要是我节省下这五十三分钟，我就要悠闲自在地朝一泓泉水走去……”", "t": [100, 6576]}]}]}, {"id": "ch24", "title_it": "XXIV", "title_zh": "第 24 章", "paras": [{"id": "ch24p00", "audio": true, "sents": [{"it": "Erano passati otto giorni da quando avevo avuto il guasto nel deserto, e avevo ascoltato la storia del negoziante bevendo la mia ultima goccia d’acqua:", "zh": "我的飞机在沙漠出故障的第八天，我听到了商人的故事，此时我储存的水已喝完了，一滴不剩。", "t": [100, 8326]}]}, {"id": "ch24p01", "audio": true, "sents": [{"it": "“Ah!” dissi al piccolo principe, “i tuoi ricordi sono proprio belli, ma non ho ancora riparato l’aereo, non ho più niente da bere, e sarei ben felice anch’io di poter camminare pian piano verso una fontana!”", "zh": "你的这些回忆挺美好的，但我还没修好我的飞机，我的水也喝完了，如果我能悠闲自在地向一泓泉水走过去，我也会很幸福快活的！", "t": [100, 12437]}]}, {"id": "ch24p02", "audio": true, "sents": [{"it": "“La mia amica volpe...” mi disse.", "zh": "” “我的朋友狐狸告诉我……” “我的小人儿，别再说狐狸的事了！", "t": [100, 2162]}]}, {"id": "ch24p03", "audio": true, "sents": [{"it": "“Caro il mio ometto, lascia stare la tua volpe!”", "zh": "” “为什么？", "t": [100, 2825]}]}, {"id": "ch24p04", "audio": true, "sents": [{"it": "“Perché?”", "zh": "” “为什么？", "t": [100, 588]}]}, {"id": "ch24p05", "audio": true, "sents": [{"it": "“Perché qui moriremo di sete...”", "zh": "” “为什么？", "t": [100, 1738]}]}, {"id": "ch24p06", "audio": true, "sents": [{"it": "Non capì il mio ragionamento e mi rispose:", "zh": "” “因为我快渴死了……” 他听不懂我说的理由。", "t": [100, 2437]}]}, {"id": "ch24p07", "audio": true, "sents": [{"it": "“È bello avere avuto un amico, anche se devi morire di sete.", "zh": "他说道： “有个朋友真好，哪怕命在旦夕。", "t": [100, 3775]}, {"it": "Io sono molto contento di avere avuto la mia amica volpe...”", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [3775, 6863]}]}, {"id": "ch24p08", "audio": true, "sents": [{"it": "“Non si rende conto del pericolo,” pensai.", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [100, 2700]}, {"it": "“Non ha mai né fame né sete.", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [2700, 4462]}, {"it": "Gli basta un po’ di sole...”", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [4462, 5924]}]}, {"id": "ch24p09", "audio": true, "sents": [{"it": "Ma lui mi guardò e rispose al mio pensiero:", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [100, 2450]}]}, {"id": "ch24p10", "audio": true, "sents": [{"it": "“Anch’io ho sete...", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [100, 1450]}, {"it": "cerchiamo un pozzo...”", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [1450, 2512]}]}, {"id": "ch24p11", "audio": true, "sents": [{"it": "Ebbi un gesto di stanchezza: è assurdo cercare a caso un pozzo nell’immensità del deserto.", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [100, 5825]}, {"it": "Tuttavia ci mettemmo in cammino.", "zh": "在一望无际的沙漠中寻一口井，这不是太荒唐了吗？", "t": [5825, 7612]}]}, {"id": "ch24p12", "audio": true, "sents": [{"it": "Dopo che avemmo camminato per ore, in silenzio, scese la notte, e cominciarono ad accendersi le stelle.", "zh": "但我们还是出发去寻找了。", "t": [100, 6762]}, {"it": "Le scorgevo come in sogno, poiché a causa della sete avevo un po’ di febbre.", "zh": "夜幕降临，天上现出星星。", "t": [6762, 11400]}, {"it": "Nella memoria mi danzavano le parole del piccolo principe:", "zh": "小王子说的话也似乎在我的脑海中跳跃。", "t": [11400, 14575]}]}, {"id": "ch24p13", "audio": true, "sents": [{"it": "“Allora anche tu hai sete?” gli domandai.", "zh": "“你也口渴了吗？", "t": [100, 2612]}]}, {"id": "ch24p14", "audio": true, "sents": [{"it": "Ma non rispose.", "zh": "”我问他。", "t": [100, 1412]}, {"it": "Mi disse soltanto:", "zh": "”我问他。", "t": [1412, 2724]}]}, {"id": "ch24p15", "audio": true, "sents": [{"it": "“L’acqua può essere buona anche per il cuore...”", "zh": "”我问他。", "t": [100, 2188]}]}, {"id": "ch24p16", "audio": true, "sents": [{"it": "Non capii quella risposta, ma tacqui...", "zh": "他不回答我的问题，只简单地对我说： “水对心也有好处……” 我听不懂他的话，但我不做声……我知道不应该问他。", "t": [100, 2862]}, {"it": "Sapevo che non bisognava fargli domande.", "zh": "他不回答我的问题，只简单地对我说： “水对心也有好处……” 我听不懂他的话，但我不做声……我知道不应该问他。", "t": [2862, 5000]}]}, {"id": "ch24p17", "audio": true, "sents": [{"it": "Era stanco.", "zh": "他走乏了，坐了下来。", "t": [100, 1200]}, {"it": "Si sedette.", "zh": "他走乏了，坐了下来。", "t": [1200, 2350]}, {"it": "Mi sedetti accanto a lui.", "zh": "他走乏了，坐了下来。", "t": [2350, 4000]}, {"it": "Poi, dopo un momento di silenzio, disse ancora:", "zh": "我靠着他坐下。", "t": [4000, 7224]}]}, {"id": "ch24p18", "audio": true, "sents": [{"it": "“Le stelle sono belle grazie a un fiore che non vediamo...”", "zh": "沉默了一会，他又说： “星星美丽，因为里面有一朵看不见的花。", "t": [100, 3225]}]}, {"id": "ch24p19", "audio": true, "sents": [{"it": "Risposi “certo” e guardai, senza parlare, le pieghe della sabbia sotto la luna.", "zh": "” 我应了一句：“当然。", "t": [100, 5212]}]}, {"id": "ch24p20", "audio": true, "sents": [{"it": "“Il deserto è bello...” aggiunse.", "zh": "”然后我不做声，看着月光下的起伏的沙丘。", "t": [100, 2324]}]}, {"id": "ch24p21", "audio": true, "sents": [{"it": "Ed era vero.", "zh": "“沙漠真美。", "t": [100, 1062]}, {"it": "Ho sempre amato il deserto.", "zh": "”他又说。", "t": [1062, 2875]}, {"it": "Ti siedi su una duna di sabbia.", "zh": "我素来喜爱沙漠。", "t": [2875, 4975]}, {"it": "Non vedi niente.", "zh": "我们坐在沙丘上。", "t": [4975, 6238]}, {"it": "Non senti niente.", "zh": "我们坐在沙丘上。", "t": [6238, 7650]}, {"it": "E tuttavia qualcosa brilla in silenzio...", "zh": "我们无所见，我们无所闻。", "t": [7650, 9912]}]}, {"id": "ch24p22", "audio": true, "sents": [{"it": "“Ciò che fa bello il deserto,” disse il piccolo principe, “è che da qualche parte nasconde un pozzo...”", "zh": "然而，有什么东西在静静地发光…… “沙漠美丽，因为沙漠的某处隐藏着一口井。", "t": [100, 5500]}]}, {"id": "ch24p23", "audio": true, "sents": [{"it": "E con grande stupore capii d’un tratto il misterioso brillio della sabbia.", "zh": "”小王子说。", "t": [100, 4612]}, {"it": "Da bambino abitavo in una vecchia casa che la leggenda diceva celasse un tesoro.", "zh": "我还是一个小男孩的时候，住在一幢古老大屋里。", "t": [4612, 9388]}, {"it": "Ovviamente nessuno è mai riuscito a trovarlo, né forse l’ha mai cercato.", "zh": "传说里面埋藏着一件宝物。", "t": [9388, 13938]}, {"it": "Ma esso rendeva quella casa come incantata.", "zh": "当然，没有一个人能找得到它。", "t": [13938, 16712]}, {"it": "Il cuore della mia casa nascondeva un segreto...", "zh": "也许甚至没人去找它。", "t": [16712, 19313]}]}, {"id": "ch24p24", "audio": true, "sents": [{"it": "“Sì,” dissi al piccolo principe, “che si tratti della casa, delle stelle o del deserto, quel che fa la loro bellezza è invisibile!”", "zh": "但它像给这幢屋子施了魔法，让它凭空增添了吸引力。", "t": [100, 8200]}]}, {"id": "ch24p25", "audio": true, "sents": [{"it": "“Mi fa piacere,” disse, “che tu sia d’accordo con la mia volpe.”", "zh": "房里埋藏着秘密…… “你说得对，”我对小王子说，“房子也好，星星、沙漠也好，美化它们的东西是肉眼看不见的！", "t": [100, 3574]}]}, {"id": "ch24p26", "audio": true, "sents": [{"it": "Il piccolo principe si stava addormentando, allora lo presi in braccio e mi rimisi in cammino.", "zh": "” “我很欣慰，”他说，“你同意狐狸的看法。", "t": [100, 5775]}, {"it": "Provavo una grande emozione.", "zh": "” 小王子入睡了。", "t": [5775, 7712]}, {"it": "Mi sembrava di reggere un fragile tesoro.", "zh": "我把他抱在怀里，继续走我们的路。", "t": [7712, 10150]}, {"it": "Mi sembrava addirittura che non ci fosse nulla di più fragile sulla Terra.", "zh": "我觉得我抱着一件脆弱的宝物。", "t": [10150, 14475]}, {"it": "Alla luce della luna, guardavo quella fronte pallida, quegli occhi chiusi, quelle ciocche di capelli che tremavano al vento, e mi dicevo: “Io vedo soltanto la scorza.", "zh": "借着银色的月光，我细细看他苍白的前额、闭着的双目、随风抖动的绺绺秀发。", "t": [14475, 24375]}, {"it": "Ciò che è davvero importante è invisibile...”.", "zh": "我心想：“我看见的只是一具躯壳，最重要的东西是看不见的……” 他半张的嘴唇上泛出浅浅的微笑。", "t": [24375, 26600]}]}, {"id": "ch24p27", "audio": true, "sents": [{"it": "Mentre le sue labbra socchiuse accennavano un mezzo sorriso, mi dissi ancora: “La cosa che più mi commuove di questo piccolo principe addormentato è la sua fedeltà a un fiore, è l’immagine di una rosa che brilla dentro di lui come la fiamma di una lampada, anche quando dorme...”.", "zh": "我又想：“这位睡着了的小王子打动了我，而打动了我的是他对花的忠贞。", "t": [100, 16138]}, {"it": "E capii che era ancora più fragile.", "zh": "玫瑰花的倩影如同灯焰，在他心里闪闪发亮，即使是在梦乡……” 我把他想像得更脆弱了。", "t": [16138, 18450]}, {"it": "Bisogna proteggere le lampade: un soffio di vento basta a spegnerle...", "zh": "灯是需要我们小心保护的，一股风就会把它吹灭……我就这样走着，曙光初露时我看见了那口井。", "t": [18450, 22650]}]}, {"id": "ch24p28", "audio": true, "sents": [{"it": "E, camminando così, all’alba trovai il pozzo.", "zh": "灯是需要我们小心保护的，一股风就会把它吹灭……我就这样走着，曙光初露时我看见了那口井。", "t": [100, 3374]}]}]}, {"id": "ch25", "title_it": "XXV", "title_zh": "第 25 章", "paras": [{"id": "ch25p00", "audio": true, "sents": [{"it": "“Gli uomini,” disse il piccolo principe, “salgono sui treni ma non sanno più cosa cercano.", "zh": "“人挤在快车的车厢里，”小王子说，“却不知道他们要寻找什么。", "t": [100, 5538]}, {"it": "Allora si agitano e girano a vuoto...”", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [5538, 7776]}]}, {"id": "ch25p01", "audio": true, "sents": [{"it": "Quindi aggiunse:", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [100, 1138]}]}, {"id": "ch25p02", "audio": true, "sents": [{"it": "“E tutto questo non serve a niente...”", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [100, 2063]}]}, {"id": "ch25p03", "audio": true, "sents": [{"it": "Il pozzo cui eravamo giunti era diverso dai soliti pozzi del Sahara.", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [100, 4188]}, {"it": "I pozzi del Sahara sono semplici buche scavate nella sabbia.", "zh": "撒哈拉沙漠的井是在沙里挖个洞，而我们找到的这口井与村子里的井一样，可是这儿没有一个村子。", "t": [4188, 8012]}, {"it": "Questo era simile al pozzo di un villaggio.", "zh": "我以为我正在做梦。", "t": [8012, 10500]}, {"it": "Ma non c’era alcun villaggio, e credevo di sognare.", "zh": "我以为我正在做梦。", "t": [10500, 13576]}]}, {"id": "ch25p04", "audio": true, "sents": [{"it": "“È strano,” dissi al piccolo principe, “è tutto pronto: la carrucola, il secchio e la corda...”", "zh": "“这就奇了，”我对小王子说，“这井一切齐备：辘轳，水桶，绳子……” 他笑了，抓住绳子，转动辘轳。", "t": [100, 6063]}]}, {"id": "ch25p05", "audio": true, "sents": [{"it": "Lui rise, toccò la corda, fece ruotare la carrucola.", "zh": "辘轳吱吱呀呀地叫唤，活像一只老风信鸡在风长睡时的叫唤。", "t": [100, 3513]}]}, {"id": "ch25p06", "audio": true, "sents": [{"it": "E la carrucola gemette come geme una vecchia banderuola dopo che il vento ha dormito a lungo.", "zh": "“你听，”小王子说，“我们唤醒了这口井。", "t": [100, 5137]}]}, {"id": "ch25p07", "audio": true, "sents": [{"it": "“Lo senti?” disse il piccolo principe, “svegliamo il pozzo e lui canta...”", "zh": "它在唱歌呢……” 我不忍心看他劳力费神。", "t": [100, 4650]}]}, {"id": "ch25p08", "audio": true, "sents": [{"it": "Non volevo che si stancasse:", "zh": "“让我来干吧，”我对他说，“你干这活太重了。", "t": [100, 1750]}]}, {"id": "ch25p09", "audio": true, "sents": [{"it": "“Lascia fare a me,” gli dissi, “per te è troppo pesante.”", "zh": "“让我来干吧，”我对他说，“你干这活太重了。", "t": [100, 3350]}]}, {"id": "ch25p10", "audio": true, "sents": [{"it": "Tirai su adagio il secchio fino al bordo.", "zh": "” 我轻轻把水桶提到井口，垂直放进井内。", "t": [100, 2538]}, {"it": "Lo posai bene in equilibrio.", "zh": "倾听着辘轳的歌声，还看见在荡漾的井水中摇动的太阳。", "t": [2538, 4450]}, {"it": "Nelle mie orecchie durava il canto della puleggia e, nell’acqua che ancora tremava, vedevo tremare il sole.", "zh": "“我渴望的就是这样的水，”小王子说，“让我喝上几口……”我明白他要寻找什么了。", "t": [4450, 10524]}]}, {"id": "ch25p11", "audio": true, "sents": [{"it": "“Ho sete di quell’acqua,” disse il piccolo principe, “dammi da bere...”", "zh": "我把桶举到他的唇边。", "t": [100, 3800]}]}, {"id": "ch25p12", "audio": true, "sents": [{"it": "E capii che cosa aveva cercato!", "zh": "他闭着双目喝水。", "t": [100, 2050]}]}, {"id": "ch25p13", "audio": true, "sents": [{"it": "Gli sollevai il secchio fino alle labbra.", "zh": "水甜得有如过节。", "t": [100, 2488]}, {"it": "Bevve, con gli occhi chiusi.", "zh": "这水不仅是饮料，它还是别的东西。", "t": [2488, 4538]}, {"it": "Era dolce come una festa.", "zh": "它是经过星光下的跋涉，在辘轳的歌声中和在我双臂的努力下诞生的。", "t": [4538, 6250]}, {"it": "Quell’acqua era ben altro che un alimento.", "zh": "它是经过星光下的跋涉，在辘轳的歌声中和在我双臂的努力下诞生的。", "t": [6250, 8588]}, {"it": "Era nata dalla camminata sotto le stelle, dal canto della carrucola, dallo sforzo delle mie braccia.", "zh": "它像礼物一样愉悦心灵。", "t": [8588, 14788]}, {"it": "Era buona per il cuore, come un dono.", "zh": "我还是小男孩的时候，圣诞树上挂的灯、子夜弥撒的音乐、甜蜜的微笑，是我收到的圣诞礼物的光芒。", "t": [14788, 17200]}, {"it": "Quando ero piccolo, erano i lumini dell’albero di Natale, la musica della messa di mezzanotte, la dolcezza dei sorrisi a far risplendere il regalo che ricevevo.", "zh": "“你们这儿的人在一个园里种植五千株玫瑰……但他们却找不到他们寻觅的东西……” “他们没找到。", "t": [17200, 26425]}]}, {"id": "ch25p14", "audio": true, "sents": [{"it": "“Gli uomini di dove stai tu,” disse il piccolo principe, “coltivano cinquemila rose in un giardino e non trovano quello che cercano...”", "zh": "”我说…… “然而他们寻找的东西可以在一朵玫瑰或一点点水里找到的……” “不错。", "t": [100, 7300]}]}, {"id": "ch25p15", "audio": true, "sents": [{"it": "“Non lo trovano...” risposi.", "zh": "”我回答说。", "t": [100, 1826]}]}, {"id": "ch25p16", "audio": true, "sents": [{"it": "“Eppure, quello che cercano potrebbero trovarlo in una sola rosa o in un po’ d’acqua...”", "zh": "小王子又说： “然而肉眼是看不见的，要用心灵去寻找。", "t": [100, 4738]}]}, {"id": "ch25p17", "audio": true, "sents": [{"it": "“Certo,” risposi.", "zh": "” 我喝了水，呼吸畅通了。", "t": [100, 1300]}]}, {"id": "ch25p18", "audio": true, "sents": [{"it": "E il piccolo principe aggiunse:", "zh": "天亮时分，沙子颜色如蜜。", "t": [100, 1888]}]}, {"id": "ch25p19", "audio": true, "sents": [{"it": "“Ma gli occhi sono ciechi.", "zh": "我也喜欢蜜般的颜色。", "t": [100, 1812]}, {"it": "Bisogna cercare con il cuore.”", "zh": "但为什么我的心里总有点不快乐呢？", "t": [1812, 3400]}]}, {"id": "ch25p20", "audio": true, "sents": [{"it": "Avevo bevuto.", "zh": "但为什么我的心里总有点不快乐呢？", "t": [100, 1288]}, {"it": "Respiravo bene.", "zh": "…… “你可要履行诺言啊。", "t": [1288, 2575]}, {"it": "Al sorgere del sole la sabbia ha il colore del miele.", "zh": "…… “你可要履行诺言啊。", "t": [2575, 6062]}, {"it": "Ero felice anche di quel color miele.", "zh": "”小王子轻声对我说，他又靠近我坐着。", "t": [6062, 8312]}, {"it": "Perché mai dovevo essere triste...", "zh": "“什么诺言？", "t": [8312, 10075]}]}, {"id": "ch25p21", "audio": true, "sents": [{"it": "“Devi mantenere la promessa,” mi disse dolcemente il piccolo principe, che di nuovo si era seduto accanto a me.", "zh": "” “你知道的呀……给我的绵羊画一个口罩，我要对我的花儿负责呀！", "t": [100, 5913]}]}, {"id": "ch25p22", "audio": true, "sents": [{"it": "“Quale promessa?”", "zh": "” 我从口袋里掏出画稿。", "t": [100, 1037]}]}, {"id": "ch25p23", "audio": true, "sents": [{"it": "“Sai...", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [100, 838]}, {"it": "la museruola per la pecora...", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [838, 2662]}, {"it": "io sono responsabile di quella rosa!”", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [2662, 4737]}]}, {"id": "ch25p24", "audio": true, "sents": [{"it": "Tirai fuori di tasca i miei disegni.", "zh": "” 我还为我画的猴面包树自鸣得意呢！", "t": [100, 2650]}, {"it": "Il piccolo principe li vide e disse ridendo:", "zh": "” 我还为我画的猴面包树自鸣得意呢！", "t": [2650, 5176]}]}, {"id": "ch25p25", "audio": true, "sents": [{"it": "“I tuoi baobab sembrano un po’ dei cavoli...”", "zh": "“你画的狐狸……它的耳朵……有点像角……太长了！", "t": [100, 2612]}]}, {"id": "ch25p26", "audio": true, "sents": [{"it": "“Oh!”", "zh": "” 他还在笑。", "t": [100, 562]}]}, {"id": "ch25p27", "audio": true, "sents": [{"it": "Io che ero così fiero dei baobab!", "zh": "” 他还在笑。", "t": [100, 2213]}]}, {"id": "ch25p28", "audio": true, "sents": [{"it": "“La tua volpe...", "zh": "“你不公平，小人儿。", "t": [100, 1225]}, {"it": "ha certe orecchie...", "zh": "“你不公平，小人儿。", "t": [1225, 2562]}, {"it": "che sembrano un po’ delle corna...", "zh": "我并不会画画，只会画打开了肚子的蟒蛇和没打开肚子的蟒蛇。", "t": [2562, 4362]}, {"it": "e sono troppo lunghe!”", "zh": "” “啊！", "t": [4362, 5575]}]}, {"id": "ch25p29", "audio": true, "sents": [{"it": "E rise ancora:", "zh": "” “啊！", "t": [100, 1138]}]}, {"id": "ch25p30", "audio": true, "sents": [{"it": "“Sei ingiusto, ometto, io sapevo disegnare soltanto i boa chiusi e i boa aperti.”", "zh": "”他说。", "t": [100, 5524]}]}, {"id": "ch25p31", "audio": true, "sents": [{"it": "“Ma va benissimo, dai,” disse, “i bambini capiscono.”", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [100, 3788]}]}, {"id": "ch25p32", "audio": true, "sents": [{"it": "Disegnai quindi una museruola.", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [100, 2362]}, {"it": "E nel dargliela mi si stringeva il cuore:", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [2362, 4438]}]}, {"id": "ch25p33", "audio": true, "sents": [{"it": "“Hai progetti che io ignoro...”", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [100, 1724]}]}, {"id": "ch25p34", "audio": true, "sents": [{"it": "Ma non mi rispose.", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 1450]}, {"it": "Mi disse:", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [1450, 2200]}]}, {"id": "ch25p35", "audio": true, "sents": [{"it": "“Sai...", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 850]}, {"it": "domani è l’anniversario della mia caduta sulla Terra...”", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [850, 3750]}]}, {"id": "ch25p36", "audio": true, "sents": [{"it": "Poi, dopo un momento di silenzio:", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 2224]}]}, {"id": "ch25p37", "audio": true, "sents": [{"it": "“Ero caduto proprio qui vicino...”", "zh": "不知何故，我有说不出来的惆怅悲哀。", "t": [100, 1776]}]}, {"id": "ch25p38", "audio": true, "sents": [{"it": "E arrossì.", "zh": "不知何故，我有说不出来的惆怅悲哀。", "t": [100, 863]}]}, {"id": "ch25p39", "audio": true, "sents": [{"it": "E di nuovo, senza capirne il motivo, provai una strana pena.", "zh": "不知何故，我有说不出来的惆怅悲哀。", "t": [100, 4275]}, {"it": "Mi sorse però una domanda:", "zh": "我提出了一个问题： “这么说，一个星期之前，认识你的那天早上，你不是偶尔一人来到这远离人烟的沙漠的？", "t": [4275, 5862]}]}, {"id": "ch25p40", "audio": true, "sents": [{"it": "“Allora non è un caso se la mattina in cui ti ho conosciuto, otto giorni fa, te ne andavi in giro da solo, lontano mille miglia da qualunque terra abitata!", "zh": "我提出了一个问题： “这么说，一个星期之前，认识你的那天早上，你不是偶尔一人来到这远离人烟的沙漠的？", "t": [100, 9238]}, {"it": "Tornavi verso il punto dov’eri caduto?”", "zh": "” 小王子的脸又红了。", "t": [9238, 11324]}]}, {"id": "ch25p41", "audio": true, "sents": [{"it": "Di nuovo il piccolo principe arrossì.", "zh": "我犹豫着又问： “也许是为了纪念降落周年？", "t": [100, 2263]}]}, {"id": "ch25p42", "audio": true, "sents": [{"it": "E io aggiunsi, titubante:", "zh": "……” 小王子的脸再次红了。", "t": [100, 1937]}]}, {"id": "ch25p43", "audio": true, "sents": [{"it": "“Era forse a causa dell’anniversario?”", "zh": "他从不回答我提的问题。", "t": [100, 2075]}]}, {"id": "ch25p44", "audio": true, "sents": [{"it": "Di nuovo il piccolo principe arrossì.", "zh": "他从不回答我提的问题。", "t": [100, 2525]}, {"it": "Non rispondeva mai alle domande, ma quando si arrossisce significa “sì”, vero?", "zh": "但一个人脸红，就意味着默认，意味着做了“是的”的回答，对吧？", "t": [2525, 7500]}]}, {"id": "ch25p45", "audio": true, "sents": [{"it": "“Ah!” gli dissi, “ho paura...”", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [100, 2438]}]}, {"id": "ch25p46", "audio": true, "sents": [{"it": "Ma mi rispose:", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [100, 1137]}]}, {"id": "ch25p47", "audio": true, "sents": [{"it": "“Adesso devi lavorare.", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [100, 1662]}, {"it": "Devi tornare al tuo aereo.", "zh": "你该到你的机器旁忙活儿了。", "t": [1662, 3638]}, {"it": "Io ti aspetto qui.", "zh": "你该到你的机器旁忙活儿了。", "t": [3638, 4975]}, {"it": "Torna domani sera...”", "zh": "你该到你的机器旁忙活儿了。", "t": [4975, 6075]}]}, {"id": "ch25p48", "audio": true, "sents": [{"it": "Ma non ero tranquillo.", "zh": "我在这儿等你，明天晚上再来……” 但我不放心。", "t": [100, 1725]}, {"it": "Pensavo alla volpe.", "zh": "我在这儿等你，明天晚上再来……” 但我不放心。", "t": [1725, 3088]}, {"it": "Si corre il rischio di piangere un po’, quando ci si è lasciati addomesticare...", "zh": "我想起了狐狸的事，让别人驯养，难免要掉掉眼泪……", "t": [3088, 7662]}]}]}, {"id": "ch26", "title_it": "XXVI", "title_zh": "第 26 章", "paras": [{"id": "ch26p00", "audio": true, "sents": [{"it": "C’erano, accanto al pozzo, i resti di un vecchio muro di pietra.", "zh": "井旁有一堵断墙残壁。", "t": [100, 4525]}, {"it": "Quando l’indomani sera tornai, dopo aver lavorato, scorsi da lontano il mio piccolo principe seduto là sopra, con le gambe penzoloni.", "zh": "我听见他说： “你不记得了吗？", "t": [4525, 13112]}, {"it": "E lo sentii che parlava:", "zh": "” 无疑有另一个声音回了他的话，因为他反驳说： “没错！", "t": [13112, 14450]}]}, {"id": "ch26p01", "audio": true, "sents": [{"it": "“Ma non te lo ricordi?” diceva.", "zh": "” 无疑有另一个声音回了他的话，因为他反驳说： “没错！", "t": [100, 2400]}, {"it": "“Non è mica qui!”", "zh": "没错！", "t": [2400, 3463]}]}, {"id": "ch26p02", "audio": true, "sents": [{"it": "Probabilmente un’altra voce gli rispose, poiché lui ribatté:", "zh": "没错！", "t": [100, 3675]}]}, {"id": "ch26p03", "audio": true, "sents": [{"it": "“Ma sì, invece!", "zh": "就是这一天，但不是这个地方……” 我向断墙残壁走过去，我看不见也听不见有什么人在那儿。", "t": [100, 1838]}, {"it": "Il giorno è giusto, ma il posto non è questo...”", "zh": "就是这一天，但不是这个地方……” 我向断墙残壁走过去，我看不见也听不见有什么人在那儿。", "t": [1838, 4875]}]}, {"id": "ch26p04", "audio": true, "sents": [{"it": "Continuai ad avvicinarmi al muro.", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [100, 2250]}, {"it": "Non sentivo né vedevo ancora nessuno.", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [2250, 4650]}, {"it": "Tuttavia il piccolo principe di nuovo ribatté:", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [4650, 7175]}]}, {"id": "ch26p05", "audio": true, "sents": [{"it": "“...Certo.", "zh": "你在那儿等我就行了。", "t": [100, 1025]}, {"it": "Guarda dove iniziano le mie impronte sulla sabbia.", "zh": "你在那儿等我就行了。", "t": [1025, 4012]}, {"it": "Non devi fare altro che aspettarmi lì.", "zh": "” 我离开墙才二十米，还是一无所见。", "t": [4012, 6312]}, {"it": "Ci sarò.", "zh": "” 我离开墙才二十米，还是一无所见。", "t": [6312, 7138]}, {"it": "Stanotte.”", "zh": "” 我离开墙才二十米，还是一无所见。", "t": [7138, 7900]}]}, {"id": "ch26p06", "audio": true, "sents": [{"it": "Ero a venti metri dal muro e continuavo a non vedere niente.", "zh": "小王子沉默片刻后又说： “你有毒液吗？", "t": [100, 3463]}]}, {"id": "ch26p07", "audio": true, "sents": [{"it": "Dopo una pausa, il piccolo principe disse ancora:", "zh": "你能肯定不让我经受很久的痛苦？", "t": [100, 3387]}]}, {"id": "ch26p08", "audio": true, "sents": [{"it": "“È un buon veleno, il tuo?", "zh": "” 我停住了脚步，心被揪成一团。", "t": [100, 2125]}, {"it": "Sei sicuro di non farmi soffrire a lungo?”", "zh": "我仍然听不懂他的话。", "t": [2125, 4263]}]}, {"id": "ch26p09", "audio": true, "sents": [{"it": "Mi fermai, con il cuore in gola, ma continuavo a non capire.", "zh": "”他说。", "t": [100, 4026]}]}, {"id": "ch26p10", "audio": true, "sents": [{"it": "“Adesso vattene...” disse.", "zh": "” 我的眼光落到墙根，我吓了一跳！", "t": [100, 2675]}, {"it": "“Voglio scendere!”", "zh": "” 我的眼光落到墙根，我吓了一跳！", "t": [2675, 3700]}]}, {"id": "ch26p11", "audio": true, "sents": [{"it": "Allora abbassai gli occhi ai piedi del muro e sobbalzai!", "zh": "一条黄蛇正仰头朝向小王子。", "t": [100, 3625]}, {"it": "Era lì, ritto verso il piccolo principe, uno di quei serpenti gialli che ammazzano in trenta secondi.", "zh": "我一面伸手到口袋里掏手枪，一面飞步冲过去。", "t": [3625, 10000]}, {"it": "Mi ficcai una mano in tasca per tirar fuori la pistola e presi a correre, ma, al rumore che feci, il serpente scivolò piano nella sabbia, come un rigagnolo d’acqua che muore e, senza affrettarsi troppo, si infilò tra le pietre con un lieve rumore metallico.", "zh": "我及时赶到墙边，用双臂接住我的小人儿。", "t": [10000, 25900]}]}, {"id": "ch26p12", "audio": true, "sents": [{"it": "Giunsi al muro appena in tempo per ricevere fra le braccia il mio ometto, il mio principe, pallido come la neve.", "zh": "” 我解下他从不离身的金围巾，用水湿湿他的太阳穴，给他喝水。", "t": [100, 6400]}]}, {"id": "ch26p13", "audio": true, "sents": [{"it": "“Che storia è questa!", "zh": "现在我不敢再向他提什么问题了。", "t": [100, 1600]}, {"it": "Adesso parli con i serpenti!”", "zh": "他神情凝重地看着我，双臂搂住我的脖子。", "t": [1600, 3437]}]}, {"id": "ch26p14", "audio": true, "sents": [{"it": "Avevo slacciato la sua eterna sciarpa color oro.", "zh": "他神情凝重地看着我，双臂搂住我的脖子。", "t": [100, 2912]}, {"it": "Gli avevo bagnato le tempie e lo avevo fatto bere.", "zh": "我感觉到他的心的狂跳，如同中弹濒死的小鸟。", "t": [2912, 5900]}, {"it": "E adesso non osavo più domandargli nulla.", "zh": "他对我说：“你找到了机器的毛病，我很高兴。", "t": [5900, 8425]}, {"it": "Mi guardò con aria seria e mi mise le braccia intorno al collo.", "zh": "你可以回家了……” “你怎么知道的？", "t": [8425, 12212]}, {"it": "Gli sentivo battere il cuore come quello di un uccello morente dopo che gli hai sparato con la carabina.", "zh": "” 我来找他，正是要告诉他：出乎我的意料，我竟修好了我的飞机。", "t": [12212, 17738]}, {"it": "Mi disse:", "zh": "” 我来找他，正是要告诉他：出乎我的意料，我竟修好了我的飞机。", "t": [17738, 18487]}]}, {"id": "ch26p15", "audio": true, "sents": [{"it": "“Sono contento che tu abbia trovato quel che mancava al tuo aereo.", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [100, 3862]}, {"it": "Adesso potrai tornare a casa...”", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [3862, 5712]}]}, {"id": "ch26p16", "audio": true, "sents": [{"it": "“Come fai a saperlo!”", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [100, 1326]}]}, {"id": "ch26p17", "audio": true, "sents": [{"it": "Venivo proprio ad annunciargli che contro ogni speranza ero riuscito a finire il lavoro!", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [100, 4750]}]}, {"id": "ch26p18", "audio": true, "sents": [{"it": "Non rispose alla mia domanda, ma aggiunse:", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [100, 2687]}]}, {"id": "ch26p19", "audio": true, "sents": [{"it": "“Anch’io oggi torno a casa...”", "zh": "然而我觉得他直往深渊里坠下去，我一点也抓不住他…… 他目光严肃，落到远方。", "t": [100, 1688]}]}, {"id": "ch26p20", "audio": true, "sents": [{"it": "Poi, malinconico:", "zh": "然而我觉得他直往深渊里坠下去，我一点也抓不住他…… 他目光严肃，落到远方。", "t": [100, 1750]}]}, {"id": "ch26p21", "audio": true, "sents": [{"it": "“È molto più lontano...", "zh": "然而我觉得他直往深渊里坠下去，我一点也抓不住他…… 他目光严肃，落到远方。", "t": [100, 1512]}, {"it": "è molto più complicato...”", "zh": "然而我觉得他直往深渊里坠下去，我一点也抓不住他…… 他目光严肃，落到远方。", "t": [1512, 2862]}]}, {"id": "ch26p22", "audio": true, "sents": [{"it": "Sentivo che stava succedendo qualcosa di straordinario.", "zh": "“我有你的绵羊，我有给绵羊住的箱子。", "t": [100, 3562]}, {"it": "Lo strinsi fra le braccia, come fosse un bambino piccolo, e tuttavia mi sembrava che precipitasse in un abisso senza che potessi far nulla per trattenerlo...", "zh": "我感觉到他的身体逐渐恢复了温暖。", "t": [3562, 12338]}]}, {"id": "ch26p23", "audio": true, "sents": [{"it": "Aveva lo sguardo serio, perso lontano:", "zh": "他温和地笑笑： “今晚我会更害怕！", "t": [100, 2700]}]}, {"id": "ch26p24", "audio": true, "sents": [{"it": "“Ho la tua pecora.", "zh": "他温和地笑笑： “今晚我会更害怕！", "t": [100, 1350]}, {"it": "E ho la cassa per la pecora.", "zh": "” 我又一次体会到无可奈何的感觉。", "t": [1350, 3075]}, {"it": "E ho la museruola...”", "zh": "” 我又一次体会到无可奈何的感觉。", "t": [3075, 4188]}]}, {"id": "ch26p25", "audio": true, "sents": [{"it": "E sorrise con malinconia.", "zh": "我全身冰冷。", "t": [100, 1712]}]}, {"id": "ch26p26", "audio": true, "sents": [{"it": "Aspettai a lungo.", "zh": "我知道，听不见他的笑声，我会忍受不了的。", "t": [100, 1388]}, {"it": "Sentivo che pian piano si rianimava.", "zh": "我知道，听不见他的笑声，我会忍受不了的。", "t": [1388, 3387]}]}, {"id": "ch26p27", "audio": true, "sents": [{"it": "“Ometto, hai avuto paura...”", "zh": "他的笑声对我来说，如同沙漠里的一口井。", "t": [100, 2063]}]}, {"id": "ch26p28", "audio": true, "sents": [{"it": "Certo che aveva avuto paura!", "zh": "他的笑声对我来说，如同沙漠里的一口井。", "t": [100, 1938]}, {"it": "Ma rise dolcemente:", "zh": "他的笑声对我来说，如同沙漠里的一口井。", "t": [1938, 3275]}]}, {"id": "ch26p29", "audio": true, "sents": [{"it": "“Avrò molta più paura stasera...”", "zh": "“小人儿，我还想听到你的笑声……” 但他对我说： “今夜是我到这儿的一周年。", "t": [100, 1775]}]}, {"id": "ch26p30", "audio": true, "sents": [{"it": "Di nuovo fui raggelato da una sensazione d’ineluttabilità.", "zh": "“小人儿，我还想听到你的笑声……” 但他对我说： “今夜是我到这儿的一周年。", "t": [100, 3850]}, {"it": "E capii che non sopportavo l’idea di non udire più quella risata.", "zh": "我的星星正好在我去年降落处的正上方……” “小人儿，蛇呀、约会呀、星星的故事，莫非都是一场噩梦？", "t": [3850, 7675]}, {"it": "Per me era come una sorgente nel deserto.", "zh": "我的星星正好在我去年降落处的正上方……” “小人儿，蛇呀、约会呀、星星的故事，莫非都是一场噩梦？", "t": [7675, 10050]}]}, {"id": "ch26p31", "audio": true, "sents": [{"it": "“Ometto, voglio ancora sentirti ridere...”", "zh": "……” 但他不回答我的问题。", "t": [100, 2575]}]}, {"id": "ch26p32", "audio": true, "sents": [{"it": "Ma lui mi disse:", "zh": "……” 但他不回答我的问题。", "t": [100, 1175]}]}, {"id": "ch26p33", "audio": true, "sents": [{"it": "“Stanotte sarà trascorso un anno.", "zh": "……” 但他不回答我的问题。", "t": [100, 2312]}, {"it": "La mia stella si troverà proprio sopra il punto in cui sono caduto l’anno scorso...”", "zh": "他对我说： “最重要的东西，是肉眼看不到的……” “当然……” “花儿也是这样，如果你爱上了一朵长在一颗星星里的花儿，夜里看看星空，你会觉得甜蜜。", "t": [2312, 6975]}]}, {"id": "ch26p34", "audio": true, "sents": [{"it": "“Ometto, è vero che questa storia del serpente e dell’appuntamento e della stella è soltanto un brutto sogno...”", "zh": "他对我说： “最重要的东西，是肉眼看不到的……” “当然……” “花儿也是这样，如果你爱上了一朵长在一颗星星里的花儿，夜里看看星空，你会觉得甜蜜。", "t": [100, 6313]}]}, {"id": "ch26p35", "audio": true, "sents": [{"it": "Ma non rispose alla mia domanda.", "zh": "所有的星星都像开了花。", "t": [100, 2062]}, {"it": "Mi disse:", "zh": "” “不错……” “水也是这样。", "t": [2062, 2813]}]}, {"id": "ch26p36", "audio": true, "sents": [{"it": "“Ciò che è importante non si vede...”", "zh": "” “不错……” “水也是这样。", "t": [100, 1787]}]}, {"id": "ch26p37", "audio": true, "sents": [{"it": "“Certo...”", "zh": "” “不错……” “水也是这样。", "t": [100, 775]}]}, {"id": "ch26p38", "audio": true, "sents": [{"it": "“È come per la rosa.", "zh": "你给我喝的水，有了辘轳和绳子，水就如同音乐……你记得……它是甘甜的。", "t": [100, 1538]}, {"it": "Se ami una rosa che si trova su una stella, di notte è bello guardare il cielo.", "zh": "你给我喝的水，有了辘轳和绳子，水就如同音乐……你记得……它是甘甜的。", "t": [1538, 6262]}, {"it": "Tutte le stelle sono fiorite.”", "zh": "” “不错。", "t": [6262, 7887]}]}, {"id": "ch26p39", "audio": true, "sents": [{"it": "“Certo...”", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [100, 775]}]}, {"id": "ch26p40", "audio": true, "sents": [{"it": "“È come per l’acqua.", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [100, 1450]}, {"it": "Quella che mi hai dato da bere era come una musica, per via della carrucola e della corda...", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [1450, 6400]}, {"it": "ti ricordi...", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [6400, 7350]}, {"it": "com’era buona.”", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [7350, 8188]}]}, {"id": "ch26p41", "audio": true, "sents": [{"it": "“Certo...”", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [100, 775]}]}, {"id": "ch26p42", "audio": true, "sents": [{"it": "“Di notte, ricordati di guardare le stelle.", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [100, 2962]}, {"it": "Dove sto io è troppo piccolo perché possa mostrarti dove si trova la mia.", "zh": "然后我会赠给你一份礼物……” 他还在笑。", "t": [2962, 7412]}, {"it": "Meglio così.", "zh": "“啊，小人儿，小人儿，我喜欢听你的笑声！", "t": [7412, 8525]}, {"it": "La mia stella sarà per te una stella qualsiasi, e allora ti farà piacere guardarle tutte...", "zh": "” “这正是我给你的礼物……这就和水一样……” “你想说什么？", "t": [8525, 13862]}, {"it": "Saranno tutte tue amiche.", "zh": "” “这正是我给你的礼物……这就和水一样……” “你想说什么？", "t": [13862, 15550]}, {"it": "E poi ti farò un regalo...”", "zh": "” “不同的人有不同的星星。", "t": [15550, 16963]}]}, {"id": "ch26p43", "audio": true, "sents": [{"it": "Rise ancora.", "zh": "” “不同的人有不同的星星。", "t": [100, 1037]}]}, {"id": "ch26p44", "audio": true, "sents": [{"it": "“Ah!, ometto, ometto, come mi piace udire questa risata!”", "zh": "” “不同的人有不同的星星。", "t": [100, 4038]}]}, {"id": "ch26p45", "audio": true, "sents": [{"it": "“E infatti sarà il mio regalo...", "zh": "星星是旅行的人的向导，星星只是其他人的小灯，星星是学者研究的问题，星星是我说过的那个商人的金子。", "t": [100, 2188]}, {"it": "sarà come per l’acqua...”", "zh": "星星是旅行的人的向导，星星只是其他人的小灯，星星是学者研究的问题，星星是我说过的那个商人的金子。", "t": [2188, 3450]}]}, {"id": "ch26p46", "audio": true, "sents": [{"it": "“Che cosa vuoi dire?”", "zh": "但所有的星星都沉默不语。", "t": [100, 1188]}]}, {"id": "ch26p47", "audio": true, "sents": [{"it": "“Le stelle sono diverse da persona a persona.", "zh": "但所有的星星都沉默不语。", "t": [100, 2862]}, {"it": "Per chi viaggia le stelle sono una guida.", "zh": "你的那颗星星是别人没有的……” “你想说什么？", "t": [2862, 5200]}, {"it": "Per altri sono soltanto lucine.", "zh": "你的那颗星星是别人没有的……” “你想说什么？", "t": [5200, 7362]}, {"it": "Per altri ancora, come gli scienziati, sono problemi.", "zh": "” “既然我住在天上一颗星星里，既然我在其中一颗星星里笑，这就如同所有的星星都在冲你笑，你就拥有无数会笑的星星了！", "t": [7362, 11088]}, {"it": "Per il mio uomo d’affari erano oro.", "zh": "” “既然我住在天上一颗星星里，既然我在其中一颗星星里笑，这就如同所有的星星都在冲你笑，你就拥有无数会笑的星星了！", "t": [11088, 13175]}, {"it": "Ma tutte queste stelle tacciono.", "zh": "” “既然我住在天上一颗星星里，既然我在其中一颗星星里笑，这就如同所有的星星都在冲你笑，你就拥有无数会笑的星星了！", "t": [13175, 15112]}, {"it": "Tu invece avrai stelle che saranno qualcosa di completamente diverso...”", "zh": "” 他还在笑。", "t": [15112, 18800]}]}, {"id": "ch26p48", "audio": true, "sents": [{"it": "“Cosa vuoi dire?”", "zh": "“你得到了安慰之后（人常常自我安慰），你会为认识我而高兴。", "t": [100, 1000]}]}, {"id": "ch26p49", "audio": true, "sents": [{"it": "“Quando la notte guarderai il cielo, poiché io abiterò in una di esse, e riderò in una di esse, per te sarà come se ridessero tutte le stelle.", "zh": "你会成为我永远的朋友，你会想与我一起笑。", "t": [100, 8388]}, {"it": "Avrai stelle che sapranno ridere!”", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [8388, 10113]}]}, {"id": "ch26p50", "audio": true, "sents": [{"it": "E rise ancora.", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [100, 1113]}]}, {"id": "ch26p51", "audio": true, "sents": [{"it": "“E quando ti sarai consolato (poiché ci si consola sempre), sarai contento di avermi conosciuto.", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [100, 5962]}, {"it": "Sarai sempre mio amico.", "zh": "’他们会以为你神经出了毛病。", "t": [5962, 7562]}, {"it": "Avrai voglia di ridere con me.", "zh": "’他们会以为你神经出了毛病。", "t": [7562, 9300]}, {"it": "E ogni tanto aprirai la finestra, così, per puro piacere...", "zh": "看来是我捉弄了你了……” 他还在笑。", "t": [9300, 13450]}, {"it": "E i tuoi amici saranno stupiti di vederti ridere guardando il cielo.", "zh": "“这样一来，我给你的不是星星，而是一大批会笑的小铃铛……” 他还在笑。", "t": [13450, 17288]}, {"it": "Allora tu gli dirai: ‘Sì, le stelle mi fanno sempre ridere!’.", "zh": "然后他收敛了笑容： “今晚……你知道……你不要来了。", "t": [17288, 21625]}, {"it": "E penseranno che sei pazzo.", "zh": "然后他收敛了笑容： “今晚……你知道……你不要来了。", "t": [21625, 23488]}, {"it": "Ti avrò fatto un bello scherzetto...”", "zh": "” “我不会离开你的。", "t": [23488, 25237]}]}, {"id": "ch26p52", "audio": true, "sents": [{"it": "E rise ancora.", "zh": "” “我不会离开你的。", "t": [100, 1113]}]}, {"id": "ch26p53", "audio": true, "sents": [{"it": "“Sarà come se, invece delle stelle, ti avessi dato tanti sonagli che sanno ridere...”", "zh": "” “我会很难看的……会像个死人，别来看我的死了的样子，没有必要。", "t": [100, 4887]}]}, {"id": "ch26p54", "audio": true, "sents": [{"it": "E rise ancora.", "zh": "” “我不会离开你的。", "t": [100, 1375]}, {"it": "Poi tornò serio:", "zh": "” 他露出忧心忡忡的神色。", "t": [1375, 2576]}]}, {"id": "ch26p55", "audio": true, "sents": [{"it": "“Stanotte...", "zh": "” 他露出忧心忡忡的神色。", "t": [100, 1125]}, {"it": "sai...", "zh": "” 他露出忧心忡忡的神色。", "t": [1125, 1788]}, {"it": "non venire.”", "zh": "” 他露出忧心忡忡的神色。", "t": [1788, 2537]}]}, {"id": "ch26p56", "audio": true, "sents": [{"it": "“Non ti lascerò.”", "zh": "” 他露出忧心忡忡的神色。", "t": [100, 975]}]}, {"id": "ch26p57", "audio": true, "sents": [{"it": "“Sembrerà che stia male...", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 1662]}, {"it": "che muoia.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [1662, 2588]}, {"it": "È così.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [2588, 3488]}, {"it": "Non venire a vedere.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [3488, 4862]}, {"it": "Non è il caso...”", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [4862, 5925]}]}, {"id": "ch26p58", "audio": true, "sents": [{"it": "“Non ti lascerò.”", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 975]}]}, {"id": "ch26p59", "audio": true, "sents": [{"it": "Ma era pensieroso.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 1338]}]}, {"id": "ch26p60", "audio": true, "sents": [{"it": "“Te lo dico...", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 1150]}, {"it": "per via del serpente.", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [1150, 2675]}, {"it": "Non deve morderti...", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [2675, 4100]}, {"it": "I serpenti sono cattivi.", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [4100, 5950]}, {"it": "Possono mordere per il semplice gusto di farlo...”", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [5950, 8513]}]}, {"id": "ch26p61", "audio": true, "sents": [{"it": "“Non ti lascerò.”", "zh": "他是悄悄走的。", "t": [100, 975]}]}, {"id": "ch26p62", "audio": true, "sents": [{"it": "Ma qualcosa lo tranquillizzò:", "zh": "他是悄悄走的。", "t": [100, 1763]}]}, {"id": "ch26p63", "audio": true, "sents": [{"it": "“È vero che non hanno veleno per un secondo morso...”", "zh": "他大步走着，步子迈得又大又坚决。", "t": [100, 2612]}]}, {"id": "ch26p64", "audio": true, "sents": [{"it": "Quella notte non lo vidi mettersi in cammino.", "zh": "他见了我，只说了一句：“呀，你在这儿……” 他牵住我的手。", "t": [100, 2700]}, {"it": "Se n’era andato senza far rumore.", "zh": "他见了我，只说了一句：“呀，你在这儿……” 他牵住我的手。", "t": [2700, 4900]}, {"it": "Quando riuscii a raggiungerlo, camminava deciso, di buon passo.", "zh": "然后他苦恼地说： “你不该来的。", "t": [4900, 9200]}, {"it": "Mi disse soltanto:", "zh": "你会难过的。", "t": [9200, 10512]}]}, {"id": "ch26p65", "audio": true, "sents": [{"it": "“Ah!", "zh": "你会难过的。", "t": [100, 750]}, {"it": "Sei qui...”", "zh": "我会像个死人，其实我不是真死……” 我不做声。", "t": [750, 1463]}]}, {"id": "ch26p66", "audio": true, "sents": [{"it": "E mi prese per mano.", "zh": "我会像个死人，其实我不是真死……” 我不做声。", "t": [100, 1488]}, {"it": "Ma si tormentava ancora:", "zh": "我会像个死人，其实我不是真死……” 我不做声。", "t": [1488, 2987]}]}, {"id": "ch26p67", "audio": true, "sents": [{"it": "“Hai fatto male.", "zh": "“你知道吧，路途太远，我拖不动这副皮囊，它太沉了。", "t": [100, 1262]}, {"it": "Sarai triste.", "zh": "“你知道吧，路途太远，我拖不动这副皮囊，它太沉了。", "t": [1262, 2462]}, {"it": "Sembrerà che sia morto e non sarà vero...”", "zh": "“你知道吧，路途太远，我拖不动这副皮囊，它太沉了。", "t": [2462, 4612]}]}, {"id": "ch26p68", "audio": true, "sents": [{"it": "Io tacevo.", "zh": "” 我不做声。", "t": [100, 962]}]}, {"id": "ch26p69", "audio": true, "sents": [{"it": "“Capisci, è troppo lontano.", "zh": "” 我不做声。", "t": [100, 2212]}, {"it": "Non posso portarmi dietro questo corpo.", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [2212, 4738]}, {"it": "È troppo pesante.”", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [4738, 5837]}]}, {"id": "ch26p70", "audio": true, "sents": [{"it": "Io tacevo.", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [100, 962]}]}, {"id": "ch26p71", "audio": true, "sents": [{"it": "“Ma sarà come una vecchia scorza abbandonata.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [100, 2812]}, {"it": "Non sono tristi, le vecchie scorze...”", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [2812, 5074]}]}, {"id": "ch26p72", "audio": true, "sents": [{"it": "Io tacevo.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [100, 962]}]}, {"id": "ch26p73", "audio": true, "sents": [{"it": "Era un po’ scoraggiato.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [100, 1625]}, {"it": "Ma fece ancora uno sforzo:", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [1625, 3288]}]}, {"id": "ch26p74", "audio": true, "sents": [{"it": "“Sarà carino, sai.", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [100, 2112]}, {"it": "Anch’io guarderò le stelle.", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [2112, 3975]}, {"it": "Tutte le stelle saranno pozzi con una carrucola arrugginita.", "zh": "“那会是多有趣的事情！", "t": [3975, 7612]}, {"it": "Tutte le stelle mi verseranno da bere...”", "zh": "“那会是多有趣的事情！", "t": [7612, 9587]}]}, {"id": "ch26p75", "audio": true, "sents": [{"it": "Io tacevo.", "zh": "“那会是多有趣的事情！", "t": [100, 962]}]}, {"id": "ch26p76", "audio": true, "sents": [{"it": "“Sarà divertentissimo!", "zh": "你会有五亿个小铃铛，我有五亿口井……” 他也不做声了，因为他哭了…… “就在这儿吧。", "t": [100, 1750]}, {"it": "Tu avrai cinquecento milioni di sonagli, io avrò cinquecento milioni di sorgenti...”", "zh": "你会有五亿个小铃铛，我有五亿口井……” 他也不做声了，因为他哭了…… “就在这儿吧。", "t": [1750, 6638]}]}, {"id": "ch26p77", "audio": true, "sents": [{"it": "E anche lui tacque, perché piangeva...", "zh": "你让我独自走一步。", "t": [100, 2425]}]}, {"id": "ch26p78", "audio": true, "sents": [{"it": "“Ecco, siamo arrivati.", "zh": "” 他坐了下来，因为他害怕了。", "t": [100, 2050]}, {"it": "Lasciami fare un passo da solo.”", "zh": "他还说： “你知道……我的花……我要对她负责！", "t": [2050, 3738]}]}, {"id": "ch26p79", "audio": true, "sents": [{"it": "E si sedette perché aveva paura.", "zh": "他还说： “你知道……我的花……我要对她负责！", "t": [100, 1963]}]}, {"id": "ch26p80", "audio": true, "sents": [{"it": "Disse ancora:", "zh": "她弱不禁风！", "t": [100, 1124]}]}, {"id": "ch26p81", "audio": true, "sents": [{"it": "“Sai...", "zh": "她弱不禁风！", "t": [100, 750]}, {"it": "io sono responsabile della mia rosa!", "zh": "她一无所有！", "t": [750, 3038]}, {"it": "E lei è così delicata!", "zh": "她一无所有！", "t": [3038, 4788]}, {"it": "È così ingenua.", "zh": "只凭四根刺保护自己，抵御世上的侵害……” 我瘫坐在地上。", "t": [4788, 6162]}, {"it": "Per proteggersi dal mondo ha solo quattro spine da niente...”", "zh": "因为我站不住了。", "t": [6162, 9537]}]}, {"id": "ch26p82", "audio": true, "sents": [{"it": "Mi sedetti perché non riuscivo più a stare in piedi.", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [100, 3338]}, {"it": "Disse:", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [3338, 4026]}]}, {"id": "ch26p83", "audio": true, "sents": [{"it": "“Ecco...", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [100, 950]}, {"it": "È tutto...”", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [950, 1588]}]}, {"id": "ch26p84", "audio": true, "sents": [{"it": "Esitò ancora un istante, poi si rialzò.", "zh": "而我不能动弹。", "t": [100, 3238]}, {"it": "Fece un passo.", "zh": "而我不能动弹。", "t": [3238, 4438]}, {"it": "Io non potevo muovermi.", "zh": "他的脚踝边闪了一道黄光。", "t": [4438, 5813]}]}, {"id": "ch26p85", "audio": true, "sents": [{"it": "Ci fu solo un lampo giallo vicino alla sua caviglia.", "zh": "他凝然不动。", "t": [100, 3138]}, {"it": "Rimase un secondo immobile.", "zh": "好一会儿之后，他像大树倒地似的倒下。", "t": [3138, 5088]}, {"it": "Non gridò.", "zh": "好一会儿之后，他像大树倒地似的倒下。", "t": [5088, 6062]}, {"it": "Cadde piano come cade un albero.", "zh": "因为这儿是沙地，他倒下去的时候，一点声音都没有。", "t": [6062, 8188]}, {"it": "Non fece neppure rumore, a causa della sabbia.", "zh": "因为这儿是沙地，他倒下去的时候，一点声音都没有。", "t": [8188, 11024]}]}]}, {"id": "ch27", "title_it": "XXVII", "title_zh": "第 27 章", "paras": [{"id": "ch27p00", "audio": true, "sents": [{"it": "E adesso, certo, sono già passati sei anni...", "zh": "当然，这已是六年前的事了……我从来没对别人讲过这个故事。", "t": [100, 3675]}, {"it": "Non avevo mai raccontato questa storia.", "zh": "当然，这已是六年前的事了……我从来没对别人讲过这个故事。", "t": [3675, 6062]}, {"it": "Gli amici che ho ritrovato sono stati felici di rivedermi vivo.", "zh": "我的同事们看见我活着回来，都替我庆幸。", "t": [6062, 9600]}, {"it": "Ero triste, ma dicevo: “È la stanchezza...”.", "zh": "我神色哀伤，但我告诉他们：“这是因为累……” 现在，我的离愁别绪已经减轻了一些。", "t": [9600, 12600]}]}, {"id": "ch27p01", "audio": true, "sents": [{"it": "Adesso mi sono un po’ consolato.", "zh": "我神色哀伤，但我告诉他们：“这是因为累……” 现在，我的离愁别绪已经减轻了一些。", "t": [100, 2238]}, {"it": "Insomma...", "zh": "也就是说……还没有完全消除。", "t": [2238, 3088]}, {"it": "non del tutto.", "zh": "也就是说……还没有完全消除。", "t": [3088, 4200]}, {"it": "Ma so che è tornato sul suo pianeta, perché al sorgere del sole non ho ritrovato il corpo.", "zh": "我很明白，他回他的星球去了，因为天亮时我没找到他的尸体。", "t": [4200, 9450]}, {"it": "Non era un corpo tanto pesante...", "zh": "我很明白，他回他的星球去了，因为天亮时我没找到他的尸体。", "t": [9450, 11538]}, {"it": "E di notte mi piace ascoltare le stelle.", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [11538, 14050]}, {"it": "Sono come cinquecento milioni di sonagli...", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [14050, 16400]}]}, {"id": "ch27p02", "audio": true, "sents": [{"it": "C’è però un fatto importante.", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [100, 2000]}, {"it": "Ho dimenticato di aggiungere la cinghia di cuoio alla museruola che ho disegnato per il piccolo principe!", "zh": "他别想把口罩套上羊嘴了。", "t": [2000, 7638]}, {"it": "Non avrà potuto metterla alla pecora.", "zh": "我于是想：“他的星球发生了什么事呢？", "t": [7638, 9938]}, {"it": "Allora mi chiedo: “Che cosa è successo sul suo pianeta?", "zh": "绵羊很可能吃了花儿……” 有时我又想：“一定不会的！", "t": [9938, 13562]}, {"it": "Forse la pecora ha mangiato la rosa...?”.", "zh": "绵羊很可能吃了花儿……” 有时我又想：“一定不会的！", "t": [13562, 15663]}]}, {"id": "ch27p03", "audio": true, "sents": [{"it": "A volte mi dico: “Sicuramente no!", "zh": "小王子每天夜里把他的花儿罩在玻璃罩里，他一定会看管好他的绵羊……”于是我放心了，天上所有的星星都温和地微笑。", "t": [100, 2612]}, {"it": "Ogni sera il piccolo principe copre la rosa con la campana di vetro e tiene d’occhio la pecora...”.", "zh": "小王子每天夜里把他的花儿罩在玻璃罩里，他一定会看管好他的绵羊……”于是我放心了，天上所有的星星都温和地微笑。", "t": [2612, 8225]}, {"it": "Allora sono felice.", "zh": "有时我想：“人总免不了有疏忽大意的时候，这就够糟的了！", "t": [8225, 9688]}, {"it": "E tutte le stelle ridono dolcemente.", "zh": "有时我想：“人总免不了有疏忽大意的时候，这就够糟的了！", "t": [9688, 11800]}]}, {"id": "ch27p04", "audio": true, "sents": [{"it": "Altre volte mi dico: “Prima o poi capita a tutti di distrarsi!", "zh": "要是有天晚上他忘了给花罩上玻璃罩，或者绵羊在夜里悄悄地溜出来呢……”于是，铃铛全变成了泪珠…… 这件事始终是无法解开的谜。", "t": [100, 4312]}, {"it": "Una sera ha dimenticato la campana di vetro, oppure la pecora è uscita senza far rumore durante la notte...”.", "zh": "要是有天晚上他忘了给花罩上玻璃罩，或者绵羊在夜里悄悄地溜出来呢……”于是，铃铛全变成了泪珠…… 这件事始终是无法解开的谜。", "t": [4312, 10738]}, {"it": "Allora i sonagli si trasformano in lacrime!...", "zh": "在宇宙中不知哪个角落，我们不认识的绵羊有没有吃掉一朵玫瑰花，你们——喜爱小王子的人，和我一样，看法绝不相同…… 请你们仰望星空吧。", "t": [10738, 13276]}]}, {"id": "ch27p05", "audio": true, "sents": [{"it": "È un mistero enorme.", "zh": "在宇宙中不知哪个角落，我们不认识的绵羊有没有吃掉一朵玫瑰花，你们——喜爱小王子的人，和我一样，看法绝不相同…… 请你们仰望星空吧。", "t": [100, 1625]}, {"it": "Per voi che come me amate il piccolo principe, tutto nell’universo cambia se da qualche parte, non si sa dove, una pecora che non conosciamo ha mangiato una rosa oppure no...", "zh": "请你们问问自己：绵羊有没有吃掉花儿？", "t": [1625, 11513]}]}, {"id": "ch27p06", "audio": true, "sents": [{"it": "Guardate il cielo.", "zh": "你们就会看到，天上所有的星星发生了变化…… 没有一个大人明白，弄清楚这个问题有多重要！", "t": [100, 1300]}, {"it": "Domandatevi: “La pecora ha mangiato o non ha mangiato il fiore?”.", "zh": "你们就会看到，天上所有的星星发生了变化…… 没有一个大人明白，弄清楚这个问题有多重要！", "t": [1300, 5162]}, {"it": "E vedrete come tutto è diverso...", "zh": "我认为这幅图画是世界上最凄美的图画了。", "t": [5162, 6926]}]}, {"id": "ch27p07", "audio": true, "sents": [{"it": "E nessun adulto capirà mai quanto è importante!", "zh": "它与前一幅的画面一样。", "t": [100, 2900]}]}, {"id": "ch27p08", "audio": true, "sents": [{"it": "Questo è per me il paesaggio più bello e più triste del mondo.", "zh": "我再一次画它，是为了让你们好好地看看它。", "t": [100, 3662]}, {"it": "È lo stesso paesaggio della pagina precedente, ma l’ho disegnato un’altra volta per mostrarvelo bene.", "zh": "小王子就是在这里出现在地球上的，然后又是从这里离开了地球。", "t": [3662, 9475]}, {"it": "Qui il piccolo principe è apparso sulla Terra e qui è scomparso.", "zh": "请你们仔细看清楚这幅画，有朝一日你们到沙漠，到非洲旅行，才能认出这地方来。", "t": [9475, 13387]}]}, {"id": "ch27p09", "audio": true, "sents": [{"it": "Guardate attentamente questo paesaggio per essere sicuri di riconoscerlo, se un giorno doveste viaggiare in Africa, nel deserto.", "zh": "如果你经过这个地方，我恳求你们，别匆忙离去，请在那颗星下稍待片刻！", "t": [100, 7712]}, {"it": "E se vi capitasse di passare di lì, vi scongiuro, non tirate dritto, fermatevi un poco sotto la stella!", "zh": "如果有个孩子向你走过来；如果他笑吟吟的；如果他长着一头金发；如果你向他提问题，他不回答；你们就会猜到他是谁了。", "t": [7712, 14275]}, {"it": "Se allora vi viene incontro un bambino, se ride, se ha i capelli d’oro, se non risponde alle domande, voi sapete chi è.", "zh": "果真如此，请你们行行好！", "t": [14275, 21488]}, {"it": "Allora siate gentili, non lasciatemi alla mia tristezza: scrivetemi che è tornato...", "zh": "别眼睁睁看着我为思念他而悲伤，别坐视不理，别无动于衷：请你们快点写信告诉我，他回来了…… 【注释】 [1] 美国的一个州。", "t": [21488, 26500]}]}]}]}